use std::collections::HashMap;
use std::hash::Hash;
use sequence_sums::sum;

/// Given a mapping from identifiers to sequences of numeric values,
/// return a new mapping that associates each identifier with the sum
/// of its sequence of values.
///
/// The function is generic over the key type `K` and value type `T`.
/// `K` must be cloneable and hashable (so it can be used as a HashMap key
/// and inserted into the result). `T` must implement `Default`, `Clone` and
/// `Add<Output = T>` so the `sequence-sums::sum` helper can produce a zero
/// for empty sequences and add values together.
///
/// Example:
/// let mut input: HashMap<&str, Vec<i32>> = HashMap::new();
/// input.insert("a", vec![1, 2, 3]);
/// input.insert("b", vec![]);
/// let out = sum_sequences(&input);
/// assert_eq!(out.get("a"), Some(&6));
/// assert_eq!(out.get("b"), Some(&0));
pub fn sum_sequences<K, T>(input: &HashMap<K, Vec<T>>) -> HashMap<K, T>
where
    K: Eq + Hash + Clone,
    T: std::ops::Add<Output = T> + Default + Clone,
{
    let mut result = HashMap::with_capacity(input.len());
    for (key, seq) in input {
        // clone the sequence's items for the iterator; `sum` consumes an iterator
        // of T and returns the aggregated T (Default used for empty sequences).
        let s = sum(seq.iter().cloned());
        result.insert(key.clone(), s);
    }
    result
}

