/// Compute the mean of selected cells in a 2D table.
///
/// - `table`: slice of rows; each row is a slice of f64 values (row-major).
/// - `rows` (var1): indices of rows to include.
/// - `cols` (var0): indices of columns to include.
///
/// Behavior:
/// - Out-of-range row/column indices are ignored.
/// - Non-finite values (NaN, +/-Inf) are ignored.
/// - Returns `None` if there are no valid values to average.
pub fn mean_selected_cells(
    table: &[Vec<f64>],
    rows: &[usize],
    cols: &[usize],
) -> Option<f64> {
    let mut sum = 0.0f64;
    let mut count: usize = 0;

    for &r in rows {
        if let Some(row) = table.get(r) {
            for &c in cols {
                if let Some(&v) = row.get(c) {
                    if v.is_finite() {
                        sum += v;
                        count += 1;
                    }
                }
            }
        }
    }

    if count == 0 {
        None
    } else {
        Some(sum / (count as f64))
    }
}

