pub fn compute_average_for_subset(
    data: &Array2<f64>,
    rows: &[usize],
    cols: &[usize],
) -> Option<f64> {
    // Validate indices
    for &row in rows {
        assert!(
            row < data.nrows(),
            "Row index {} is out of bounds (max: {})",
            row,
            data.nrows() - 1
        );
    }
    for &col in cols {
        assert!(
            col < data.ncols(),
            "Column index {} is out of bounds (max: {})",
            col,
            data.ncols() - 1
