fn remove_elements<T>(arr: &mut [Vec<T>], var0: usize, var1: usize) {
    if var1 > 1 || arr.is_empty() {
        panic!("var1 must be 0 (for rows) or 1 (for columns)");
    }

    // If var1 is 0, we operate on rows
    if var1 == 0 {
        // Keep every row except for every var0-th
        *arr = arr.iter()
            .enumerate()
            .filter(|(i, _)| i % var0 != 0)
            .map(|(_, v)| v.clone())
