        // Transpose the array to facilitate column-wise deletion
        let transposed: Vec<Vec<T>> = (0..arr[0].len())
            .map(|i| arr.iter().map(|row| row[i].clone()).collect())
            .collect();

        // Keep every column except for every var0-th
