use ndarray::{Array, Axis};

/// Deletes elements from an array along the specified dimension, 
/// removing every nth element.
///
/// # Arguments
///
/// * `arr0`: The input array.
/// * `var0`: The interval at which elements are removed.
/// * `var1`: The dimension along which elements are removed.
///
/// # Returns
///
/// The resulting array after removing elements.
pub fn delete_elements(arr0: Array<i32, 2>, var0: usize, var1: usize) -> Array<i32, 2> {
    let dim = arr0.dim();
    let mut result = arr0.clone();

    if var1 == 0 {
        // Remove elements along the first dimension (rows)
        result = Array::from_shape_vec(
            (dim.0 - (dim.0 / var0), dim.1),
            result
                .axis_iter(Axis(0))
                .enumerate()
                .filter_map(|(i, row)| if i % var0 != 0 { Some(row) } else { None })
                .flatten()
                .collect(),
        )
        .unwrap();
    } else if var1 == 1 {
        // Remove elements along the second dimension (columns)
        result = Array::from_shape_vec(
            (dim.0, dim.1 - (dim.1 / var0)),
            result
                .axis_iter(Axis(1))
                .enumerate()
                .filter_map(|(i, col)| if i % var0 != 0 { Some(col) } else { None })
                .flatten()
                .collect(),
        )
        .unwrap();
    }

    result
}

fn main() {
    let arr0 = Array::from_shape_vec(
        (5, 5),
        (0..25).map(|x| x as i32).collect(),
    )
    .unwrap();

    println!("Original array:");
    println!("{:?}", arr0);

    let result = delete_elements(arr0, 2, 0);

    println!("Array after removing elements:");
    println!("{:?}", result);
}
```

