use std::collections::HashMap;
use std::hash::Hash;

/// A tiny map-comprehension macro:
/// Usage: map_comp!(for key in iterable => value_expr)
/// The value expression is cloned for each inserted key, so V must implement Clone.
macro_rules! map_comp {
    (for $key:ident in $iter:expr => $val:expr) => {{
        let mut __map: ::std::collections::HashMap<_, _> = ::std::collections::HashMap::new();
        for $key in $iter {
            __map.insert($key, $val.clone());
        }
        __map
    }};
}

/// Create a new associative mapping by iterating over `var0` to use its elements as keys
/// and assigning `var1` as the value for each, using the `map_comp!` comprehension.
///
/// Example:
/// let keys = vec!["a", "b", "c"];
/// let value = 42;
/// let map = build_map_from_keys(keys, value);
pub fn build_map_from_keys<K, V, I>(var0: I, var1: V) -> HashMap<K, V>
where
    K: Eq + Hash,
    V: Clone,
    I: IntoIterator<Item = K>,
{
    map_comp!(for k in var0.into_iter() => var1)
}

