    let order_map: HashMap<&str, usize> = name_order
        .iter()
        .enumerate()
        .map(|(index, name)| (*name, index))
        .collect();

    // Separate ordered and unordered rows
    let mut ordered_rows: Vec<Option<HashMap<String, String>>> = vec![None; name_order.len()];
    let mut unordered_rows = Vec::new();

    for row in data {
        if let Some(name) = row.get("name") {
            if let Some(&position) = order_map.get(name.as_str()) {
                ordered_rows[position] = Some(row);
            } else {
                unordered_rows.push(row);
            }
        } else {
            unordered_rows.push(row);
        }
    }

    // Collect results: first the ordered rows (filtering None), then unordered
    let mut result: Vec<HashMap<String, String>> = ordered_rows
        .into_iter()
        .filter_map(|opt| opt)
        .collect();

    result.extend(unordered_rows);
    result
