fn filter_records_by_max_c(records: Vec<Record>) -> Vec<Record> {
    use std::collections::HashMap;

    let mut grouped: HashMap<(String, String), i32> = HashMap::new();

    // First pass: find max C for each (a, b)
    for record in records {
        let key = (record.a.clone(), record.b.clone());
        let current_max = grouped.entry(key).or_insert(record.c);
        if record.c > *current_max {
            *current_max = record.c;
        }
    }

    // Second pass: collect records with max C
    let mut result = Vec::new();
    for record in records {
        let key = (record.a.clone(), record.b.clone());
        if let Some(max_c) = grouped.get(&key) {
            if record.c == *max_c {
                result.push(record);
            }
        }
    }

    result
}
