```rust
/// Normalize each row of `input_data` in-place so that each row sums to exactly 1.
///
/// Behavior:
/// - Empty rows are left unchanged.
/// - If a row's sum is 0 or not finite (NaN/Inf), the row is left unchanged to avoid division by zero.
/// - Otherwise each element is divided by the row sum. To make the row sum exactly 1 (accounting for
///   floating-point rounding), the last element of the row is set to `1.0 - sum_of_normalized_prefix`.
///
/// Example:
/// let mut data = vec![vec![1.0, 1.0, 2.0], vec![0.0, 0.0], vec![3.0]];
/// normalize_rows_in_place(&mut data);
/// // data[0] == [0.25, 0.25, 0.5], data[1] unchanged, data[2] == [1.0]
pub fn normalize_rows_in_place(input_data: &mut [Vec<f64>]) {
    for row in input_data.iter_mut() {
        match row.len() {
            0 => continue, // nothing to do for empty row
            1 => {
                // Single element row: if finite, set to 1.0 (unless it's NaN/Inf)
                let v = row[0];
                if v.is_finite() && v != 0.0 {
                    row[0] = 1.0;
                } else if v == 0.0 {
                    // leave as is (sum is 0)
                } // otherwise leave NaN/Inf unchanged
                continue;
            }
            _ => {}
        }

        // Compute the (floating-point) sum
        let sum: f64 = row.iter().copied().sum();

        // Skip rows with zero/invalid sum to avoid division by zero or propagating NaNs/Infs
        if !(sum.is_finite() && sum != 0.0) {
            continue;
        }

        // Normalize all but the last element, accumulate their normalized sum.
        let last_index = row.len() - 1;
        let mut acc: f64 = 0.0;
        for i in 0..last_index {
            let normalized = row[i] / sum;
            row[i] = normalized;
            acc += normalized;
        }

        // Set last element so the row sums exactly to 1.0 (within float rounding).
        row[last_index] = 1.0 - acc;
    }
}

