Here is a self-contained Rust function that assigns each element in a list its rank (dense, 1-based) without sorting the list more than once. It sorts an index vector (so the original list order is preserved) and then walks the sorted indices to assign ranks; equal values receive the same rank.

```rust
/// Return dense 1-based ranks for the elements of `lst0`.
/// Equal elements receive the same rank. The function sorts the list at most once.
///
/// Example:
///   let v = vec![30, 10, 20, 20];
///   assert_eq!(ranks(&v), vec![3, 1, 2, 2]);
pub fn ranks<T: Ord>(lst0: &[T]) -> Vec<usize> {
    let n = lst0.len();
    let mut idx: Vec<usize> = (0..n).collect();

    // Sort indices by the values they point to (single sort).
    idx.sort_by(|&i, &j| lst0[i].cmp(&lst0[j]));

    // Prepare result vector and walk sorted indices to assign ranks.
    let mut ranks = vec![0usize; n];
    if n == 0 {
        return ranks;
    }

    let mut current_rank = 1usize;
    ranks[idx[0]] = current_rank;
    for k in 1..n {
        if lst0[idx[k]] != lst0[idx[k - 1]] {
            current_rank += 1;
        }
        ranks[idx[k]] = current_rank;
    }

    ranks
}

