pub fn assign_ranks<T: Ord + Clone>(lst0: &[T]) -> Vec<usize> {
    // Create a vector of (value, original_index) pairs
    let indexed: Vec<(T, usize)> = lst0.iter()
        .cloned()
        .enumerate()
        .map(|(i, v)| (v, i))
