        assert_eq!(result[0].id, 1);
        assert_eq!(result[0].name, "Bob");
        assert_eq!(result[1].id, 2);
        assert_eq!(result[1].name, "Charlie");
        assert_eq!(result[2].id, 3);
        assert_eq!(result[2].name, "Alice");
    }

    #[test]
