/// Given two sequences of numeric lists of equal length, calculate the sum of 
/// the outer products of each pair of corresponding lists.
///
/// # Arguments
/// * `seq1` - A slice of slices containing the first sequence of numeric values
/// * `seq2` - A slice of slices containing the second sequence of numeric values
///
/// # Returns
/// A 2D vector containing the sum of all outer products
///
/// # Panics
/// Panics if the sequences have different lengths or if any pair of corresponding
/// lists have incompatible dimensions for outer product calculation
pub fn sum_outer_products<T>(seq1: &[&[T]], seq2: &[&[T]]) -> Vec<Vec<T>>
where
    T: num_traits::Num + Clone + Copy + std::ops::Add<Output = T> + std::ops::Mul<Output = T>,
{
    assert_eq!(
        seq1.len(),
        seq2.len(),
        "Sequences must have equal length"
    );

    if seq1.is_empty() {
        return Vec::new();
    }

    // Initialize result with zeros based on dimensions of first pair
    let first_outer = outer_sum::outer_product(seq1[0], seq2[0]);
    let rows = first_outer.len();
    let cols = if rows > 0 { first_outer[0].len() } else { 0 };

    let mut result = vec![vec![T::zero(); cols]; rows];

    // Add the first outer product
    for i in 0..rows {
        for j in 0..cols {
            result[i][j] = result[i][j] + first_outer[i][j];
        }
    }

    // Add remaining outer products
    for k in 1..seq1.len() {
        let outer = outer_sum::outer_product(seq1[k], seq2[k]);
        for i in 0..rows {
            for j in 0..cols {
                result[i][j] = result[i][j] + outer[i][j];
            }
        }
    }

    result
}

