        //           [2*3, 2*4]   [6, 8]
        assert_eq!(result.shape(), &[2, 2]);
        assert_eq!(result[[0, 0]], 3.0);
        assert_eq!(result[[0, 1]], 4.0);
        assert_eq!(result[[1, 0]], 6.0);
        assert_eq!(result[[1, 1]], 8.0);
