Code:

```rust
use std::collections::{HashMap, HashSet};

/// One-hot-encode all categorical (non-numeric) columns in df0.
///
/// Input:
/// - df0: slice of rows, each row is a HashMap<column_name, cell_value> (all values as strings)
///
/// Output:
/// - Vec of rows (HashMap<String, String>) where categorical columns have been replaced by
///   binary columns named "{col}__{label}" containing "0" or "1".
///
/// Notes:
/// - Numeric columns (all values parseable as f64) are kept unchanged.
/// - Missing keys in a row are treated as the empty string "".
/// - Label and column names are sanitized to replace whitespace with '_' and remove '/' characters.
pub fn onehot_encode_df(
    df0: &[HashMap<String, String>],
) -> Vec<HashMap<String, String>> {
    // 1) collect all column names
    let mut col_names: Vec<String> = Vec::new();
    {
        let mut seen = HashSet::new();
        for row in df0 {
            for k in row.keys() {
                if seen.insert(k.clone()) {
                    col_names.push(k.clone());
                }
            }
        }
    }

    // 2) gather values per column and detect numeric vs categorical
    let mut col_values: HashMap<String, Vec<String>> = HashMap::new();
    for col in &col_names {
        col_values.insert(col.clone(), Vec::new());
    }
    for row in df0 {
        for col in &col_names {
            let v = row.get(col).cloned().unwrap_or_else(|| "".to_string());
            col_values.get_mut(col).unwrap().push(v);
        }
    }

    // Helper to check if all non-empty values in a column parse as f64
    fn is_column_numeric(values: &[String]) -> bool {
        for v in values.iter() {
            let s = v.trim();
            if s.is_empty() {
                continue; // ignore missing as numeric-compatible
            }
            if s.parse::<f64>().is_err() {
                return false;
            }
        }
        true
    }

    // 3) For each categorical column, collect unique labels in order of first occurrence
    let mut categorical_cols: Vec<String> = Vec::new();
    let mut unique_labels: HashMap<String, Vec<String>> = HashMap::new();

    for col in &col_names {
        let vals = col_values.get(col).unwrap();
        if !is_column_numeric(vals) {
            categorical_cols.push(col.clone());
            let mut seen = HashSet::new();
            let mut labels = Vec::new();
            for v in vals {
                let label = v.clone();
                if seen.insert(label.clone()) {
                    labels.push(label);
                }
            }
            unique_labels.insert(col.clone(), labels);
        }
    }

    // 4) produce new rows with one-hot columns
    fn sanitize_name(s: &str) -> String {
        s.replace(char::is_whitespace, "_")
         .replace("/", "_")
         .replace("\\", "_")
    }

    let mut out: Vec<HashMap<String, String>> = Vec::with_capacity(df0.len());

    for (row_idx, row) in df0.iter().enumerate() {
        let mut new_row: HashMap<String, String> = HashMap::new();

        // Keep numeric columns unchanged
        for col in &col_names {
            if !categorical_cols.contains(col) {
                if let Some(v) = row.get(col) {
                    new_row.insert(col.clone(), v.clone());
                } else {
                    new_row.insert(col.clone(), "".to_string());
                }
            }
        }

        // For each categorical column, add one-hot columns
        for cat_col in &categorical_cols {
            let labels = &unique_labels[cat_col];
            // value for this row (empty string if missing)
            let value = row.get(cat_col).cloned().unwrap_or_else(|| "".to_string());
            for label in labels {
                let col_name = format!("{}__{}", sanitize_name(cat_col), sanitize_name(label));
                let bit = if &value == label { "1" } else { "0" };
                new_row.insert(col_name, bit.to_string());
            }
        }

        out.push(new_row);
    }

    out
}

