pub fn one_hot_encode_categorical_columns(df0: DataFrame) -> Result<DataFrame, PolarsError> {
    // Create a vector to hold the processed columns
    let mut processed_columns: Vec<Series> = Vec::new();

    // Track which columns we've already processed (to avoid duplicates)
    let mut processed_col_names: Vec<&str> = Vec::new();

    // Iterate through each column in the DataFrame
    for column in df0.get_columns() {
        let col_name = column.name().as_str();

        // Check if this column contains categorical data
        let is_categorical = matches!(
            column.dtype(),
            DataType::String | DataType::Categorical(None, Default) | DataType::Utf8
        );

        if is_categorical {
            // Skip if we've already processed this column (shouldn't happen, but just in case)
            if processed_col_names.contains(&col_name) {
                continue;
            }

            // Extract the categorical values as strings
            let cat_values: Vec<&str> = column
                .str()?
                .into_iter()
                .map(|opt| opt.unwrap_or(""))
                .collect();

            // Create a OneHotEncoder and fit it to the data
            let encoder = OneHotEncoder::new(&cat_values);

            // Transform the data to get one-hot encoded vectors
            let encoded_vectors: Vec<Vec<u8>> = cat_values
                .iter()
                .map(|val| encoder.transform(val))
                .collect();

            // Get the unique categories from the encoder
            let categories = encoder.categories();

            // Create a Series for each category
            for (i, category) in categories.iter().enumerate() {
                let binary_values: Vec<u8> = encoded_vectors
                    .iter()
                    .map(|vec| vec[i])
                    .collect();

                // Create the new column name: original_column_category
                let new_col_name = format!("{}_{}", col_name, category);

                let new_series = Series::new(&new_col_name, binary_values);
                processed_columns.push(new_series);
            }

            processed_col_names.push(col_name);
        } else {
            // For non-categorical columns, keep them as-is
            processed_columns.push(column.clone());
        }
    }

    // Combine all processed columns into a new DataFrame
    DataFrame::new(processed_columns)
