use std::cmp::{Reverse, Ordering};
use std::collections::BinaryHeap;

/// Wrapper giving a total ordering for f64 using total_cmp,
/// so f64 can be used in a BinaryHeap safely (including -0.0 / +0.0 / NaN handling).
#[derive(Copy, Clone, Debug)]
struct FloatOrd(f64);

impl PartialEq for FloatOrd {
    fn eq(&self, other: &Self) -> bool {
        self.0.to_bits() == other.0.to_bits()
    }
}
impl Eq for FloatOrd {}

impl PartialOrd for FloatOrd {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}
impl Ord for FloatOrd {
    fn cmp(&self, other: &Self) -> Ordering {
        // total_cmp is stable and gives a total ordering for IEEE-754 floats
        self.0.total_cmp(&other.0)
    }
}

/// Example item type. Replace or adapt this to your actual element type.
#[derive(Debug)]
struct Item {
    var0: f64,
    // other fields...
}

/// Return the indices of the top `n` elements (largest var0) from `lst0`.
/// The returned Vec is sorted in descending order by var0 (largest first).
///
/// - lst0: slice of items (indexing is returned relative to this slice)
/// - n: how many top indices to return (if n == 0 returns empty Vec)
///
/// Complexity: O(len(lst0) * log n) time, O(n) additional memory.
fn top_n_indices_var0(lst0: &[Item], n: usize) -> Vec<usize> {
    if n == 0 || lst0.is_empty() {
        return Vec::new();
    }

    // BinaryHeap is a max-heap; we want to keep the N largest items,
    // so we store Reverse<(FloatOrd, usize)> so that the heap's "max" is the smallest of the N kept items.
    let mut heap: BinaryHeap<Reverse<(FloatOrd, usize)>> = BinaryHeap::with_capacity(n + 1);

    for (i, item) in lst0.iter().enumerate() {
        let f = FloatOrd(item.var0);
        if heap.len() < n {
            heap.push(Reverse((f, i)));
        } else {
            // smallest among current top N is at heap.peek()
            let smallest = heap.peek().unwrap().0 .0;
            if f > smallest {
                // replace the smallest kept element
                heap.pop();
                heap.push(Reverse((f, i)));
            }
        }
    }

    // Collect and sort descending by var0 (largest first)
    let mut tmp: Vec<(f64, usize)> = heap.into_iter()
        .map(|Reverse((f, idx))| (f.0, idx))
        .collect();

    tmp.sort_by(|a, b| b.0.total_cmp(&a.0)); // descending
    tmp.into_iter().map(|(_, idx)| idx).collect()
}

// Example usage
fn main() {
    let lst0 = vec![
        Item { var0: 1.2 },
        Item { var0: 5.0 },
        Item { var0: 3.3 },
        Item { var0: 5.0 }, // equal value; order among equals will be by sorting stability (index not considered)
        Item { var0: -2.0 },
        Item { var0: 10.0 },
    ];

    let top3 = top_n_indices_var0(&lst0, 3);
    println!("Top 3 indices by var0: {:?}", top3); // should include indices of values 10.0, 5.0, 5.0 (or 10,5,2 etc.)
}
```

