use std::collections::HashMap;
use std::hash::Hash;

/// Generate a new map by matching each entry from `first` to its corresponding value in `second`.
///
/// - `first`: HashMap<K, I>  (maps keys K -> intermediate keys I)
/// - `second`: HashMap<I, V> (maps intermediate keys I -> final values V)
/// - Returns: HashMap<K, V>  (maps K -> V for every K whose intermediate key exists in `second`)
///
/// Entries in `first` whose intermediate key is not present in `second` are skipped.
///
/// Example:
/// let mut a = HashMap::new();
/// a.insert("apple", 1);
/// a.insert("banana", 2);
/// let mut b = HashMap::new();
/// b.insert(1, "red");
/// b.insert(2, "yellow");
/// let res = match_mappings(&a, &b);
/// // res: { "apple" => "red", "banana" => "yellow" }
pub fn match_mappings<K, I, V>(
    first: &HashMap<K, I>,
    second: &HashMap<I, V>,
) -> HashMap<K, V>
where
    K: Eq + Hash + Clone,
    I: Eq + Hash + Clone,
    V: Clone,
{
    let mut out = HashMap::with_capacity(first.len());
    for (k, inter) in first {
        if let Some(v) = second.get(inter) {
            out.insert(k.clone(), v.clone());
        }
    }
    out
}
