use std::collections::HashMap;

/// Generates a new mapping by matching each key from the first map
/// to its corresponding value in the second map.
///
/// # Arguments
/// * `source_map` - The mapping containing keys to look up
/// * `value_map` - The mapping containing values to retrieve
///
/// # Returns
/// A new HashMap where keys from source_map are mapped to their
/// corresponding values from value_map. Keys not found in value_map
/// are skipped.
///
/// # Example
/// ```
/// let source = [("a", "key1"), ("b", "key2")].iter().cloned().collect();
/// let values = [("key1", 100), ("key2", 200)].iter().cloned().collect();
/// let result = match_and_map(source, values);
/// // result: {("a", 100), ("b", 200)}
/// ```
fn match_and_map<K, V1, V2>(
    source_map: HashMap<K, V1>,
    value_map: HashMap<V1, V2>,
) -> HashMap<K, V2>
where
    K: Eq + std::hash::Hash + Clone,
    V1: Eq + std::hash::Hash,
    V2: Clone,
{
    source_map
        .iter()
        .filter_map(|(key, intermediate_value)| {
            value_map
                .get(intermediate_value)
                .map(|final_value| (key.clone(), final_value.clone()))
        })
        .collect()
}

// Example usage
fn main() {
    // Create source mapping: user_id -> role_id
    let source_map: HashMap<&str, i32> = [
        ("alice", 1),
        ("bob", 2),
        ("charlie", 1),
    ]
    .iter()
    .cloned()
    .collect();

    // Create value mapping: role_id -> role_name
    let value_map: HashMap<i32, &str> = [
        (1, "admin"),
        (2, "user"),
    ]
    .iter()
    .cloned()
    .collect();

    // Match and map
    let result = match_and_map(source_map, value_map);

    // Print results
    for (user, role) in result {
        println!("{} -> {}", user, role);
    }
    // Output:
    // alice -> admin
    // bob -> user
    // charlie -> admin
}
```

