        name_opt.map(|name| {
            let mut result = String::new();
            let mut depth = 0;

            for ch in name.chars() {
                match ch {
                    '(' => depth += 1,
                    ')' => depth = depth.saturating_sub(1),
                    _ if depth == 0 => result.push(ch),
                    _ => {}
