/// A tiny local helper module that provides "inclusive-range" checking.
/// (You can replace this with an external crate named `inclusive-range-indices`
/// if you prefer; this keeps the example self-contained.)
mod inclusive_range_indices {
    /// Return true if `value` lies in the inclusive range defined by `a` and `b`.
    /// The order of `a` and `b` does not matter (the function treats the smaller
    /// as the lower bound and the larger as the upper bound).
    pub fn in_inclusive_range<T: PartialOrd>(value: &T, a: &T, b: &T) -> bool {
        let (low, high) = if *a <= *b { (a, b) } else { (b, a) };
        *value >= *low && *value <= *high
    }
}

/// Return the indices of elements in `seq` whose values lie within the inclusive
/// range defined by `bound1` and `bound2`.
///
/// - `seq`: a slice of values to search
/// - `bound1`, `bound2`: the two inclusive bounds (order does not matter)
///
/// The returned Vec<usize> contains the indices (0-based) of matching elements.
pub fn indices_within_inclusive_range<T: PartialOrd>(seq: &[T], bound1: T, bound2: T) -> Vec<usize> {
    seq.iter()
        .enumerate()
        .filter_map(|(i, v)| {
            if inclusive_range_indices::in_inclusive_range(v, &bound1, &bound2) {
                Some(i)
            } else {
                None
            }
        })
        .collect()
}

