/// Group the rows in `rows` by the value in `keys` (column var0).
/// For each distinct key produce a single row whose columns are the sums
/// of the corresponding columns across rows in that group.
///
/// - `keys`: slice of length N with the grouping key for each row.
/// - `rows`: slice of length N of rows, each row is a Vec<T> with the same length.
///
/// Returns a tuple (unique_keys, summed_rows) where:
/// - `unique_keys` is Vec<K> with one entry per group (preserving first-seen order),
/// - `summed_rows` is Vec<Vec<T>> with one summed row per group.
///
/// Example:
/// let keys = vec!["a", "b", "a"];
/// let rows = vec![vec![1.0, 2.0], vec![3.0, 4.0], vec![5.0, 6.0]];
/// let (uniq, sums) = group_rows_by_var0(&keys, &rows);
/// // uniq == ["a", "b"]
/// // sums == [[6.0, 8.0], [3.0, 4.0]]
pub fn group_rows_by_var0<K, T>(keys: &[K], rows: &[Vec<T>]) -> (Vec<K>, Vec<Vec<T>>)
where
    K: Eq + Hash + Clone,
    T: Copy + AddAssign + Default,
{
    assert_eq!(
        keys.len(),
        rows.len(),
        "keys and rows must have the same length"
    );

    if rows.is_empty() {
        return (Vec::new(), Vec::new());
    }

    let ncols = rows[0].len();
    for r in rows {
        assert_eq!(r.len(), ncols, "all rows must have same number of columns");
    }

    // Transform rows -> column-wise vectors, so we can group-sum each column using groupby_sum.
    let mut cols: Vec<Vec<T>> = vec![Vec::with_capacity(rows.len()); ncols];
    for row in rows {
        for (j, v) in row.iter().enumerate() {
            cols[j].push(*v);
        }
    }

    // We'll store the unique keys returned by the first column aggregation and
    // assert subsequent columns produce the same key order.
    let mut out_keys: Option<Vec<K>> = None;
    let mut out_cols: Vec<Vec<T>> = Vec::with_capacity(ncols);

    for col in cols.iter() {
        let (k, sums) = groupby_sum::groupby_sum(keys, col);
        if let Some(ref existing) = out_keys {
            assert_eq!(existing, &k, "group order mismatch between columns");
        } else {
            out_keys = Some(k);
        }
        out_cols.push(sums);
    }

    let out_keys = out_keys.unwrap_or_default();
    if out_cols.is_empty() {
        return (out_keys, Vec::new());
    }

    // Transpose out_cols (ncols x ngroups) -> rows (ngroups x ncols)
    let ngroups = out_cols[0].len();
    let mut out_rows = vec![vec![T::default(); ncols]; ngroups];
    for (col_idx, col) in out_cols.into_iter().enumerate() {
        for (group_idx, value) in col.into_iter().enumerate() {
            out_rows[group_idx][col_idx] = value;
        }
