/// ```
fn extract_text_subset(entries: &[&str], start: usize, end: usize) -> Vec<&str> {
    // Validate indices
    assert!(
        start <= end,
        "Start index ({}) must be less than or equal to end index ({})",
        start,
        end
    );
    assert!(
        end <= entries.len(),
        "End index ({}) is out of bounds for slice of length {}",
        end,
        entries.len()
    );

    // Create a SliceExtractor and extract the subset
    let extractor = SliceExtractor::new(entries);
    extractor.extract(start, end).to_vec()
