use missingness::Missingness;

fn percentage_missing(df0: &[Vec<Option<String>>]) -> Vec<f64> {
    // Get the number of columns
    let num_cols = if df0.is_empty() { 0 } else { df0[0].len() };

    // Initialize a vector to hold the count of missing entries for each column
    let mut missing_counts = vec![0; num_cols];
    let mut total_counts = vec![0; num_cols];

    // Iterate through each row in the dataset
    for row in df0 {
        for (col_index, value) in row.iter().enumerate() {
            total_counts[col_index] += 1;  // Count total entries
            if value.is_none() {
                missing_counts[col_index] += 1;  // Count missing entries
            }
        }
    }

    // Calculate the percentage of missing entries for each column
    let percentages: Vec<f64> = total_counts
        .iter()
        .enumerate()
        .map(|(index, &total)| {
            if total == 0 {
                0.0  // Avoid division by zero if there are no entries
            } else {
                (missing_counts[index] as f64 / total as f64) * 100.0
            }
        })
        .collect();

    percentages
}

