pub fn find_longest_texts(text_values: Vec<Vec<String>>) -> Vec<String> {
    // Create a ColumnWidths instance to track the maximum width of each column.
    let mut column_widths = ColumnWidths::new();

    // Iterate over each row in the 2D list.
