use std::collections::HashMap;
use std::hash::Hash;
use std::ops::AddAssign;

/// Sum values for each key across all maps in `lst0`, then return a Vec of (key, summed_value)
/// sorted by the summed values in descending order.
///
/// - K: key type (must be hashable, comparable for equality, and cloneable)
/// - V: value type (must support `+=`, have a default zero, be cloneable and comparable)
///
/// Example:
/// let a = HashMap::from([("a", 1), ("b", 2)]);
/// let b = HashMap::from([("a", 3), ("c", 4)]);
/// let out = sum_and_sort_by_value(&[a, b]);
/// // out == vec![("a", 4), ("c", 4), ("b", 2)]  (ordering among equal sums is unspecified)
pub fn sum_and_sort_by_value<K, V>(lst0: &[HashMap<K, V>]) -> Vec<(K, V)>
where
    K: Eq + Hash + Clone,
    V: AddAssign + Default + Clone + PartialOrd,
{
    // Accumulate sums into `acc`
    let mut acc: HashMap<K, V> = HashMap::new();

    for map in lst0 {
        for (k, v) in map {
            // If key exists, add v to existing sum; otherwise insert clone of v.
            acc.entry(k.clone())
                .and_modify(|existing| {
                    // existing += v
                    existing.add_assign(v.clone());
                })
                .or_insert_with(|| v.clone());
        }
    }

    // Move into a Vec for sorting
    let mut pairs: Vec<(K, V)> = acc.into_iter().collect();

    // Sort by value descending. Use partial_cmp to support floats; treat incomparable as equal.
    pairs.sort_by(|a, b| {
        b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal)
    });

    pairs
}

