```rust
use std::collections::HashMap;

/// Aggregates values by key and sorts by summed values in descending order.
///
/// Given a list of key-value mappings, this function:
/// 1. Sums all values for each unique key across all mappings
/// 2. Returns a vector of (key, sum) pairs sorted by sum in descending order
///
/// # Arguments
///
/// * `lst0` - A slice of HashMaps where each map contains key-value pairs
///
/// # Returns
///
/// A `Vec<(String, i64)>` with entries sorted by summed values (highest first)
///
/// # Example
///
/// ```
/// use std::collections::HashMap;
///
/// let map1 = [("apple", 5), ("banana", 3)].iter().cloned().collect::<HashMap<&str, i64>>();
/// let map2 = [("apple", 2), ("banana", 4), ("cherry", 1)].iter().cloned().collect::<HashMap<&str, i64>>();
/// let lst0 = vec![map1, map2];
///
/// let result = aggregate_and_sort_kvs(&lst0);
/// assert_eq!(result, vec![("apple".to_string(), 7), ("banana".to_string(), 7), ("cherry".to_string(), 1)]);
/// ```
fn aggregate_and_sort_kvs<K, V>(lst0: &[HashMap<K, V>]) -> Vec<(K, V)>
where
    K: std::cmp::Eq + std::hash::Hash + Clone + Ord,
    V: std::ops::Add<Output = V> + Clone + Ord + std::cmp::Reverse,
{
    // Aggregate: sum values for each key
    let mut aggregated: HashMap<K, V> = HashMap::new();

    for map in lst0 {
        for (key, value) in map.iter() {
            aggregated
                .entry(key.clone())
                .and_modify(|v| *v = v.clone() + value.clone())
                .or_insert_with(|| value.clone());
        }
    }

    // Convert to vector and sort by value (descending)
    let mut result: Vec<(K, V)> = aggregated.into_iter().collect();
    result.sort_by(|a, b| b.1.cmp(&a.1)); // Sort descending by value

    result
}

// Example usage
fn main() {
    use std::collections::HashMap;

    // Create sample data
    let mut map1 = HashMap::new();
    map1.insert("apple", 5);
    map1.insert("banana", 3);

    let mut map2 = HashMap::new();
    map2.insert("apple", 2);
    map2.insert("banana", 4);
    map2.insert("cherry", 1);

    let lst0 = vec![map1, map2];

    // Aggregate and sort
    let result = aggregate_and_sort_kvs(&lst0);

    println!("Aggregated and sorted results:");
    for (key, sum) in result {
        println!("  {}: {}", key, sum);
    }
    // Output:
    //   apple: 7
    //   banana: 7
    //   cherry: 1
}
```

## Key Features

- **Generic Implementation**: Works with any hashable, cloneable key type and any numeric value type that supports addition and ordering
- **Aggregation**: Iterates through all maps and accumulates values for each key
- **Sorting**: Sorts results by summed values in descending order
- **Self-contained**: No external dependencies (the function doesn't require the `kv-aggregator` library, as Rust's standard `HashMap` provides the necessary aggregation capabilities)

## Complexity

- **Time**: O(n·m + k·log(k)) where n is the number of maps, m is average entries per map, and k is unique keys
