/// A tuple containing the new dataset and remaining headers
fn drop_columns(
    df0: &Vec<Vec<String>>,
    headers: &Vec<String>,
    lst0: &[&str],
) -> (Vec<Vec<String>>, Vec<String>) {
    // Find indices of columns to keep
    let indices_to_keep: Vec<usize> = headers
        .iter()
        .enumerate()
        .filter(|(_, header)| !lst0.contains(&header.as_str()))
        .map(|(idx, _)| idx)
        .collect();

