use itertools::iproduct;

/// Generate all possible sequences by picking exactly one element from each sublist.
///
/// # Arguments
///
/// * `lst0` - A slice of slices, where each inner slice contains elements of type T
///
/// # Returns
///
/// * A vector of vectors, where each inner vector is a sequence formed by picking
///   one element from each sublist
///
/// # Example
///
/// ```
/// let input = vec![vec![1, 2], vec![3, 4], vec![5]];
/// let result = cartesian_product(&input);
/// assert_eq!(result, vec![
///     vec![1, 3, 5],
///     vec![1, 4, 5],
///     vec![2, 3, 5],
///     vec![2, 4, 5],
/// ]);
/// ```
pub fn cartesian_product<T: Clone>(lst0: &[Vec<T>]) -> Vec<Vec<T>> {
    if lst0.is_empty() {
        return vec![vec![]];
    }

    // Start with the first sublist
    let mut result: Vec<Vec<T>> = lst0[0]
        .iter()
        .map(|x| vec![x.clone()])
        .collect();

    // Iterate through remaining sublists
    for sublist in &lst0[1..] {
        let mut new_result = Vec::new();

        // For each existing sequence and each element in the current sublist,
        // create a new sequence by appending the element
        for seq in &result {
            for elem in sublist {
                let mut new_seq = seq.clone();
                new_seq.push(elem.clone());
                new_result.push(new_seq);
            }
        }

        result = new_result;
    }

    result
}

/// Alternative implementation using itertools' iproduct macro
/// This version is more concise but requires the itertools crate
pub fn cartesian_product_itertools<T: Clone + 'static>(lst0: &[Vec<T>]) -> Vec<Vec<T>> {
    match lst0.len() {
        0 => return vec![vec![]],
        1 => return lst0[0].iter().map(|x| vec![x.clone()]).collect(),
        2 => {
            return iproduct!(&lst0[0], &lst0[1])
                .map(|(a, b)| vec![a.clone(), b.clone()])
                .collect();
        }
        3 => {
            return iproduct!(&lst0[0], &lst0[1], &lst0[2])
                .map(|(a, b, c)| vec![a.clone(), b.clone(), c.clone()])
                .collect();
        }
        _ => {
            // For more than 3 sublists, use the iterative approach
            cartesian_product(lst0)
        }
    }
}

