/// assert_eq!(result, vec![vec![1, 3], vec![4, 6], vec![7, 9]]);
/// ```
pub fn remove_columns(mat0: &[Vec<f64>], columns_to_delete: Vec<usize>) -> Vec<Vec<f64>> {
