/// Example:
/// let mat = vec![vec![1,2,3], vec![4,5,6]];
/// let res = remove_columns(&mat, &[0,2]); // res == vec![vec![2], vec![5]]
pub fn remove_columns<T: Clone>(mat0: &[Vec<T>], columns_to_delete: &[usize]) -> Vec<Vec<T>> {
    if mat0.is_empty() {
        return Vec::new();
    }

