    let n_cols = mat0[0].len();

    // Build a boolean mask of columns to delete (size n_cols), ignoring out-of-range indices.
    let mut delete_mask = vec![false; n_cols];
    for &col in columns_to_delete {
        if col < n_cols {
            delete_mask[col] = true;
        }
    }

    // Collect indices of columns to keep in order.
    let keep_cols: Vec<usize> = (0..n_cols).filter(|&j| !delete_mask[j]).collect();

