use polars::prelude::*;

fn element_wise_difference(df0: &DataFrame, df1: &DataFrame) -> Result<DataFrame, PolarsError> {
    // Ensure both dataframes have the same shape
    if df0.height() != df1.height() || df0.width() != df1.width() {
        return Err(PolarsError::ComputeError(
            "DataFrames must be of the same size".into(),
        ));
    }

    // Ensure both dataframes have the same schema
    if df0.schema() != df1.schema() {
        return Err(PolarsError::SchemaMisMatch(
            "DataFrames must have the same schema".into(),
        ));
    }

    // Create a new DataFrame to store the result
    let mut result_columns = Vec::with_capacity(df0.width());

    // Iterate over each column and compute the element-wise difference
    for (name, dtype) in df0.schema().iter_fields() {
        match dtype {
            DataType::Float32 => {
                let col0 = df0.column(name)?.f32()?;
                let col1 = df1.column(name)?.f32()?;
                let diff_col = col0
                    .into_iter()
                    .zip(col1.into_iter())
                    .map(|(a, b)| match (a, b) {
                        (Some(a), Some(b)) => Some(a - b),
                        _ => None,
                    })
                    .collect::<Float32Chunked>();
                result_columns.push(Series::new(name, diff_col));
            }
            DataType::Float64 => {
                let col0 = df0.column(name)?.f64()?;
                let col1 = df1.column(name)?.f64()?;
