                .ok_or_else(|| format!("index out of bounds for df0 at ({},{})", r, c))?;
            let b = df1
                .get(r, c)
                .ok_or_else(|| format!("index out of bounds for df1 at ({},{})", r, c))?;
            out_row.push(*a - *b);
