use polars::prelude::*;

/// Function to retain the first row for each distinct value in a column
///
/// # Arguments
///
/// * `df` - The input DataFrame
/// * `column_name` - The name of the column to consider for uniqueness
///
/// # Returns
///
/// A new DataFrame with only the first row for each distinct value in the specified column
fn retain_first_row(df: &DataFrame, column_name: &str) -> DataFrame {
