// A tiny local "pair-freq" helper to count pair occurrences.
// If you have a real `pair-freq` crate, swap this module out for that crate.
mod pair_freq {
    use std::collections::HashMap;
    use std::hash::Hash;

    pub struct PairFreq<K>(HashMap<K, usize>);

    impl<K: Eq + Hash> PairFreq<K> {
        pub fn new() -> Self {
            PairFreq(HashMap::new())
        }

        // Add/increment one occurrence of key `k`.
        pub fn add(&mut self, k: K) {
            *self.0.entry(k).or_insert(0) += 1;
        }

        // Consume and return an iterator over (key, count).
        pub fn into_iter(self) -> impl Iterator<Item = (K, usize)> {
            self.0.into_iter()
        }
    }
}

/// Compute the frequency of each unique (col1, col2) pair.
///
/// - `rows` is any iterable of (T, T) pairs (for example, you can map your table rows
///   to `(row.col1.clone(), row.col2.clone())` and pass that).
/// - Returns a Vec of ((col1, col2), count) sorted by descending count.
///
/// T must implement Eq + Hash + Clone so pairs can be used as hash-map keys.
pub fn compute_pair_freq<T, I>(rows: I) -> Vec<((T, T), usize)>
where
    T: Eq + Hash + Clone,
    I: IntoIterator<Item = (T, T)>,
