impl MultiIndex {
    /// Build a MultiIndex from two parallel arrays of strings.
    pub fn from_arrays(level0_vals: &[String], level1_vals: &[String]) -> Result<Self, String> {
        if level0_vals.len() != level1_vals.len() {
            return Err("length mismatch between level arrays".to_string());
        }
        let mut uniq0: Vec<String> = Vec::new();
        let mut uniq1: Vec<String> = Vec::new();
        let mut map0: HashMap<&String, usize> = HashMap::new();
        let mut map1: HashMap<&String, usize> = HashMap::new();
        let mut labels: Vec<(usize, usize)> = Vec::with_capacity(level0_vals.len());

