            let i1 = match map1.get(b) {
                Some(&i) => i,
                None => {
                    let idx = uniq1.len();
                    uniq1.push(b.clone());
                    map1.insert(b, idx);
                    idx
                }
            };
            labels.push((i0, i1));
        }

        Ok(MultiIndex {
            levels: (uniq0, uniq1),
            labels,
        })
    }
