Below is a self-contained Rust implementation of a row-filtering function that supports multiple conditions. It models the typical capabilities of filtering libraries (equals, !=, numeric comparisons, contains, starts_with, ends_with) and accepts column selection by index or by header name. It does not require any external crates, so it's easy to drop into a project; the API is similar in spirit to table2d-filter libraries and can be adapted to one if you prefer.

Code:

```rust
use std::str::FromStr;

/// Column selector: either by zero-based index or by header name.
#[derive(Debug, Clone)]
pub enum Column {
    Index(usize),
    Name(String),
}

/// Supported comparison operators.
#[derive(Debug, Clone, Copy)]
pub enum Operator {
    Eq,         // ==
    Ne,         // !=
    Lt,         // <
    Le,         // <=
    Gt,         // >
    Ge,         // >=
    Contains,   // substring
    StartsWith, // prefix
    EndsWith,   // suffix
}

/// One condition to apply to a row.
#[derive(Debug, Clone)]
pub struct Condition {
    pub column: Column,
    pub operator: Operator,
    pub value: String,
    /// If false, comparisons are done case-insensitively for string ops.
    pub case_sensitive: bool,
}

/// Filter a 2D table (rows of columns) by multiple conditions.
/// - `headers`: optional slice of header values (used if conditions refer to columns by name).
/// - `rows`: slice of rows, each row is a Vec<String> of column values.
/// - `conditions`: list of conditions; a row must satisfy ALL conditions to be included.
///
/// Returns a Vec<Vec<String>> containing the rows that matched all conditions.
///
/// Notes:
/// - If a condition references a column by name but headers is None or the name is not found,
///   that condition is treated as not satisfied (the row will be excluded).
/// - For Eq/Ne/Lt/Le/Gt/Ge: if both the cell and condition value parse as f64, a numeric comparison
///   is attempted; otherwise a lexicographic string comparison is used.
/// - Contains/StartsWith/EndsWith operate on strings.
///
pub fn filter_rows(
    headers: Option<&[String]>,
    rows: &[Vec<String>],
    conditions: &[Condition],
) -> Vec<Vec<String>> {
    rows.iter()
        .filter(|row| {
            conditions.iter().all(|cond| {
                // Resolve column index
                let idx_opt = match &cond.column {
                    Column::Index(i) => Some(*i),
                    Column::Name(name) => {
                        if let Some(hdrs) = headers {
                            hdrs.iter().position(|h| h == name)
                        } else {
                            None
                        }
                    }
                };

                let idx = match idx_opt {
                    Some(i) => i,
                    None => return false, // column not found => condition fails
                };

                let cell = row.get(idx);
                let cell = match cell {
                    Some(c) => c,
                    None => return false, // out-of-range column => condition fails
                };

                match cond.operator {
                    Operator::Contains => {
                        if cond.case_sensitive {
                            cell.contains(&cond.value)
                        } else {
                            cell.to_lowercase().contains(&cond.value.to_lowercase())
                        }
                    }
                    Operator::StartsWith => {
                        if cond.case_sensitive {
                            cell.starts_with(&cond.value)
                        } else {
                            cell.to_lowercase().starts_with(&cond.value.to_lowercase())
                        }
                    }
                    Operator::EndsWith => {
                        if cond.case_sensitive {
                            cell.ends_with(&cond.value)
                        } else {
                            cell.to_lowercase().ends_with(&cond.value.to_lowercase())
                        }
                    }
                    // For eq/ne/lt/le/gt/ge we try numeric compare first
                    Operator::Eq | Operator::Ne | Operator::Lt | Operator::Le | Operator::Gt | Operator::Ge => {
                        // Try numeric comparison
                        let cell_num = parse_f64(cell);
                        let val_num = parse_f64(&cond.value);
                        if let (Some(a), Some(b)) = (cell_num, val_num) {
                            match cond.operator {
                                Operator::Eq => a == b,
                                Operator::Ne => a != b,
                                Operator::Lt => a < b,
                                Operator::Le => a <= b,
                                Operator::Gt => a > b,
                                Operator::Ge => a >= b,
                                _ => unreachable!(),
                            }
                        } else {
                            // Fallback to string comparison
                            let (a, b) = if cond.case_sensitive {
                                (cell.as_str(), cond.value.as_str())
                            } else {
                                (cell.to_lowercase().as_str(), cond.value.to_lowercase().as_str())
                            };
                            match cond.operator {
                                Operator::Eq => a == b,
                                Operator::Ne => a != b,
                                Operator::Lt => a < b,
                                Operator::Le => a <= b,
                                Operator::Gt => a > b,
                                Operator::Ge => a >= b,
                                _ => unreachable!(),
                            }
                        }
                    }
                }
            })
        })
        .cloned()
        .collect()
}

fn parse_f64(s: &str) -> Option<f64> {
    // Trim whitespace then attempt parse
    let t = s.trim();
    f64::from_str(t).ok()
}

