    // Sort by max value in descending order
    items.sort_by(|a, b| b.1.cmp(&a.1));

    // Rebuild the HashMap in the new order
    let mut sorted_map = HashMap::with_capacity(map.len());
    for (k, _) in items {
        sorted_map.insert(k.clone(), map.remove(k).unwrap());
    }

    // Return the original map (now sorted)
    map.clear();
    for (k, v) in sorted_map {
