# Rust Function: Sort Map by Maximum Value

Here's a self-contained Rust function that sorts a key-to-sequence mapping by the maximum value in each sequence in descending order:

```rust
use std::collections::HashMap;

/// Reorders a HashMap so that entries are sorted by the maximum value
/// in each associated sequence in descending order.
/// 
/// # Arguments
/// * `map` - A HashMap where keys map to vectors of numbers
/// 
/// # Returns
/// A Vec of tuples containing (key, sequence) sorted by max sequence value descending
fn sort_map_by_max_descending<K: Clone + Ord, V: Ord + Copy>(
    map: &HashMap<K, Vec<V>>,
) -> Vec<(K, Vec<V>)> {
    let mut entries: Vec<(K, Vec<V>)> = map
        .iter()
        .map(|(k, v)| (k.clone(), v.clone()))
        .collect();

    // Sort by the maximum value in each sequence in descending order
    entries.sort_by(|a, b| {
        let max_a = a.1.iter().max();
        let max_b = b.1.iter().max();

        // Compare in reverse order for descending sort
        max_b.cmp(&max_a)
    });

    entries
}

// Example usage and tests
fn main() {
    let mut map: HashMap<&str, Vec<i32>> = HashMap::new();
    map.insert("fruits", vec![3, 7, 2]);
    map.insert("vegetables", vec![15, 8, 10]);
    map.insert("grains", vec![5, 5, 5]);
    map.insert("dairy", vec![20, 12]);

    let sorted = sort_map_by_max_descending(&map);

    println!("Sorted entries by maximum value (descending):");
    for (key, sequence) in sorted {
        let max = sequence.iter().max().unwrap();
        println!("  {}: {:?} (max: {})", key, sequence, max);
    }
}
