use std::collections::HashSet;

/// Performs a semi-join between two tables (A and B) based on a key.
///
/// # Arguments
/// * `table_a` - A vector of rows from table A, where each row is a tuple of values.
/// * `table_b` - A vector of rows from table B, where each row is a tuple of values.
/// * `key_index` - The index of the key column to join on (must be the same for both tables).
///
/// # Returns
/// A vector of rows from table A that have matching rows in table B based on the key.
///
/// # Example
/// ```
/// use std::collections::HashSet;
///
/// let table_a = vec![
///     vec!["Alice".to_string(), 30],
///     vec!["Bob".to_string(), 25],
///     vec!["Charlie".to_string(), 35],
/// ];
/// let table_b = vec![
