use polars::prelude::*;

/// Perform a semi-join operation between two tables.
///
/// This function filters the rows from table A so that only those with matching rows in table B are retained.
///
/// # Arguments
///
/// * `table_a`: The left table.
/// * `table_b`: The right table.
/// * `join_column`: The column to join on.
///
/// # Returns
///
/// A new DataFrame containing the filtered rows from table A.
fn semi_join(table_a: &DataFrame, table_b: &DataFrame, join_column: &str) -> DataFrame {
    let join_column_a = table_a.column(join_column).unwrap();
    let join_column_b = table_b.column(join_column).unwrap();

    let mask = join_column_a.is_in(join_column_b);
    table_a.filter(&mask).unwrap()
}

