    let table_b = DataFrame::new(vec![
        Series::new("id", vec![1, 2, 3]),
        Series::new("other_value", vec![100, 200, 300]),
    ])
    .unwrap();

    // Perform semi-join
    let result = semi_join(&table_a, &table_b, "id");

    // Print the result
    println!("{:?}", result);
}
```

