/// Simple in-file "column-mean" library.
mod column_mean {
    use std::collections::HashMap;

    /// Compute the mean for each group of columns that share the same name.
    ///
    /// - `headers`: list of column names (length = number of columns).
    /// - `rows`: list of rows; each row is a Vec<Option<f64>> of length = number of columns.
    ///
    /// Returns a HashMap mapping column-name -> mean (f64). Groups with no numeric values are omitted.
    pub fn grouped_means(headers: &[String], rows: &[Vec<Option<f64>>]) -> HashMap<String, f64> {
