pub fn reset_index_to_columns(mut table: Table) -> Result<Table, Error> {
    // If there's no index, nothing to do.
    let index_ref = match table.index() {
        Some(idx) => idx,
        None => return Ok(table),
    };

    let index_names = index_ref.names();
    let nrows = table.height();

    // For each index level, construct a column of values (one value per row).
    // Insert new columns in front so the former index levels appear to the left of existing columns,
    // which is the common behavior of "reset_index" operations (like pandas.reset_index()).
    for (level_idx, level_name) in index_names.iter().enumerate() {
