/// * `index_name` - The name for the new column created from the old index
/// 
/// # Returns
/// * A new Table with a default integer index and the old index values as a column
pub fn reset_index(mut table: Table, index_name: &str) -> Table {
    // Extract the current index values
    let old_index = table.index().clone();

