```rust
use std::collections::HashMap;

/// Combines a list of key-value mappings into a single mapping where each key's 
/// value is the sum of that key's values across all input mappings.
///
/// # Arguments
/// * `mappings` - A slice of HashMaps with string keys and numeric values
///
/// # Returns
/// A HashMap where each key maps to the sum of its values across all input mappings
///
/// # Example
/// ```
/// use std::collections::HashMap;
///
/// let mut map1 = HashMap::new();
/// map1.insert("a".to_string(), 10);
/// map1.insert("b".to_string(), 5);
///
/// let mut map2 = HashMap::new();
/// map2.insert("a".to_string(), 20);
/// map2.insert("c".to_string(), 15);
///
/// let result = aggregate_mappings(&[map1, map2]);
/// assert_eq!(result.get("a"), Some(&30));
/// assert_eq!(result.get("b"), Some(&5));
/// assert_eq!(result.get("c"), Some(&15));
/// ```
fn aggregate_mappings(mappings: &[HashMap<String, i64>]) -> HashMap<String, i64> {
    let mut aggregated: HashMap<String, i64> = HashMap::new();

    for mapping in mappings {
        for (key, value) in mapping.iter() {
            aggregated
                .entry(key.clone())
                .and_modify(|v| *v += value)
                .or_insert(*value);
        }
    }

    aggregated
}

