use std::ops::Sub;

/// Calculates the Euclidean distance between two points in N-dimensional space.
///
/// # Arguments
/// * `point1` - A sequence of numerical coordinates representing the first point
/// * `point2` - A sequence of numerical coordinates representing the second point
///
/// # Returns
/// The Euclidean distance between the two points
pub fn euclidean_distance<T, I>(point1: I, point2: I) -> f64
where
    T: Sub<Output = T> + std::ops::Mul<f64, Output = T> + Into<f64>,
    I: IntoIterator<Item = T>,
    I::IntoIter: ExactSizeIterator,
{
    let mut sum = 0.0;
    let mut iter1 = point1.into_iter();
    let mut iter2 = point2.into_iter();

    while let (Some(a), Some(b)) = (iter1.next(), iter2.next()) {
        let diff = a - b;
        sum += (diff * diff).into::<f64>();
    }

    sum.sqrt()
}

