        let word = word.trim();
        if word.is_empty() {
            return 0;
        }

        // Escape the search word so any special regex characters are treated literally.
        let escaped = regex::escape(word);

        // Use `\b` boundaries to ensure whole-word matching.
        let pattern = format!(r"\b{}\b", escaped);

        // Build the regex with optional case insensitivity and Unicode enabled.
        let re = RegexBuilder::new(&pattern)
            .case_insensitive(case_insensitive)
            .unicode(true)
            .build()
            .expect("failed to build regex");

