use std::collections::HashMap;

/// A single row in the table.
/// - var0 and var1 are the grouping fields (strings).
/// - values holds all numeric columns (column name -> value).
#[derive(Debug)]
struct Row {
    var0: String,
    var1: String,
    values: HashMap<String, f64>,
}

/// Compute the mean of each numeric column in `df0`, grouped by (var0, var1).
///
/// Returns a map from (var0_value, var1_value) -> (column_name -> mean).
fn compute_grouped_column_means(
    df0: &[Row],
) -> HashMap<(String, String), HashMap<String, f64>> {
    // accumulator: group_key -> column -> (sum, count)
    let mut acc: HashMap<(String, String), HashMap<String, (f64, usize)>> = HashMap::new();

    for row in df0 {
        let key = (row.var0.clone(), row.var1.clone());
        let group_entry = acc.entry(key).or_insert_with(HashMap::new);

        for (col, &val) in &row.values {
            let e = group_entry.entry(col.clone()).or_insert((0.0_f64, 0_usize));
            e.0 += val;
            e.1 += 1;
        }
    }

    // finalize: compute means
    let mut result: HashMap<(String, String), HashMap<String, f64>> = HashMap::new();
    for (group_key, col_map) in acc {
        let mut means: HashMap<String, f64> = HashMap::new();
        for (col, (sum, count)) in col_map {
            if count > 0 {
                means.insert(col, sum / (count as f64));
            }
        }
        result.insert(group_key, means);
    }

    result
}

