use std::collections::HashMap;

fn compute_grouped_mean(
    df0: Vec<HashMap<String, f64>>,
    var0: &str,
    var1: &str,
) -> HashMap<(String, String), HashMap<String, f64>> {
    let mut groups: HashMap<(String, String), Vec<HashMap<String, f64>>> = HashMap::new();

    // Group rows by var0 and var1
    for row in df0 {
        if let (Some(v0), Some(v1)) = (
            row.get(var0).map(|v| v.to_string()),
            row.get(var1).map(|v| v.to_string()),
        ) {
            groups
                .entry((v0, v1))
                .or_insert_with(Vec::new)
                .push(row);
        }
    }

    // Compute means for each group
    let mut result = HashMap::new();
    for (key, group_rows) in groups {
        let mut means = HashMap::new();
        let count = group_rows.len() as f64;

        // Get all column names from first row
        if let Some(first_row) = group_rows.first() {
            for col_name in first_row.keys() {
                if col_name != var0 && col_name != var1 {
                    let sum: f64 = group_rows.iter().filter_map(|r| r.get(col_name)).sum();
                    means.insert(col_name.clone(), sum / count);
                }
            }
        }

        result.insert(key, means);
    }

    result
}
