mod entry_if_none {
    use std::collections::HashMap;
    use std::hash::Hash;

    /// Extension trait for HashMap<K, Option<V>> providing set_if_none.
    pub trait EntryIfNone<K, V> {
        /// If the map contains `key` and its value is `None`, set it to `Some(value)`.
        /// If the key is absent or already `Some(_)`, do nothing.
        fn set_if_none(&mut self, key: K, value: V);
