fn replace_diagonal<T: Clone>(arr0: &mut Array2<T>, var0: T) {
    let (rows, cols) = arr0.dim();
    let diagonal_len = rows.min(cols);

    for i in 0..diagonal_len {
        arr0[[i, i]] = var0.clone();
    }
}

