///
/// This version is self-contained and does not require external crates.
/// If you have a `tabular-sort` crate and want to use it, enable the "use_tabular_sort" feature
/// and provide the appropriate implementation for your crate.
pub fn sort_tabular_dataset(data0: &mut Vec<Vec<String>>, cols0: &[&str]) {
    // Quick exit for empty or header-only tables
    if data0.len() <= 1 || cols0.is_empty() {
        return;
    }

    // Find header and map requested column names to indices.
    // If a requested column is not found, it is simply ignored.
    let header = &data0[0];
    let mut col_indices: Vec<usize> = Vec::new();
    for &col_name in cols0 {
        if let Some(idx) = header.iter().position(|h| h == col_name) {
            col_indices.push(idx);
        }
    }

    // If none of the requested columns were found, do nothing.
    if col_indices.is_empty() {
        return;
    }

    // Sort only the data rows (keep header at data0[0]).
    // Use split_first_mut to get a mutable slice of the body without the header.
    let (_header_row, body) = data0.split_first_mut().unwrap();

    // Stable lexicographic sort by the sequence of column indices.
