- Returns a Vec<(K, Vec<V>)> sorted by the element at the provided index.
- Elements that lack the requested index are ordered either before or after present elements depending on the missing_first parameter.
- K and V must be Ord (V obviously for comparison; K doesn't need Ord for the algorithm but keeping it unconstrained is ok — we don't depend on key-ordering).

Code (self-contained, no external crates):

```rust
use std::cmp::Ordering;
use std::collections::HashMap;

/// Sort a map whose values are sequences by the element at `index` inside those sequences.
///
/// - `map`: any iterable of (K, Vec<V>) pairs (e.g., HashMap<K, Vec<V>>.into_iter()).
/// - `index`: the position inside each value-sequence used as the sort key.
/// - `missing_first`: if true, entries whose sequence is too short (no element at `index`)
///                    are ordered before entries that do have an element; if false they come after.
///
/// Returns a Vec of (K, Vec<V>) pairs in sorted order (stable with respect to equal keys).
///
/// Example:
/// let mut m = HashMap::new();
/// m.insert("a", vec![2, 10]);
/// m.insert("b", vec![1, 20]);
/// let sorted = sort_map_by_seq_index(m.into_iter(), 0, true);
/// // sorted will be [("b", [1,20]), ("a", [2,10])]
///
pub fn sort_map_by_seq_index<K, V, I>(
    map: I,
    index: usize,
    missing_first: bool,
) -> Vec<(K, Vec<V>)>
where
    I: IntoIterator<Item = (K, Vec<V>)>,
    V: Ord,
{
    let mut entries: Vec<(K, Vec<V>)> = map.into_iter().collect();

    entries.sort_by(|a, b| {
        let a_key = a.1.get(index);
        let b_key = b.1.get(index);

        match (a_key, b_key) {
            (Some(x), Some(y)) => x.cmp(y),
            (Some(_), None) => {
                if missing_first {
                    Ordering::Greater
