Code:

```rust
use std::collections::HashMap;

/// Sum columns that have identical headers.
///
/// Inputs:
/// - `headers`: vector of column headers (may contain duplicates).
/// - `rows`: vector of rows; each row is a vector of f64 values and must have the same length as `headers`.
///
/// Output:
/// - Ok((unique_headers, summed_rows)) where:
///   - `unique_headers` is headers with duplicates removed in order of first occurrence.
///   - `summed_rows` has the same number of rows as input, and one column per unique header; each value is the sum
///     of the corresponding input columns that had that header.
///
/// Returns Err(...) if any input row length does not match headers length.
pub fn sum_columns_with_identical_headers(
    headers: &[String],
    rows: &[Vec<f64>],
) -> Result<(Vec<String>, Vec<Vec<f64>>), String> {
    let n_cols = headers.len();
    // Build mapping from header -> output column index, preserving first-occurrence order.
    let mut out_index: HashMap<&str, usize> = HashMap::new();
    let mut unique_headers: Vec<String> = Vec::new();

    for h in headers {
        let key = h.as_str();
        if !out_index.contains_key(key) {
            let idx = unique_headers.len();
            unique_headers.push(h.clone());
            out_index.insert(key, idx);
        }
    }

    let n_out_cols = unique_headers.len();
    let n_rows = rows.len();

    // Prepare output rows initialized to zero
    let mut out_rows: Vec<Vec<f64>> = vec![vec![0.0; n_out_cols]; n_rows];

    // Validate input and accumulate sums
    for (r_idx, row) in rows.iter().enumerate() {
        if row.len() != n_cols {
            return Err(format!(
                "Row {} length ({}) does not match headers length ({})",
                r_idx,
                row.len(),
                n_cols
            ));
        }
        for (col_idx, value) in row.iter().enumerate() {
            let header = headers[col_idx].as_str();
            let target_col = out_index[header];
            out_rows[r_idx][target_col] += *value;
        }
    }

    Ok((unique_headers, out_rows))
}

