# Rust Function for Summing Columns with Identical Headers

```rust
use std::collections::HashMap;

/// Sums the values of columns with identical headers in a tabular dataset.
/// Returns a dataset with each header appearing only once, with values summed.
///
/// # Arguments
/// * `headers` - A vector of column header names
/// * `rows` - A vector of rows, where each row is a vector of numeric values
///
/// # Returns
/// A tuple containing:
/// * `Vec<String>` - Unique headers in order of first appearance
/// * `Vec<Vec<f64>>` - Rows with aggregated columns
///
/// # Example
/// ```
/// let headers = vec!["A".to_string(), "B".to_string(), "A".to_string()];
/// let rows = vec![
///     vec![1.0, 2.0, 3.0],
///     vec![4.0, 5.0, 6.0],
/// ];
/// let (new_headers, new_rows) = sum_identical_columns(headers, rows);
/// assert_eq!(new_headers, vec!["A".to_string(), "B".to_string()]);
/// assert_eq!(new_rows, vec![
///     vec![4.0, 2.0],  // 1.0 + 3.0 = 4.0 for "A", 2.0 for "B"
///     vec![10.0, 5.0], // 4.0 + 6.0 = 10.0 for "A", 5.0 for "B"
/// ]);
/// ```
pub fn sum_identical_columns(
    headers: Vec<String>,
    rows: Vec<Vec<f64>>,
) -> (Vec<String>, Vec<Vec<f64>>) {
    // Build a map of unique headers to their column indices
    let mut header_map: HashMap<String, Vec<usize>> = HashMap::new();
    let mut unique_headers: Vec<String> = Vec::new();

    for (col_idx, header) in headers.iter().enumerate() {
        if !header_map.contains_key(header) {
            unique_headers.push(header.clone());
        }
        header_map.entry(header.clone()).or_insert_with(Vec::new).push(col_idx);
    }

    // Process each row: sum columns with identical headers
    let aggregated_rows = rows
        .iter()
        .map(|row| {
            unique_headers
                .iter()
                .map(|header| {
                    header_map
                        .get(header)
                        .unwrap()
                        .iter()
                        .map(|&col_idx| row[col_idx])
                        .sum::<f64>()
                })
                .collect::<Vec<f64>>()
        })
        .collect::<Vec<Vec<f64>>>();

    (unique_headers, aggregated_rows)
}

