            vec![1.0, 2.0, 3.0],
            vec![4.0, 5.0, 6.0],
        ];

        let (new_headers, new_rows) = sum_identical_columns(headers, rows);

        assert_eq!(new_headers, vec!["A".to_string(), "B".to_string()]);
        assert_eq!(new_rows, vec![
