/// * `var0` - The inner key to sort by
/// 
/// # Returns
/// A new BTreeMap with entries reordered by the specified inner key's values
pub fn reorder_by_inner_key<K, V, IK>(
    dict0: BTreeMap<K, BTreeMap<IK, V>>,
    var0: &IK,
) -> BTreeMap<K, BTreeMap<IK, V>>
where
    K: Ord + Clone,
    IK: Ord + Clone,
    V: Ord + Clone,
{
    // Convert to a vector of (key, value) pairs for sorting
    let mut entries: Vec<(K, BTreeMap<IK, V>)> = dict0.into_iter().collect();

    // Sort by the value associated with the specified inner key
    entries.sort_by(|a, b| {
        let a_val = a.1.get(var0);
        let b_val = b.1.get(var0);

        match (a_val, b_val) {
            (Some(a_val), Some(b_val)) => a_val.cmp(b_val),
            (Some(_), None) => std::cmp::Ordering::Less,
            (None, Some(_)) => std::cmp::Ordering::Greater,
            (None, None) => std::cmp::Ordering::Equal,
        }
    });

    // Convert back to BTreeMap
    entries.into_iter().collect()
}

// Example usage
fn main() {
    use std::collections::BTreeMap;

    // Create a sample nested mapping
    let mut dict0 = BTreeMap::new();

    let mut inner1 = BTreeMap::new();
