use std::cmp::Ordering;

/// Mini "min-pair" library (self-contained helper).
/// Provides a `min_by` function that returns the minimum item of an iterator
/// according to a provided comparator.
mod min_pair {
    use std::cmp::Ordering;

    /// Return the minimum item from an iterator according to `cmp`.
    /// The iterator item type `T` is returned by value.
    pub fn min_by<I, T, F>(mut iter: I, mut cmp: F) -> Option<T>
    where
        I: Iterator<Item = T>,
        F: FnMut(&T, &T) -> Ordering,
    {
        let first = iter.next()?;
        let mut best = first;
        for item in iter {
            if cmp(&item, &best) == Ordering::Less {
                best = item;
            }
        }
        Some(best)
    }
}

/// Given a slice of (label, value_string) pairs, parse numeric values and
/// return the pair with the smallest valid numeric value as (label, f64).
/// Values that fail to parse to a finite f64 are treated as invalid and ignored.
/// Returns None if there are no valid numeric values.
pub fn smallest_valid_pair(pairs: &[(String, String)]) -> Option<(String, f64)> {
    // Build an iterator of valid (label, value) pairs (owned).
    let candidates = pairs.iter().filter_map(|(label, val_str)| {
