/// ```
fn find_min_pair(pairs: &[(&str, f64)]) -> Option<(&str, f64)> {
    pairs
        .iter()
        .filter(|(_, value)| value.is_finite()) // Filter out NaN and infinities
        .copied()
        .min_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal))
