    desc_positions: Option<Vec<usize>>,
) -> Vec<&str> {
    let mut result = texts.clone();

    // If no positions specified, sort all in ascending order
    let positions_set = desc_positions.unwrap_or_default();

    if positions_set.is_empty() {
        result.sort();
        return result;
    }

    // Create a set of positions for O(1) lookup
    let desc_set: std::collections::HashSet<usize> = positions_set.into_iter().collect();

    // Sort using positional_sort with custom comparison
    result.sort_by(|a, b| {
        // Get the original indices before sorting
        // We need to track indices through the sort, so we use indexed approach
        if desc_set.contains(&result.iter().position(|x| x == a).unwrap_or(0)) {
            b.cmp(a) // Descending for specified positions
        } else {
            a.cmp(b) // Ascending for other positions
        }
    });

    result
