```rust
/// Return the indices of the `k` (= var0) largest elements in `xs` (= lst0),
/// sorted from highest value to lowest. If k > xs.len(), all indices are returned.
pub fn topk_indices(var0: usize, xs: &[f64]) -> Vec<usize> {
    let n = xs.len();
    let k = var0.min(n);
    // collect all indices
    let mut idx: Vec<usize> = (0..n).collect();
    // sort indices so that indices of larger values come first (descending by value).
    // tie-break by index to be deterministic.
    idx.sort_unstable_by(|&i, &j| match xs[i].partial_cmp(&xs[j]) {
        Some(std::cmp::Ordering::Greater) => std::cmp::Ordering::Less,    // i > j -> i should come before j
        Some(std::cmp::Ordering::Less) => std::cmp::Ordering::Greater,    // i < j -> i should come after j
        Some(std::cmp::Ordering::Equal) => i.cmp(&j),                     // tie-break by index
        None => std::cmp::Ordering::Equal,                                // NaN cases: treat as equal
    });
    idx.truncate(k);
    idx
}

