```rust
use std::collections::HashMap;
use std::error::Error;

/// Removes rows with duplicate identifiers from a tabular dataset, keeping only the first occurrence.
///
/// # Arguments
/// * `data` - A vector of vectors representing the tabular data (each inner vector is a row)
/// * `id_column_index` - The index of the column containing the identifier
///
/// # Returns
/// * `Result<Vec<Vec<String>>, Box<dyn Error>>` - The deduplicated data or an error
///
/// # Example
/// ```
/// let data = vec![
///     vec!["ID1".to_string(), "Alice".to_string(), "25".to_string()],
///     vec!["ID2".to_string(), "Bob".to_string(), "30".to_string()],
///     vec!["ID1".to_string(), "Charlie".to_string(), "35".to_string()], // Duplicate ID
///     vec!["ID3".to_string(), "David".to_string(), "28".to_string()],
/// ];
///
/// let result = remove_duplicate_ids(data, 0).unwrap();
/// assert_eq!(result.len(), 3); // Only 3 rows should remain
/// ```
pub fn remove_duplicate_ids(
    data: Vec<Vec<String>>,
    id_column_index: usize,
) -> Result<Vec<Vec<String>>, Box<dyn Error>> {
    // Validate that the id_column_index is within bounds for all rows
    if data.is_empty() {
        return Ok(Vec::new());
    }

    for (row_idx, row) in data.iter().enumerate() {
        if id_column_index >= row.len() {
            return Err(format!(
                "Row {} has {} columns, but id_column_index is {}",
                row_idx,
                row.len(),
                id_column_index
            )
            .into());
        }
    }

    // Use a HashMap to track seen identifiers
    let mut seen_ids: HashMap<String, bool> = HashMap::new();
    let mut result: Vec<Vec<String>> = Vec::new();

    for row in data {
        let id = &row[id_column_index];

        // Check if we've seen this identifier before
        if !seen_ids.contains_key(id) {
            seen_ids.insert(id.clone(), true);
            result.push(row);
        }
        // If we've seen it, skip this row (keep only first occurrence)
    }

    Ok(result)
}

