/// Multiply a row vector `var0` (length n) by a matrix `var1` (n x m).
/// Returns a vector of length m on success, or an Err with a message if dimensions are invalid.
///
/// var0: &[f64]        - the input row vector (length n)
/// var1: &[Vec<f64>]  - the input matrix given as n rows, each of length m
///
/// Example:
/// let v = vec![1.0, 2.0]; // 1x2
/// let m = vec![vec![3.0, 4.0], vec![5.0, 6.0]]; // 2x2
/// assert_eq!(vec_mat_mul(&v, &m).unwrap(), vec![13.0, 16.0]); // [1*3 + 2*5, 1*4 + 2*6]
pub fn vec_mat_mul(var0: &[f64], var1: &[Vec<f64>]) -> Result<Vec<f64>, String> {
    // If the matrix has zero rows, treat as producing an empty result.
    if var1.is_empty() {
        // only valid if vector is also empty (or we accept multiplying empty matrix)
        if var0.is_empty() {
            return Ok(Vec::new());
        } else {
            return Err("Matrix has zero rows but vector is non-empty".into());
        }
    }

    let n = var0.len();
    if var1.len() != n {
        return Err(format!(
            "Dimension mismatch: vector length is {}, matrix has {} rows",
            n,
            var1.len()
        ));
    }

    // Ensure all rows have the same number of columns and get m
    let m = var1[0].len();
    for (r_idx, row) in var1.iter().enumerate() {
        if row.len() != m {
            return Err(format!(
                "Invalid matrix: row {} has length {} but expected {}",
                r_idx,
                row.len(),
                m
            ));
        }
    }

    // Result is a row vector of length m
    let mut result = vec![0.0_f64; m];

    // Compute result[j] = sum_i var0[i] * var1[i][j]
    for (i, &v) in var0.iter().enumerate() {
        let row = &var1[i];
        // Unroll inner loop by index for clarity/performance
        for j in 0..m {
            result[j] += v * row[j];
        }
    }

    Ok(result)
}

