use std::error::Error;

/// Strip currency symbols from the penultimate column of a 2D table and convert to f64 strings.
///
/// Assumes `Table<String>` provides access to its rows as `Vec<Vec<String>>` via `rows_mut()`.
/// If your currency-table type has a different API, extract the rows into `Vec<Vec<String>>`,
