///     let mut tbl: currency_table::Table<String> = ...;
///     let rows = tbl.rows_mut(); // if available
///     strip_currency_from_penultimate_col_rows(rows)?;
///
/// This function operates in-place: it replaces each penultimate-column cell with the
/// stringified floating-point value (using Rust's default to_string for f64).
pub fn strip_currency_from_penultimate_col_rows(
    rows: &mut Vec<Vec<String>>,
) -> Result<(), Box<dyn Error>> {
    if rows.is_empty() {
        return Ok(());
    }

    // Determine penultimate column index using the first non-empty row with at least 2 columns
    let mut penultimate_idx_opt: Option<usize> = None;
    for r in rows.iter() {
        if r.len() >= 2 {
            penultimate_idx_opt = Some(r.len() - 2);
            break;
        }
    }
    let penultimate_idx = match penultimate_idx_opt {
        Some(i) => i,
        None => return Ok(()), // nothing to do: no row with >= 2 columns
    };

    // Helper to clean a currency-like string to a parseable float-like string
    fn clean_currency_text(s: &str) -> String {
        let s = s.trim();

        // Remove surrounding parentheses indicating negative amounts
        let (is_negative, mut inner) = if s.starts_with('(') && s.ends_with(')') {
            (true, s[1..s.len() - 1].trim())
        } else {
            (false, s)
        };

        // Remove common currency symbols and whitespace (including NBSP)
        let mut without_symbols = inner
            .chars()
            .filter(|&c| {
                // keep digits, common signs, separators, exponent markers and decimal point/comma
                match c {
                    '0'..='9' | '.' | ',' | '-' | '+' | 'e' | 'E' => true,
                    // treat NBSP (U+00A0) as whitespace to be removed
                    _ => false,
                }
            })
            .collect::<String>();

        // Decide how to handle commas / dots:
        // If both '.' and ',' appear, assume ',' are thousand separators -> remove all ','
        // If only ',' appears (no '.'), treat ',' as decimal separator and convert to '.'
        // Otherwise leave '.' as decimal separator
        let has_dot = without_symbols.contains('.');
        let has_comma = without_symbols.contains(',');

        if has_comma && has_dot {
            without_symbols.retain(|c| c != ',');
        } else if has_comma && !has_dot {
            // treat comma as decimal separator
            without_symbols = without_symbols.replace(',', ".");
        }

        // Reattach sign if parentheses indicated negative
        if is_negative {
            format!("-{}", without_symbols)
        } else {
            without_symbols
        }
    }

    for row in rows.iter_mut() {
        if row.len() <= penultimate_idx {
            // ragged row: skip
            continue;
        }
        let original = row[penultimate_idx].clone();
        // if cell is empty or purely whitespace, skip conversion
        if original.trim().is_empty() {
            continue;
        }
        let cleaned = clean_currency_text(&original);
        // Parse float; propagate parse errors upwards
        let value: f64 = cleaned.parse()?;
        // Replace cell with canonical float string
        row[penultimate_idx] = value.to_string();
    }

    Ok(())
}

