```rust
use polars::prelude::*;

/// Replace values in column "var2" of `df0`: 0 -> value from "var0", 1 -> value from "var1".
///
/// This updates `df0` in place (returns a new DataFrame with the replaced column and assigns it
/// back to the original reference).
///
/// Returns Result<(), PolarsError>.
pub fn replace_var2_with_var0_var1(df0: &mut DataFrame) -> PolarsResult<()> {
    // Build an expression:
    // if var2 == 0 -> var0
    // else if var2 == 1 -> var1
    // else -> var2 (leave unchanged)
    let new_var2_expr = when(col("var2").eq(lit(0)))
        .then(col("var0"))
        .when(col("var2").eq(lit(1)))
        .then(col("var1"))
        .otherwise(col("var2"))
        .alias("var2");

    // Apply expression and replace column "var2"
    // with_column returns a new DataFrame; assign it back to df0 by replacing contents.
    let replaced = df0.clone().lazy().with_column(new_var2_expr).collect()?;
    *df0 = replaced;

    Ok(())
}
```

