use std::cmp::Ordering;

/// Sort `data0` (Vec of rows, where each row is Vec<T>) by the sequence of columns in `col0`.
/// Returns the sorted dataset as `var0`.
///
/// - `data0`: input two-dimensional dataset (rows x columns)
/// - `col0`: list of column indices (0-based) specifying the sort precedence (first index = primary key)
pub fn sort_by_columns<T: Ord + Clone>(mut data0: Vec<Vec<T>>, col0: &[usize]) -> Vec<Vec<T>> {
    // Use stable sort; compare rows by columns in `col0` order
    data0.sort_by(|a, b| {
        for &col in col0 {
            match (a.get(col), b.get(col)) {
                (Some(av), Some(bv)) => {
                    let cmp = av.cmp(bv);
                    if cmp != Ordering::Equal {
                        return cmp;
                    }
                }
                (None, Some(_)) => {
                    // a is missing this column while b has a value -> treat missing as less
                    return Ordering::Less;
                }
                (Some(_), None) => {
                    // a has a value, b missing -> a is greater
                    return Ordering::Greater;
                }
                (None, None) => {
                    // both missing this column -> continue to next column
                    continue;
                }
            }
        }
        Ordering::Equal
    });

    // Return sorted result named `var0` as requested
    let var0 = data0;
    var0
}

