use std::collections::HashMap;

/// A lazy view that presents keys and values of an underlying map as lowercase.
/// Keys are looked up case-insensitively by lowercasing the lookup key.
/// Values are lowercased on demand when returned by `get` or yielded by `iter`.
pub struct LazyLowercaseMap {
    // original map with original casing
    inner: HashMap<String, String>,
    // index mapping lowercased key -> original key (first occurrence wins)
    key_index: HashMap<String, String>,
}

impl LazyLowercaseMap {
    /// Build the lazy lowercase view from an existing map.
    /// This indexes lowercase keys to allow fast lookups; values themselves are
    /// not lowercased until requested.
    pub fn new(dict: HashMap<String, String>) -> Self {
        let mut key_index = HashMap::with_capacity(dict.len());
        for key in dict.keys() {
            let lk = key.to_lowercase();
            // keep the first original key we see for this lowercase form
            key_index.entry(lk).or_insert_with(|| key.clone());
        }
        LazyLowercaseMap {
            inner: dict,
            key_index,
        }
    }

    /// Lookup by (any-case) key; returns the value lowercased if present.
    pub fn get(&self, key: &str) -> Option<String> {
        let lk = key.to_lowercase();
        self.key_index
            .get(&lk)
            .and_then(|orig_key| self.inner.get(orig_key))
            .map(|v| v.to_lowercase())
    }

    /// Returns an iterator over (lowercased_key, lowercased_value) pairs.
    /// The lowercasing is performed on demand as the iterator yields items.
    pub fn iter(&self) -> impl Iterator<Item = (String, String)> + '_ {
        self.inner
            .iter()
            .map(|(k, v)| (k.to_lowercase(), v.to_lowercase()))
    }

    /// Consume the view and return an iterator that yields owned (lowercased_key, lowercased_value).
    pub fn into_iter(self) -> impl Iterator<Item = (String, String)> {
        self.inner.into_iter().map(|(k, v)| (k.to_lowercase(), v.to_lowercase()))
    }

    /// Convenience: materialize the whole lowered map (this eagerly generates all entries).
    pub fn to_hash_map(&self) -> HashMap<String, String> {
        self.iter().collect()
    }
}

/// Convenience function requested: take dict0 and produce a lazy-lowercase map view.
pub fn lowercase_lazy(dict0: HashMap<String, String>) -> LazyLowercaseMap {
    LazyLowercaseMap::new(dict0)
}

fn main() {
    let mut dict0 = HashMap::new();
    dict0.insert("Foo".into(), "BarValue".into());
    dict0.insert("BaZ".into(), "QuxValue".into());

    let lazy = lowercase_lazy(dict0);

    // Lookup (case-insensitive)
    assert_eq!(lazy.get("foo"), Some("barvalue".into()));
    assert_eq!(lazy.get("BAZ"), Some("quxvalue".into()));
    assert_eq!(lazy.get("missing"), None);

    // Iterate (keys and values lowercased on the fly)
    for (k, v) in lazy.iter() {
        println!("{} => {}", k, v);
    }

    // Materialize if you need an eager HashMap
    let eager = lazy.to_hash_map();
    println!("eager map: {:?}", eager);
}

Notes:
- This implementation indexes lowercase keys for O(1) lookup. Values are lowercased only when returned or iterated, satisfying "generate entries on demand".
- If the original map contains two keys that differ only by case (e.g., "Foo" and "foo"), this implementation keeps the first one encountered for the lowercase key; adjust behavior if you need deterministic conflict resolution.

