/// assert_eq!(result, vec![
///     vec![1, 40, 60],
///     vec![2, 50, 60],
/// ]);
/// ```
pub fn group_and_sum(input: &[Vec<f64>], group_column: usize) -> Vec<Vec<f64>> {
    // Check for empty input
    if input.is_empty() {
        return Vec::new();
    }

    // Determine the number of columns
    let num_columns = input[0].len();

    // Check if group_column is valid
    if group_column >= num_columns {
        panic!("Group column index {} is out of bounds for table with {} columns", group_column, num_columns);
