use std::collections::HashMap;
use std::hash::Hash;

/// Group rows by the value in column var0 and sum the corresponding entries in all other columns.
///
/// rows: slice of (key, values) where `values` are the remaining columns (as f64).
/// Returns a Vec of (key, summed_values) with one entry per unique key.
/// The returned vector is sorted by key for deterministic output (requires K: Ord).
pub fn group_by_sum_var0<K>(rows: &[(K, Vec<f64>)]) -> Vec<(K, Vec<f64>)>
where
    K: Eq + Hash + Clone + Ord,
{
    let mut map: HashMap<K, Vec<f64>> = HashMap::new();

    for (key, vals) in rows {
        if vals.is_empty() {
            // If there are no other columns, ensure we still keep an empty vector for the key.
            map.entry(key.clone()).or_insert_with(Vec::new);
            continue;
        }

        let entry = map
            .entry(key.clone())
            .or_insert_with(|| vec![0.0f64; vals.len()]);

        // If row has different number of columns than the first seen for this key,
        // we handle by resizing the accumulator if necessary.
        if entry.len() < vals.len() {
            entry.resize(vals.len(), 0.0);
        }

        for (i, &v) in vals.iter().enumerate() {
            entry[i] += v;
        }
    }

    // Collect and sort by key for deterministic ordering
    let mut aggregated: Vec<(K, Vec<f64>)> = map.into_iter().collect();
    aggregated.sort_by(|a, b| a.0.cmp(&b.0));
    aggregated
}

