///
/// // Group by "category" and aggregate
/// let result = group_and_pivot(&df, "category", sum_fn);
/// ```
pub fn group_and_pivot<F>(df0: &DataFrame, var0: &str, agg_function: F) -> HashMap<String, f64>
where
    F: Fn(&[f64]) -> f64,
{
    // Get the grouping column
    let group_column = df0.get_column(var0)
        .expect("Column not found")
        .as_string()
        .expect("Grouping column must be string type");

    // Get the values column (assuming there's a numeric column to aggregate)
    // In a real implementation, you might want to specify which column to aggregate
    let value_column = df0.get_column("value")
        .expect("Value column not found")
        .as_f64()
        .expect("Value column must be numeric type");

    // Group values by the grouping field
    let mut grouped: HashMap<String, Vec<f64>> = HashMap::new();

    for (group, value) in group_column.iter().zip(value_column.iter()) {
        grouped.entry(group.clone())
            .or_insert_with(Vec::new)
            .push(*value);
    }

    // Apply the aggregation function to each group
    let mut result: HashMap<String, f64> = HashMap::new();

    for (group, values) in grouped.iter() {
        let aggregated = agg_function(values.as_slice());
        result.insert(group.clone(), aggregated);
    }

    result
}

