    // Create a pivot table configuration
    let mut pivot = PivotTable::new();

    // Set the row field (grouping field)
    pivot.set_rows(vec![var0]);

    // Set the values field (assuming "value" is the column to aggregate)
    pivot.set_values(vec!["value"]);

    // Apply custom aggregation
    pivot.set_aggregation(move |values| agg_function(values));

    // Execute the pivot
    let pivoted = pivot.execute(df0)
        .expect("Pivot operation failed");

    // Convert the pivoted DataFrame to a HashMap
    let mut result: HashMap<String, f64> = HashMap::new();

    if let Some(row_column) = pivoted.get_column(var0) {
        if let Some(value_column) = pivoted.get_column("value") {
            let row_values = row_column.as_string().unwrap();
            let value_values = value_column.as_f64().unwrap();

            for (row, value) in row_values.iter().zip(value_values.iter()) {
                result.insert(row.clone(), *value);
            }
        }
    }

