use std::collections::HashMap;
use itertools::Itertools;

/// Convert an iterator of (K, V) pairs into a HashMap<K, (K, V)>,
/// using the first element of each pair as the key and the whole pair as the value.
/// If a key appears multiple times, the last pair for that key is kept.
fn groups_to_map<K, V, I>(items: I) -> HashMap<K, (K, V)>
where
    I: IntoIterator<Item = (K, V)>,
    K: Eq + std::hash::Hash + Clone,
{
    // Group into HashMap<K, Vec<(K, V)>> using the pair's first element as the grouping key.
    let grouped: HashMap<K, Vec<(K, V)>> =
        items.into_iter().into_group_map_by(|(k, _v)| k.clone());

    // From each vector of pairs for a key, take the last pair (if any) as the map value.
    grouped
        .into_iter()
        .filter_map(|(k, mut vec)| vec.pop().map(|pair| (k, pair)))
        .collect()
}

fn main() {
    let pairs = vec![
        ("a", 1),
        ("b", 2),
        ("a", 3), // duplicate key "a"
        ("c", 4),
    ];

    let map = groups_to_map(pairs);

    // map contains:
    // "a" -> ("a", 3)
    // "b" -> ("b", 2)
    // "c" -> ("c", 4)
    for (k, pair) in &map {
        println!("{:?} => {:?}", k, pair);
    }
}
