Here's a self-contained Rust function that creates a key-value mapping from two-element groups:

```rust
use itertools::Itertools;
use std::collections::HashMap;

/// Creates a key-value mapping from a sequence of two-element groups.
/// Each group's first element is used as the key, and the entire group (as a tuple) is the value.
///
/// # Arguments
/// * `items` - An iterable sequence of items to be grouped
///
/// # Returns
/// A HashMap where keys are the first elements of pairs and values are the tuples themselves
///
/// # Example
/// ```
/// let data = vec![1, 2, 3, 4, 5, 6];
/// let result = group_map_pairs(data);
/// assert_eq!(result.get(&1), Some(&(1, 2)));
/// assert_eq!(result.get(&3), Some(&(3, 4)));
/// assert_eq!(result.get(&5), Some(&(5, 6)));
/// ```
fn group_map_pairs<T: Clone + std::hash::Hash + Eq>(
    items: impl IntoIterator<Item = T>,
) -> HashMap<T, (T, T)> {
    items
        .into_iter()
        .chunks(2)
        .into_iter()
        .filter_map(|mut chunk| {
            let first = chunk.next()?;
            let second = chunk.next()?;
            Some((first.clone(), (first, second)))
        })
        .collect()
}

fn main() {
    // Example 1: Integer pairs
    let numbers = vec![1, 2, 3, 4, 5, 6];
    let result = group_map_pairs(numbers);

    println!("Integer pairs:");
    for (key, value) in &result {
        println!("  Key: {}, Value: {:?}", key, value);
    }

    // Example 2: String pairs
    let strings = vec!["a", "b", "c", "d", "e", "f"];
    let result2 = group_map_pairs(strings);

    println!("\nString pairs:");
    for (key, value) in &result2 {
        println!("  Key: {}, Value: {:?}", key, value);
    }

    // Example 3: Odd number of elements (last element is ignored)
    let odd_numbers = vec![10, 20, 30, 40, 50];
    let result3 = group_map_pairs(odd_numbers);

    println!("\nOdd number of elements:");
    for (key, value) in &result3 {
        println!("  Key: {}, Value: {:?}", key, value);
    }
}
```

