) -> Result<usize, Box<dyn Error>> {
    // Validate that the data is not empty
    if data.is_empty() {
        return Err("Data is empty".into());
    }

    // Validate that the column index is within bounds
    let max_column_index = data[0].len().checked_sub(1)
        .ok_or("Data has no columns")?;

    if column_index > max_column_index {
        return Err(format!(
            "Column index {} is out of bounds. Maximum column index is {}",
            column_index, max_column_index
        ).into());
    }

    // Create a ColumnValueCounter and process the data
    let mut counter = ColumnValueCounter::new();

    for row in data {
        if column_index < row.len() {
            counter.add(row[column_index]);
        }
    }

    // Get the count for the target value
    let count = counter.get_count(target_value);

    Ok(count)
}

