use std::collections::HashMap;

/// Function to count distinct combinations of values in specified columns of a DataFrame.
fn count_distinct_combinations(df: &DataFrame, key_columns: Vec<&str>) -> Result<DataFrame> {
    // Ensure the key columns are in the DataFrame
    for key in &key_columns {
        if !df.get_column(key).is_ok() {
            return Err(PolarsError::InvalidOperation(format!(
                "Column {} not found in DataFrame",
                key
            )));
        }
