/// Compute means for selected rows and selected columns from a 2D table.
///
/// - `data` is a slice of rows, each row is a Vec<f64>. All rows must have the same length.
/// - `row_indices` lists the row indices whose means (over the selected columns) are computed.
/// - `col_indices` lists the column indices whose means (over the selected rows) are computed.
///
/// Returns Ok((row_means, col_means)) on success, where:
/// - row_means[i] is the mean of `data[row_indices[i]][col_indices[*]]`
/// - col_means[j] is the mean of `data[row_indices[*]][col_indices[j]]`
///
/// Returns Err(String) if the matrix is ragged or any index is out of bounds.
///
/// Example:
/// let data = vec![vec![1.0,2.0,3.0], vec![4.0,5.0,6.0], vec![7.0,8.0,9.0]];
/// let (rmeans, cmeans) = selected_row_col_means(&data, &[0,2], &[1,2])?;
pub fn selected_row_col_means(
    data: &[Vec<f64>],
    row_indices: &[usize],
    col_indices: &[usize],
) -> Result<(Vec<f64>, Vec<f64>), String> {
    // empty data -> return empty means
    if data.is_empty() {
        return Ok((vec![], vec![]));
    }

    // Ensure matrix is rectangular
    let ncols = data[0].len();
    for (i, row) in data.iter().enumerate() {
        if row.len() != ncols {
            return Err(format!("ragged matrix: row {} has length {}, expected {}", i, row.len(), ncols));
        }
    }

    let nrows = data.len();

    // Bounds checks
    for &ri in row_indices {
        if ri >= nrows {
            return Err(format!("row index {} out of bounds (nrows = {})", ri, nrows));
        }
    }
    for &ci in col_indices {
        if ci >= ncols {
            return Err(format!("col index {} out of bounds (ncols = {})", ci, ncols));
        }
    }

    // Compute row means: for each selected row, average the entries in selected columns
    let mut row_means = Vec::with_capacity(row_indices.len());
    for &ri in row_indices {
        let row = &data[ri];
        if col_indices.is_empty() {
            // define mean over zero elements as NaN
            row_means.push(f64::NAN);
            continue;
        }
        let mut sum = 0.0;
        for &ci in col_indices {
            sum += row[ci];
        }
        row_means.push(sum / (col_indices.len() as f64));
    }

    // Compute column means: for each selected column, average the entries in selected rows
    let mut col_means = Vec::with_capacity(col_indices.len());
    for &ci in col_indices {
        if row_indices.is_empty() {
            col_means.push(f64::NAN);
            continue;
        }
        let mut sum = 0.0;
        for &ri in row_indices {
            sum += data[ri][ci];
        }
        col_means.push(sum / (row_indices.len() as f64));
    }

    Ok((row_means, col_means))
}

