    #[test]
    fn test_compute_means() {
        let data = vec![
            vec![1.0, 2.0, 3.0],
            vec![4.0, 5.0, 6.0],
            vec![7.0, 8.0, 9.0],
        ];

        let row_indices = vec![0, 2];
        let col_indices = vec![0, 2];

        let (row_means, col_means) = compute_row_col_means(&data, &row_indices, &col_indices);

        // Row 0: (1+2+3)/3 = 2.0
        // Row 2: (7+8+9)/3 = 8.0
        assert_eq!(row_means, vec![2.0, 8.0]);

        // Col 0: (1+4+7)/3 = 4.0
        // Col 2: (3+6+9)/3 = 6.0
        assert_eq!(col_means, vec![4.0, 6.0]);
    }

    #[test]
    fn test_single_row_col() {
        let data = vec![vec![10.0, 20.0], vec![30.0, 40.0]];

