use std::collections::HashMap;

/// Sorts each inner list according to a mapping that defines the desired order of elements.
///
/// # Arguments
/// * `lists` - A vector of vectors to be sorted.
/// * `order_map` - A mapping from elements to their desired order (lower values come first).
///
/// # Returns
/// A new vector of vectors where each inner list is sorted according to the order_map.
///
/// # Example
/// ```
/// let lists = vec![vec!['c', 'a', 'b'], vec!['z', 'x', 'y']];
/// let order_map = HashMap::from([('a', 0), ('b', 1), ('c', 2), ('x', 0), ('y', 1), ('z', 2)]);
/// let sorted_lists = sort_lists_by_map(lists, &order_map);
/// assert_eq!(sorted_lists, vec![vec!['a', 'b', 'c'], vec!['x', 'y', 'z']]);
/// ```
pub fn sort_lists_by_map<T, K>(lists: Vec<Vec<T>>, order_map: &HashMap<T, K>) -> Vec<Vec<T>>
where
    T: Clone + std::cmp::Eq + std::hash::Hash,
    K: Ord,
{
    lists
        .into_iter()
        .map(|mut inner_list| {
            inner_list.sort_by(|a, b| {
                // If both elements are in the map, compare their order
                if let (Some(ka), Some(kb)) = (order_map.get(a), order_map.get(b)) {
                    ka.cmp(kb)
                }
                // If one is in the map and the other isn't, the one in the map comes first
                else if order_map.contains_key(a) {
                    std::cmp::Ordering::Less
                }
                else if order_map.contains_key(b) {
                    std::cmp::Ordering::Greater
                }
                // If neither is in the map, maintain original order (stable sort)
                else {
                    std::cmp::Ordering::Equal
                }
            });
            inner_list
        })
        .collect()
}

