    // get usize::MAX so they end up at the end. The sort is stable relative to items
    // with equal keys (stable because we use sort_by_key which is stable).
    for list in lists.iter_mut() {
        list.sort_by_key(|item| order_map.get(item).cloned().unwrap_or(usize::MAX));
    }
}

