```rust
use std::collections::HashMap;

/// Convert a 2D table `df0` (header row + data rows) into a map keyed by the
/// values in the column named `var0`.
///
/// - `df0` is expected as Vec<Vec<String>> where the first row (df0[0]) is the header.
/// - `var0` is the name of the column to use as the row identifier (the map key).
/// - Returns Err if header is missing or `var0` not found in header.
/// - If multiple rows share the same key, the later row overwrites the earlier one.
///
/// Example:
/// let df0 = vec![
///     vec!["id".into(), "name".into(), "age".into()],
///     vec!["a1".into(), "Alice".into(), "30".into()],
///     vec!["b2".into(), "Bob".into(), "25".into()],
/// ];
/// let map = table_to_map_by_column(&df0, "id").unwrap();
/// assert_eq!(map["a1"]["name"], "Alice");
pub fn table_to_map_by_column(
    df0: &[Vec<String>],
    var0: &str,
) -> Result<HashMap<String, HashMap<String, String>>, String> {
    if df0.is_empty() {
        return Ok(HashMap::new());
    }

    let header = &df0[0];
    let col_count = header.len();

    let key_col_index = header
        .iter()
        .position(|h| h == var0)
        .ok_or_else(|| format!("Identifier column '{}' not found in header", var0))?;

    let mut result: HashMap<String, HashMap<String, String>> = HashMap::new();

    for (row_idx, row) in df0.iter().enumerate().skip(1) {
        // Build a row map of header -> value. If a row is short, missing values become empty string.
        let mut row_map: HashMap<String, String> = HashMap::with_capacity(col_count);

        for (i, col_name) in header.iter().enumerate() {
            let value = row.get(i).cloned().unwrap_or_default();
            row_map.insert(col_name.clone(), value);
        }

        // Determine key
        let key = row
            .get(key_col_index)
            .cloned()
            .unwrap_or_default(); // if missing, use empty key

        if key.is_empty() {
            // Optionally skip empty keys; here we choose to return an error to avoid silent loss.
            return Err(format!("Empty identifier found in row {}", row_idx + 1));
        }

        // Insert into result (later rows overwrite earlier ones with same key)
        result.insert(key, row_map);
    }

    Ok(result)
}

fn main() {
    // Example usage
    let df0 = vec![
        vec!["id".into(), "name".into(), "age".into()],
        vec!["a1".into(), "Alice".into(), "30".into()],
        vec!["b2".into(), "Bob".into(), "25".into()],
        vec!["a1".into(), "Alice Lee".into(), "31".into()], // duplicate id => will overwrite previous a1
    ];

    match table_to_map_by_column(&df0, "id") {
