/// let mut map = HashMap::new();
/// map.insert("banana", 3);
/// map.insert("apple", 1);
/// map.insert("pear", 2);
///
/// let sorted = sort_by_value(&map);
/// assert_eq!(sorted, vec![
///     ("apple", 1, 1),
///     ("pear", 2, 2),
///     ("banana", 3, 0),
/// ]);
/// ```
pub fn sort_by_value<K, V, I>(mapping: I) -> Vec<(K, V, usize)>
where
    I: IntoIterator<Item = (K, V)>,
    K: Ord + Clone,
    V: Ord,
{
    // Collect the original items with their indices
    let mut items: Vec<(K, V, usize)> = mapping
        .into_iter()
        .enumerate()
        .map(|(i, (k, v))| (k, v, i))
        .collect();

    // Sort by value (and then by original index to maintain stability)
    items.sort_by(|a, b| a.1.cmp(&b.1).then(a.2.cmp(&b.2)));

