fn groupby_max_row(df0: &DataFrame, var0: &str, var1: &str) -> Result<DataFrame> {
    // Create a lazy DataFrame from the input DataFrame
    let ldf = df0.lazy();

    // Group by var1 and find the index of the max value in var0 for each group
    let idx_max_df = ldf
        .group_by([col(var1)])
        .agg([col(var0).arg_max().alias("idx_max")])
