        .join(
            idx_max_df.lazy(),
            [col(var1)],
            ["group"],
            JoinType::Inner,
        )
        .filter(col("idx_max").eq(lit(0i32)))
        .select(df0.get_column_names())
        .collect()?;

    Ok(joined_df)
}

