use triple_pairs_iter::TriplePairsIter;

/// Iterates through a sequence of items, each containing three pairs of values.
/// 
/// This function demonstrates how to use the triple-pairs-iter library to process
/// sequences where each item contains three key-value pairs.
/// 
/// # Example
/// ```
/// let data = vec![
///     (("key1", "val1"), ("key2", "val2"), ("key3", "val3")),
///     (("a", "1"), ("b", "2"), ("c", "3")),
/// ];
/// 
/// process_triple_pairs(data);
/// ```
fn process_triple_pairs<T>(items: Vec<((T, T), (T, T), (T, T))>) 
where 
    T: std::fmt::Debug
{
    for item in items {
        let triple_pairs = TriplePairsIter::from(item);

        for (index, pair) in triple_pairs.enumerate() {
            println!("Pair {}: {:?}", index, pair);
        }
    }
}

/// Alternative: Process with mutable access to each pair
fn process_triple_pairs_mut<T>(mut items: Vec<((T, T), (T, T), (T, T))>) 
where 
    T: std::fmt::Debug + Clone
{
    for item in &mut items {
        let triple_pairs = TriplePairsIter::from(item.clone());

        triple_pairs.for_each(|pair| {
            println!("Processing pair: {:?}", pair);
        });
    }
}

/// Collect all pairs from triple-pair items into a single vector
fn collect_all_pairs<T: Clone>(items: Vec<((T, T), (T, T), (T, T))>) -> Vec<(T, T)> {
    items
        .into_iter()
        .flat_map(|item| TriplePairsIter::from(item).collect::<Vec<_>>())
        .collect()
}

