# Rust Function: Extract Substring

Here's a self-contained Rust function that extracts a portion of text starting at a specified position for a given number of characters:

```rust
/// Extracts a substring from the input text.
///
/// # Arguments
/// * `text` - The input string slice
/// * `start` - The starting position (in characters, not bytes)
/// * `length` - The number of characters to extract
///
/// # Returns
/// An `Option<&str>` containing the substring, or `None` if the range is invalid
///
/// # Example
/// ```
/// let text = "Hello, World!";
/// assert_eq!(substring(text, 0, 5), Some("Hello"));
/// assert_eq!(substring(text, 7, 5), Some("World"));
/// assert_eq!(substring(text, 100, 5), None);
/// ```
fn substring(text: &str, start: usize, length: usize) -> Option<&str> {
    let chars: Vec<char> = text.chars().collect();

    // Check if start position is valid
    if start >= chars.len() {
        return None;
    }

    // Calculate end position
    let end = std::cmp::min(start + length, chars.len());

    // Convert character indices back to byte indices
    let byte_start = chars[..start].iter().map(|c| c.len_utf8()).sum::<usize>();
    let byte_end = chars[..end].iter().map(|c| c.len_utf8()).sum::<usize>();

    Some(&text[byte_start..byte_end])
}

fn main() {
    // Example usage
    let text = "Hello, World!";

    println!("{:?}", substring(text, 0, 5));      // Some("Hello")
    println!("{:?}", substring(text, 7, 5));      // Some("World")
    println!("{:?}", substring(text, 0, 100));    // Some("Hello, World!")
    println!("{:?}", substring(text, 100, 5));    // None

    // Works with Unicode characters
    let text_unicode = "Hello, 世界! 🌍";
    println!("{:?}", substring(text_unicode, 7, 2)); // Some("世界")
}
