mod colscale {
    // Minimal local implementation of a MinMax scaler for demonstration.
    // This mimics the idea of a "colscale" library's min-max functionality.
    pub struct MinMaxScaler {
        mins: Vec<f64>,
        maxs: Vec<f64>,
    }

    impl MinMaxScaler {
        // Fit a scaler to the data (rows x cols)
        pub fn fit(data: &[Vec<f64>]) -> Result<Self, String> {
            if data.is_empty() {
                return Ok(Self { mins: vec![], maxs: vec![] });
            }
            let ncols = data[0].len();
            if ncols == 0 {
                return Ok(Self { mins: vec![], maxs: vec![] });
            }

            // initialize mins and maxs from first row
            let mut mins = data[0].clone();
            let mut maxs = data[0].clone();

            for row in data.iter().skip(1) {
                if row.len() != ncols {
                    return Err("Inconsistent number of columns in rows".into());
                }
                for (j, &v) in row.iter().enumerate() {
                    // propagate NaN: if value is NaN, leave min/max unchanged
                    if v.is_nan() {
                        continue;
                    }
                    if mins[j].is_nan() || v < mins[j] {
                        mins[j] = v;
                    }
                    if maxs[j].is_nan() || v > maxs[j] {
                        maxs[j] = v;
                    }
                }
            }
            Ok(Self { mins, maxs })
        }

        // Transform data using the fitted mins and maxs
        pub fn transform(&self, data: &[Vec<f64>]) -> Result<Vec<Vec<f64>>, String> {
            if data.is_empty() {
                return Ok(vec![]);
            }
            let ncols = self.mins.len();
            if ncols == 0 {
                // no columns
                return Ok(data.iter().map(|_| vec![]).collect());
            }

            let mut out: Vec<Vec<f64>> = Vec::with_capacity(data.len());
            for row in data {
                if row.len() != ncols {
                    return Err("Inconsistent number of columns in rows".into());
                }
                let mut out_row = Vec::with_capacity(ncols);
                for j in 0..ncols {
                    let v = row[j];
                    if v.is_nan() {
                        out_row.push(f64::NAN);
                        continue;
                    }
                    let min = self.mins[j];
                    let max = self.maxs[j];

                    if min.is_nan() || max.is_nan() {
                        // if min/max are NaN due to all-NaN column, propagate NaN
                        out_row.push(f64::NAN);
                    } else if (max - min).abs() < std::f64::EPSILON {
                        // constant column -> map to 0.0
                        out_row.push(0.0);
                    } else {
                        out_row.push((v - min) / (max - min));
                    }
                }
                out.push(out_row);
            }
            Ok(out)
        }

