use consec_dedupe::ConsecutiveDedupe;
use polars::prelude::*;

/// Removes consecutive duplicate rows from a DataFrame, keeping only the first occurrence
/// in each sequence of identical consecutive rows.
///
/// # Arguments
/// * `df0` - A Polars DataFrame to deduplicate
///
/// # Returns
/// * `Result<DataFrame>` - A new DataFrame with consecutive duplicates removed
///
/// # Example
/// ```
/// use polars::prelude::*;
///
/// let df = df! {
///     "A" => [1, 1, 1, 2, 2, 3],
///     "B" => ["x", "x", "x", "y", "y", "z"],
/// }.unwrap();
///
/// let result = remove_consecutive_duplicate_rows(df).unwrap();
/// // Result has 3 rows: [1, "x"], [2, "y"], [3, "z"]
/// ```
fn remove_consecutive_duplicate_rows(df0: DataFrame) -> Result<DataFrame> {
    // Convert DataFrame to a vector of rows for deduplication
    let mut rows: Vec<Vec<String>> = df0
        .iter()
        .map(|series| {
            series
                .iter()
                .map(|val| val.to_string())
                .collect::<Vec<String>>()
        })
        .collect();

    // Transpose to get rows instead of columns
    if rows.is_empty() {
        return Ok(df0);
    }

    let n_rows = rows[0].len();
    let mut transposed_rows: Vec<Vec<String>> = vec![vec![]; n_rows];

    for col in rows {
        for (i, val) in col.iter().enumerate() {
            transposed_rows[i].push(val.clone());
        }
    }

    // Apply consecutive deduplication
    transposed_rows.consecutive_dedupe();

    // Reconstruct DataFrame from deduplicated rows
    let columns = df0.get_column_names();
    let mut new_series: Vec<Series> = vec![];

    for (col_idx, col_name) in columns.iter().enumerate() {
        let original_series = df0.column(col_name)?;
        let values: Vec<String> = transposed_rows
            .iter()
            .map(|row| row[col_idx].clone())
            .collect();

        // Recreate series with appropriate dtype
        let new_col = match original_series.dtype() {
            DataType::Int64 => Series::new(
                col_name,
                values.iter().map(|v| v.parse::<i64>().ok()).collect::<Vec<_>>(),
            ),
            DataType::Float64 => Series::new(
                col_name,
                values.iter().map(|v| v.parse::<f64>().ok()).collect::<Vec<_>>(),
            ),
            _ => Series::new(col_name, values),
        };

        new_series.push(new_col);
    }

    DataFrame::new(new_series)
}
