use consec_dedupe::ConsecutiveDedupe;
use polars::prelude::*;

/// Removes consecutive duplicate rows from a DataFrame
fn remove_consecutive_duplicate_rows(df0: DataFrame) -> Result<DataFrame> {
    let n_rows = df0.height();

    if n_rows <= 1 {
        return Ok(df0);
    }

    // Create a vector of row indices to keep
    let mut keep_indices: Vec<usize> = (0..n_rows).collect();

    // Compare consecutive rows and mark duplicates for removal
    let mut i = 0;
    while i < keep_indices.len() - 1 {
        let row1_idx = keep_indices[i];
        let row2_idx = keep_indices[i + 1];

        let row1 = df0.slice(row1_idx as i64, 1);
        let row2 = df0.slice(row2_idx as i64, 1);

        if rows_equal(&row1, &row2) {
            keep_indices.remove(i + 1);
        } else {
            i += 1;
        }
    }

    // Filter DataFrame to keep only selected rows
    df0.filter(&Series::new(
        "_keep",
        (0..n_rows)
            .map(|i| keep_indices.contains(&i))
            .collect::<Vec<_>>(),
    ))
}

