///
/// - df: mutable reference to a DataFrame whose cells are f64.
/// - columns_list0: list of column names to be divided (each element is &str).
/// - column_name0: name of the column whose value is used as the denominator for each row.
///
/// Returns Ok(()) on success or Err(String) with a descriptive message on failure.
///
/// Assumptions about the dataframe-divider API used here:
/// - DataFrame<f64>::nrows() -> usize
/// - DataFrame<f64>::has_column(&str) -> bool
/// - DataFrame<f64>::get_value(row_index: usize, column_name: &str) -> Option<f64>
/// - DataFrame<f64>::set_value(row_index: usize, column_name: &str, value: f64) -> Result<(), E>
pub fn divide_columns_by_column(
    df: &mut DataFrame<f64>,
    columns_list0: &[&str],
    column_name0: &str,
) -> Result<(), String> {
    // Validate denominator column exists
    if !df.has_column(column_name0) {
        return Err(format!("Denominator column '{}' not found in DataFrame", column_name0));
    }

    // Validate numerator columns exist
    for &col in columns_list0 {
        if !df.has_column(col) {
            return Err(format!("Column '{}' not found in DataFrame", col));
        }
    }

    let nrows = df.nrows();

    for row in 0..nrows {
        // Get denominator for this row
        let denom = df
            .get_value(row, column_name0)
            .ok_or_else(|| format!("Missing value in denominator column '{}' at row {}", column_name0, row))?;

        if denom == 0.0 {
            return Err(format!("Division by zero in row {} for denominator column '{}'", row, column_name0));
        }

        // Divide each specified column value by the denominator and write back
        for &col in columns_list0 {
            let numerator = df
                .get_value(row, col)
                .ok_or_else(|| format!("Missing value in column '{}' at row {}", col, row))?;
            let new_val = numerator / denom;
            df.set_value(row, col, new_val)
                .map_err(|e| format!("Failed to set value at row {}, column '{}': {:?}", row, col, e))?;
        }
    }

    Ok(())
}
