# Rust Function for Tuple Counting with Advanced Operations

```rust
use std::collections::HashMap;
use std::cmp::Ordering;

/// A tuple counter that supports filtering, ordering, and limiting results
#[derive(Debug, Clone)]
pub struct TupleCounter<T: Clone + Eq + std::hash::Hash> {
    counts: HashMap<T, usize>,
}

impl<T: Clone + Eq + std::hash::Hash> TupleCounter<T> {
    /// Create a new TupleCounter from a sequence
    pub fn new<I: IntoIterator<Item = T>>(items: I) -> Self {
        let mut counts = HashMap::new();
        for item in items {
            *counts.entry(item).or_insert(0) += 1;
        }
        TupleCounter { counts }
    }

    /// Get the count of a specific tuple
    pub fn get_count(&self, item: &T) -> usize {
        self.counts.get(item).copied().unwrap_or(0)
    }

    /// Get all tuples and their counts
    pub fn counts(&self) -> Vec<(T, usize)> {
        self.counts
            .iter()
            .map(|(k, v)| (k.clone(), *v))
            .collect()
    }

    /// Filter tuples based on a predicate function
    pub fn filter<F>(self, predicate: F) -> Self
    where
        F: Fn(&T) -> bool,
    {
        let filtered = self
            .counts
            .into_iter()
            .filter(|(k, _)| predicate(k))
            .collect();
        TupleCounter { counts: filtered }
    }

    /// Filter tuples based on their count
    pub fn filter_by_count<F>(self, predicate: F) -> Self
    where
        F: Fn(usize) -> bool,
    {
        let filtered = self
            .counts
            .into_iter()
            .filter(|(_, count)| predicate(*count))
            .collect();
        TupleCounter { counts: filtered }
    }

    /// Get tuples ordered by count (descending by default)
    pub fn order_by_count(self) -> Vec<(T, usize)> {
        let mut items = self.counts();
        items.sort_by(|a, b| b.1.cmp(&a.1));
        items
    }

    /// Get tuples ordered by count in ascending order
    pub fn order_by_count_asc(self) -> Vec<(T, usize)> {
        let mut items = self.counts();
        items.sort_by(|a, b| a.1.cmp(&b.1));
        items
    }

    /// Limit results to top N tuples by count
    pub fn top_n(self, n: usize) -> Vec<(T, usize)> {
        let mut items = self.order_by_count();
        items.truncate(n);
        items
    }

    /// Limit results to bottom N tuples by count
    pub fn bottom_n(self, n: usize) -> Vec<(T, usize)> {
        let mut items = self.order_by_count_asc();
        items.truncate(n);
        items
    }

    /// Get tuples with count greater than or equal to threshold
    pub fn min_count(self, threshold: usize) -> Vec<(T, usize)> {
        let mut items: Vec<_> = self
            .counts
            .into_iter()
            .filter(|(_, count)| *count >= threshold)
            .map(|(k, v)| (k, v))
            .collect();
        items.sort_by(|a, b| b.1.cmp(&a.1));
        items
    }

    /// Get total number of unique tuples
    pub fn unique_count(&self) -> usize {
        self.counts.len()
    }

    /// Get total count of all occurrences
    pub fn total_count(&self) -> usize {
        self.counts.values().sum()
    }

    /// Get the most common tuple and its count
    pub fn most_common(&self) -> Option<(T, usize)> {
        self.counts
            .iter()
            .max_by_key(|&(_, count)| count)
            .map(|(k, v)| (k.clone(), *v))
    }

    /// Get the least common tuple and its count
    pub fn least_common(&self) -> Option<(T, usize)> {
        self.counts
            .iter()
            .min_by_key(|&(_, count)| count)
            .map(|(k, v)| (k.clone(), *v))
    }
}

