use order_by_list::order_by_list;

pub fn custom_sort<A: Ord + Clone, B: AsRef<[A]>>(a: &[A], b: B) -> Vec<A> {
    let order = b.as_ref();

    // Create a hashmap for quick lookup of indices in B
    let order_indices: std::collections::HashMap<_, _> = order.iter()
        .enumerate()
        .map(|(idx, item)| (item.clone(), idx))
        .collect();

    // Split into items present in B and those not
    let (in_b, not_in_b): (Vec<_>, Vec<_>) = a.iter()
        .partition(|item| order_indices.contains_key(*item));

    // Sort items present in B according to their indices
    let mut sorted_in_b: Vec<_> = in_b.into_iter()
        .map(|item| (item, order_indices[item]))
        .collect();

    sorted_in_b.sort_by_key(|(_, idx)| *idx);

    // Collect results: items not in B followed by items in B in sorted order
    let mut result = not_in_b.into_iter().cloned().collect::<Vec<_>>();
    result.extend(sorted_in_b.into_iter().map(|(item, _)| item.clone()));

    result
}

fn main() {
    let a = vec![3, 1, 2, 5, 4];
    let b = vec![2, 1, 3];

    let sorted = custom_sort(&a, &b);
    println!("{:?}", sorted); // Output: [5, 4, 2, 1, 3]
}
