/// * `b` - The reference list that defines the sort order (must be sorted)
/// 
/// # Returns
/// A new sorted vector where items not in B come first, followed by items in B's order
/// 
/// # Time Complexity
/// O(n + m) where n = len(a) and m = len(b)
/// 
/// # Space Complexity
/// O(m) for the HashMap storing B's order indices
pub fn sort_by_list<T: Clone + Eq + std::hash::Hash>(a: Vec<T>, b: &[T]) -> Vec<T> {
    // Create a HashMap of items in B with their order indices
    // This allows O(1) lookup of an item's position in B
    let order_map: HashMap<&T, usize> = b
        .iter()
        .enumerate()
        .map(|(index, item)| (item, index))
        .collect();

    // Separate items into two groups: those in B and those not in B
    let mut in_b = Vec::new();
    let mut not_in_b = Vec::new();

    for item in a {
        if order_map.contains_key(&item) {
            in_b.push(item);
        } else {
            not_in_b.push(item);
        }
    }

    // Sort items that are in B according to their order in B
    in_b.sort_by_key(|item| order_map[item]);

    // Combine: items not in B come first, followed by items in B's order
    let mut result = not_in_b;
    result.extend(in_b);

    result
}

