/// - Setting all even positions to zero
///
/// Returns a tuple of three sequences (subtract_1, subtract_0, subtract_neg_1)
pub fn create_transformed_sequences<T>(input: &Sequence<T>) -> (Sequence<T>, Sequence<T>, Sequence<T>)
where
    T: Clone + std::ops::Sub<Output = T> + std::ops::Add<Output = T>,
    T: std::ops::Mul<Output = T> + std::ops::Div<Output = T>,
    T: PartialEq + PartialOrd,
    T: From<i64>,
{
