    let zero = T::from(0);

    // Create the three sequences
    let subtract_1 = input
        .enumerate()
        .map(|(i, val)| {
            if (i + 1) % 2 == 1 {  // odd position (1-based)
                val.clone() - T::from(1)
            } else {
                zero.clone()
            }
        })
        .collect();

    let subtract_0 = input
        .enumerate()
        .map(|(i, val)| {
            if (i + 1) % 2 == 1 {  // odd position (1-based)
                val.clone()
            } else {
                zero.clone()
            }
