        .collect();

    let subtract_neg_1 = input
        .enumerate()
        .map(|(i, val)| {
            if (i + 1) % 2 == 1 {  // odd position (1-based)
                val.clone() + T::from(1)
            } else {
                zero.clone()
            }
        })
        .collect();

    (subtract_1, subtract_0, subtract_neg_1)
}

