```rust
use std::collections::HashMap;

mod assoc_map_sorter {
    use std::collections::HashMap;

    /// Sorts `maps` in-place according to the order defined by `order_list`.
    /// `key_fn` is a function that extracts (optionally) the value to be looked up in `order_list`.
    /// Values not found in `order_list` are treated as having the largest rank (i.e., sorted to the end).
    pub fn sort_by_order<F>(
        maps: &mut Vec<HashMap<String, String>>,
        order_list: &[String],
        key_fn: F,
    )
    where
        F: Fn(&HashMap<String, String>) -> Option<String>,
    {
        // Build a ranking map from value -> index for quick lookup.
        let order_map: HashMap<String, usize> = order_list
            .iter()
            .cloned()
            .enumerate()
            .map(|(i, v)| (v, i))
            .collect();

        // Sort in place by the rank of the extracted key; missing/not-found -> usize::MAX.
        maps.sort_by_key(|m| {
            key_fn(m)
                .and_then(|k| order_map.get(&k).cloned())
                .unwrap_or(usize::MAX)
        });
    }
}

