Here is a self-contained Rust function that sorts a list of integers in ascending order. It uses a small, local "list_sort" module (merge sort implementation) and returns a new Vec with the sorted values.

```rust
// Self-contained module implementing a simple "list_sort" library (merge sort).
mod list_sort {
    /// Sorts a slice and returns a new Vec with elements in ascending order.
    /// Uses merge sort; T must implement Ord + Clone.
    pub fn sort<T: Ord + Clone>(input: &[T]) -> Vec<T> {
        let n = input.len();
        if n <= 1 {
            return input.to_vec();
        }

        let mid = n / 2;
        let left = sort(&input[..mid]);
        let right = sort(&input[mid..]);

        merge(&left, &right)
    }

    fn merge<T: Ord + Clone>(left: &[T], right: &[T]) -> Vec<T> {
        let mut out = Vec::with_capacity(left.len() + right.len());
        let (mut i, mut j) = (0, 0);

        while i < left.len() && j < right.len() {
            if left[i] <= right[j] {
                out.push(left[i].clone());
                i += 1;
            } else {
                out.push(right[j].clone());
                j += 1;
            }
        }

        if i < left.len() {
            out.extend_from_slice(&left[i..]);
        }
        if j < right.len() {
            out.extend_from_slice(&right[j..]);
        }

        out
    }
}

// Public function that meets the requirement.
// Given a list `lst0` whose elements represent integer values,
// return a new list with all elements arranged in ascending numeric order.
