/// let result = frequency_sort(&input);
/// // 3 appears 4 times, 1 appears 3 times, 2 appears 2 times
/// // Result: [3, 3, 3, 3, 1, 1, 1, 2, 2]
/// ```
pub fn frequency_sort<T: Clone + Eq + std::hash::Hash>(collection: &[T]) -> Vec<T> {
    // Count frequencies of each element
    let mut frequency_map: HashMap<&T, usize> = HashMap::new();
    for item in collection {
        *frequency_map.entry(item).or_insert(0) += 1;
