```rust
use std::collections::HashMap;
use std::cmp::Ordering;

/// A tiny self-contained "dataframe-filter" like module for demonstration.
/// It defines a basic Value type, a Condition operator enum, a DataFrame type,
/// and a filter implementation applying a list of conditions (AND semantics).
mod dataframe_filter {
    use super::*;

    #[derive(Clone, Debug)]
    pub enum Value {
        Int(i64),
        Float(f64),
        Str(String),
        Bool(bool),
    }

    impl Value {
        // Try to get numeric representation for Int/Float
        fn as_f64(&self) -> Option<f64> {
            match self {
                Value::Int(i) => Some(*i as f64),
                Value::Float(f) => Some(*f),
                _ => None,
            }
        }

        fn as_str(&self) -> Option<&str> {
            match self {
                Value::Str(s) => Some(s),
                _ => None,
            }
        }

        fn as_bool(&self) -> Option<bool> {
            match self {
                Value::Bool(b) => Some(*b),
                _ => None,
            }
        }

        // Equality handling across numeric types and exact matches for others
        fn eq_value(&self, other: &Value) -> bool {
            match (self, other) {
                (Value::Int(_), Value::Float(_)) |
                (Value::Float(_), Value::Int(_)) |
                (Value::Int(_), Value::Int(_)) |
                (Value::Float(_), Value::Float(_)) => {
                    match (self.as_f64(), other.as_f64()) {
                        (Some(a), Some(b)) => (a - b).abs() < std::f64::EPSILON,
                        _ => false,
                    }
                }
                (Value::Str(a), Value::Str(b)) => a == b,
                (Value::Bool(a), Value::Bool(b)) => a == b,
                _ => false,
            }
        }

        // Compare, only for numeric values
        fn partial_cmp_numeric(&self, other: &Value) -> Option<Ordering> {
            match (self.as_f64(), other.as_f64()) {
                (Some(a), Some(b)) => a.partial_cmp(&b),
                _ => None,
            }
        }
    }

    // Operator for a condition. Contains any literal values it needs.
    #[derive(Clone, Debug)]
    pub enum Operator {
        Eq(Value),
        Neq(Value),
        Lt(Value),
        Lte(Value),
        Gt(Value),
        Gte(Value),
        Contains(String),         // substring for string columns
        In(Vec<Value>),           // membership in given set
        Between(Value, Value),    // inclusive between
    }

    #[derive(Clone, Debug)]
    pub struct Condition {
        pub column: String,
        pub op: Operator,
    }

    pub type Row = HashMap<String, Value>;

    #[derive(Clone, Debug)]
    pub struct DataFrame {
        pub rows: Vec<Row>,
    }

    impl DataFrame {
        pub fn new(rows: Vec<Row>) -> Self {
            DataFrame { rows }
        }

        /// Filter the dataframe with an AND of all provided conditions.
        pub fn filter(&self, conditions: &[Condition]) -> DataFrame {
            let mut out_rows = Vec::new();
            'row_loop: for row in &self.rows {
                for cond in conditions {
                    let cell = match row.get(&cond.column) {
                        Some(v) => v,
                        None => {
                            // missing column -> condition fails
                            continue 'row_loop;
                        }
                    };

                    let matched = match &cond.op {
                        Operator::Eq(v) => cell.eq_value(v),
                        Operator::Neq(v) => !cell.eq_value(v),
                        Operator::Lt(v) => {
                            match cell.partial_cmp_numeric(v) {
                                Some(Ordering::Less) => true,
                                _ => false,
                            }
                        }
                        Operator::Lte(v) => {
                            match cell.partial_cmp_numeric(v) {
                                Some(Ordering::Less) | Some(Ordering::Equal) => true,
                                _ => false,
                            }
                        }
                        Operator::Gt(v) => {
                            match cell.partial_cmp_numeric(v) {
                                Some(Ordering::Greater) => true,
                                _ => false,
                            }
                        }
                        Operator::Gte(v) => {
                            match cell.partial_cmp_numeric(v) {
                                Some(Ordering::Greater) | Some(Ordering::Equal) => true,
                                _ => false,
                            }
                        }
                        Operator::Contains(sub) => {
                            match cell.as_str() {
                                Some(s) => s.contains(sub),
                                None => false,
                            }
                        }
                        Operator::In(set) => {
                            let mut found = false;
                            for v in set {
                                if cell.eq_value(v) {
                                    found = true;
                                    break;
                                }
                            }
                            found
                        }
                        Operator::Between(a, b) => {
                            match (cell.partial_cmp_numeric(a), cell.partial_cmp_numeric(b)) {
                                (Some(lo_cmp), Some(hi_cmp)) => {
                                    // lo_cmp should be >= Equal (cell >= a) and hi_cmp <= Equal (cell <= b)
                                    (lo_cmp == Ordering::Greater || lo_cmp == Ordering::Equal) &&
                                    (hi_cmp == Ordering::Less || hi_cmp == Ordering::Equal)
                                }
                                _ => false,
                            }
                        }
                    };

                    if !matched {
                        continue 'row_loop;
                    }
                } // end for cond
                out_rows.push(row.clone());
            } // end for row

            DataFrame::new(out_rows)
        }
    }
}

