Function signature:
- Input:
  - labels: slice of label-like values (anything implementing AsRef<str>) of length = number of columns
  - rows: slice of rows, each a Vec<f64>, shape = n_rows x n_cols
- Output:
  - Result containing (group_labels, grouped_rows) where:
    - group_labels: Vec<String> (unique labels in order)
    - grouped_rows: Vec<Vec<f64>> with shape n_rows x n_groups
- Returns Err(&'static str) on inconsistent input (e.g., row lengths differ from label count)

Code:

```rust
use std::collections::HashMap;

/// Group columns by their labels and sum values within each group.
///
/// - `labels`: a slice of labels with length equal to the number of columns.
/// - `rows`: a slice of rows; each row is a Vec<f64> with length equal to labels.len().
///
/// Returns Ok((group_labels, grouped_rows)) on success:
/// - `group_labels` is the unique labels (in the order of first appearance).
/// - `grouped_rows` is the table after grouping/aggregation (n_rows x n_groups).
///
/// Returns Err(&'static str) if input dimensions are inconsistent.
pub fn group_columns_by_label_sum<S: AsRef<str>>(
    labels: &[S],
    rows: &[Vec<f64>],
) -> Result<(Vec<String>, Vec<Vec<f64>>), &'static str> {
    let n_cols = labels.len();

    // Build group mapping: label -> group index, preserving first-seen order.
    let mut group_index: HashMap<String, usize> = HashMap::new();
    let mut group_labels: Vec<String> = Vec::new();
    for label in labels {
        let s = label.as_ref().to_string();
        if !group_index.contains_key(&s) {
            let idx = group_labels.len();
            group_index.insert(s.clone(), idx);
            group_labels.push(s);
        }
    }

    let n_groups = group_labels.len();
    let n_rows = rows.len();

    // If there are zero rows, return empty grouped_rows with zero rows.
    if n_rows == 0 {
        return Ok((group_labels, Vec::new()));
    }

    // Validate row lengths
    for row in rows {
        if row.len() != n_cols {
            return Err("All rows must have the same length as labels");
        }
    }

    // Precompute column -> group index mapping for speed
    let mut col_to_group: Vec<usize> = Vec::with_capacity(n_cols);
    for label in labels {
        let key = label.as_ref();
        // unwrap is safe because group_index was constructed from the same labels slice
        col_to_group.push(*group_index.get(key).unwrap());
    }

    // Initialize output table: n_rows x n_groups with zeros.
    let mut grouped_rows: Vec<Vec<f64>> = vec![vec![0.0; n_groups]; n_rows];

    // Accumulate sums: for each column, add its values to the corresponding group column.
    for (col_idx, &gidx) in col_to_group.iter().enumerate() {
        for row_idx in 0..n_rows {
            grouped_rows[row_idx][gidx] += rows[row_idx][col_idx];
        }
    }

    Ok((group_labels, grouped_rows))
}

#[cfg(test)]
