fn group_columns_and_sum(
    table: Vec<Vec<f64>>,
    column_labels: Vec<&str>,
    group_labels: Vec<&str>,
) -> Vec<(String, f64)> {
    // Create a mapping from column label to group label
    let label_to_group: std::collections::HashMap<&str, &str> = column_labels
        .iter()
        .zip(group_labels.iter())
        .map(|(label, group)| (*label, *group))
        .collect();

    // Collect all unique groups while preserving order
    let mut groups: Vec<&str> = Vec::new();
    for group in &group_labels {
        if !groups.contains(group) {
            groups.push(group);
        }
    }

    // Compute sums for each group
    let mut result: Vec<(String, f64)> = Vec::new();

    for group in groups {
        let mut group_sum = 0.0;

        // Sum all columns that belong to this group
        for (col_idx, col_label) in column_labels.iter().enumerate() {
            if let Some(&g) = label_to_group.get(col_label) {
                if g == group {
                    // Sum all values in this column
                    for row in &table {
                        if col_idx < row.len() {
                            group_sum += row[col_idx];
                        }
                    }
                }
            }
        }

        result.push((group.to_string(), group_sum));
