/// Sum the products of every unique subset of `values` that has exactly `k` elements.
///
/// - values: slice of integers (i128). Elements are treated by position (combinations of indices).
/// - k: the subset size (0 <= k <= values.len()).
///
/// Returns the sum of the product of elements for every k-element subset.
///
/// Examples:
/// ```
/// let v = [2i128, 3, 5];
/// // 2-element subsets: {2,3}, {2,5}, {3,5} -> products 6, 10, 15 -> sum = 31
/// assert_eq!(sum_of_k_products(&v, 2), 31);
///
/// // 0-element subset: product of empty set defined as 1
/// assert_eq!(sum_of_k_products(&v, 0), 1);
/// ```
pub fn sum_of_k_products(values: &[i128], k: usize) -> i128 {
    // Optional: if you compiled with feature "use_subset_sum_product" and the crate is available,
    // call into it. Otherwise, fall back to the local DP algorithm below.
    #[cfg(all(feature = "use_subset_sum_product"))]
    {
        // This assumes the external crate provides a function like:
        // pub fn sum_of_products(values: &[i128], k: usize) -> i128
        // Adjust this call to the real crate API if different.
        return subset_sum_product::sum_of_products(values, k);
    }

    // Local DP implementation (elementary symmetric sums).
    let n = values.len();
    if k > n {
        return 0;
    }
    // e[j] will hold the sum of products for j-element subsets seen so far.
    let mut e = vec![0i128; k + 1];
    e[0] = 1; // empty-product = 1

    for &v in values {
        // Update from high to low so each value is used at most once per subset.
        let upper = std::cmp::min(k, n); // just for clarity; k <= n already ensured
        for j in (1..=k).rev() {
            // e[j] += e[j-1] * v
            e[j] = e[j].saturating_add(e[j - 1].saturating_mul(v));
            // Note: using saturating_ ops to avoid panics on overflow; remove if you prefer wrapping arithmetic.
        }
    }

    e[k]
}

