        // Sum = 35
        assert_eq!(result, 35);
    }

    #[test]
    fn test_single_element_subsets() {
        let values = vec![2, 3, 5];
        let result = sum_of_subset_products(&values, 1);
        // [2]=2, [3]=3, [5]=5
        // Sum = 10
        assert_eq!(result, 10);
    }

    #[test]
    fn test_full_set() {
        let values = vec![2, 3, 4];
        let result = sum_of_subset_products(&values, 3);
        // [2,3,4]=24
        assert_eq!(result, 24);
    }

    #[test]
    fn test_empty_result() {
        let values = vec![1, 2, 3];
        let result = sum_of_subset_products(&values, 5);
        // No subsets of size 5 from 3 elements
        assert_eq!(result, 0);
    }

    #[test]
