        let cols = cols_in
            .into_iter()
            .map(|(k, v)| (k, Column::Strings(v)))
            .collect();
        DataFrame { cols, nrows }
    }

    /// Helper to get a reference to a string column, if present.
    fn get_string_column(&self, name: &str) -> Option<&Vec<String>> {
        match self.cols.get(name) {
            Some(Column::Strings(v)) => Some(v),
            _ => None,
        }
    }
}

