/// let df = df!(
///     "col0" => &["cat", "dog", "cat", "bird", "dog"]
/// ).unwrap();
///
/// let result = map_categorical_to_indices(df, "col0").unwrap();
/// println!("{:?}", result);
/// // Output will show col0 with values [0, 1, 0, 2, 1]
/// ```
pub fn map_categorical_to_indices(
    df0: DataFrame,
    col0: &str,
) -> Result<DataFrame, PolarsError> {
    // Extract the categorical column as a Series
    let series = df0.column(col0)?.clone();

    // Convert to string series (handles both Utf8 and Categorical types)
    let string_series = series.str()?;

    // Collect all unique values
    let unique_values: Vec<&str> = string_series.unique()?.str()?.into_iter()
        .filter_map(|opt| opt)
        .collect();

    // Create an indexer and map each unique value to an index
    let mut indexer = Indexer::new();
    for value in &unique_values {
        indexer.insert(value);
    }

    // Map each original value to its index
    let indices: Vec<u32> = string_series.into_iter()
        .map(|opt| {
            match opt {
                Some(val) => indexer.index(val).unwrap_or(0) as u32,
                None => 0, // Handle null values by assigning index 0
            }
        })
        .collect();

    // Create a new Series with the indices
    let indexed_series = Series::new(col0, indices);

    // Replace the original column in the DataFrame
    let mut df = df0;
    df.replace(col0, indexed_series)?;

    Ok(df)
}

// Alternative implementation that returns the indexer for later use
