Below is a self-contained Rust function that deletes (in-place) every column that is all zeros from a tabular dataset represented as Vec<Vec<f64>>. It does not depend on any external crates and preserves row order. If rows have different lengths the missing entries are treated as zeros.

Usage example is included.

```rust
/// Remove all columns that contain only zeros across every row.
/// The table is modified in-place: columns that are all zero are removed.
///
/// Representation:
/// - table: Vec of rows, each row is Vec<f64>.
/// - Rows may have different lengths; missing entries are considered zero.
///
/// Example:
/// let mut table = vec![
///     vec![1.0, 0.0, 3.0],
///     vec![0.0, 0.0, 4.0],
/// ];
/// drop_zero_columns(&mut table);
/// // table == vec![vec![1.0, 3.0], vec![0.0, 4.0]]
pub fn drop_zero_columns(table: &mut Vec<Vec<f64>>) {
    // Fast exit
    if table.is_empty() {
        return;
    }

    // Determine maximum number of columns present in any row
    let ncols = table.iter().map(|r| r.len()).max().unwrap_or(0);
    if ncols == 0 {
        return;
    }

    // For each column index, check if any row has a non-zero value at that index
    let mut keep = vec![false; ncols];
    for j in 0..ncols {
        for row in table.iter() {
            let val = if j < row.len() { row[j] } else { 0.0 };
            if val != 0.0 {
                keep[j] = true;
                break;
            }
        }
    }

    // Collect indices of columns to keep (in order)
    let kept_indices: Vec<usize> = keep.iter()
        .enumerate()
        .filter_map(|(i, &k)| if k { Some(i) } else { None })
        .collect();

    // If nothing was kept, clear all rows
    if kept_indices.is_empty() {
        for row in table.iter_mut() {
            row.clear();
        }
        return;
    }

    // Rebuild each row with only kept columns (missing entries treated as zero)
    for row in table.iter_mut() {
        let mut new_row = Vec::with_capacity(kept_indices.len());
        for &col_idx in &kept_indices {
            let v = if col_idx < row.len() { row[col_idx] } else { 0.0 };
            new_row.push(v);
        }
        *row = new_row;
    }
}

fn main() {
    let mut table = vec![
        vec![1.0, 0.0, 3.0, 0.0],
        vec![0.0, 0.0, 4.0, 0.0],
        vec![2.0, 0.0, 0.0, 0.0],
    ];

    drop_zero_columns(&mut table);

    println!("{:?}", table);
    // prints: [[1.0, 3.0], [0.0, 4.0], [2.0, 0.0]]
}
```

