fn replace_missing_values_generic<T: Copy>(
    primary_column: Vec<Option<T>>,
    fallback_column: Vec<Option<T>>,
) -> Vec<Option<T>> {
    primary_column
        .iter()
        .zip(fallback_column.iter())
        .map(|(primary, fallback)| primary.or(*fallback))
        .collect()
}

