    #[test]
    fn test_sort_by_weight_and_factor() {
        let mut items = vec![
            {
                let mut m = HashMap::new();
                m.insert("weight".to_string(), 10);
                m.insert("factor".to_string(), 5);
                m
            },
            {
                let mut m = HashMap::new();
                m.insert("weight".to_string(), 10);
                m.insert("factor".to_string(), 3);
                m
            },
            {
                let mut m = HashMap::new();
                m.insert("weight".to_string(), 5);
                m.insert("factor".to_string(), 8);
                m
            },
        ];

        let sorted = sort_by_weight_and_factor(items);

        // Verify sorting
        assert_eq!(sorted[0].get("weight").unwrap(), &5);
        assert_eq!(sorted[1].get("weight").unwrap(), &10);
        assert_eq!(sorted[1].get("factor").unwrap(), &3); // Should come before factor=5
        assert_eq!(sorted[2].get("factor").unwrap(), &5);
    }
}
```

## Key Features:

1. **Efficient Sorting**: Uses Rust's built-in `sort_by()` with a custom comparator—O(n log n) complexity
2. **Concise**: Leverages pattern matching and `cmp()` for clean tie-breaking logic
3. **Safe**: Uses `unwrap_or(0)` to handle missing fields gracefully
4. **Well-tested**: Includes comprehensive test cases demonstrating the sorting behavior

