/// A `Result` containing a vector of column indices that have at least one null value,
/// or an error if the operation fails.
///
/// # Example
/// ```
/// use table_nulls::TableNulls;
/// use polars::prelude::*;
///
/// fn main() -> Result<(), Box<dyn Error>> {
///     let df = df!(
///         "data" => &[Some(1), None, Some(3)],
///         "name" => &[Some("Alice"), Some("Bob"), None]
///     )?;
///
///     let null_columns = find_columns_with_nulls(&df)?;
///     println!("Columns with nulls: {:?}", null_columns);
///     Ok(())
/// }
/// ```
pub fn find_columns_with_nulls<T>(table: &T) -> Result<Vec<usize>, Box<dyn Error>>
where
    T: TableNulls,
{
    // Get the number of columns in the table
    let num_columns = table.num_columns();

    // Check each column for nulls
    let mut null_columns = Vec::new();
    for col_idx in 0..num_columns {
        if table.has_nulls(col_idx) {
            null_columns.push(col_idx);
        }
    }

    Ok(null_columns)
}
