/// Assumes each row has at least `n_cols` cells; extra cells are ignored.
pub fn columns_with_missing<T>(rows: &[Vec<Option<T>>]) -> Vec<bool> {
    if rows.is_empty() {
        return Vec::new();
    }
    let n_cols = rows[0].len();
