use decision_tree_rules::{extract_rules, Rule};
use std::fmt;

// Define a struct to hold the decision tree and feature names
struct DecisionTreeModel {
    tree: decision_tree_rules::DecisionTree,
    feature_names: Vec<String>,
}

// Implement a method to extract and print human-readable rules
impl DecisionTreeModel {
    fn extract_human_readable_rules(&self) -> Vec<String> {
        let rules: Vec<Rule> = extract_rules(&self.tree);
        rules.into_iter().map(|rule| self.format_rule(rule)).collect()
    }

    fn format_rule(&self, rule: Rule) -> String {
        let conditions: Vec<String> = rule
            .conditions
            .iter()
            .map(|condition| {
                let feature_name = &self.feature_names[condition.feature_index];
                match condition.operator {
                    decision_tree_rules::Operator::Lt => format!("{} < {}", feature_name, condition.threshold),
                    decision_tree_rules::Operator::Le => format!("{} <= {}", feature_name, condition.threshold),
                    decision_tree_rules::Operator::Gt => format!("{} > {}", feature_name, condition.threshold),
                    decision_tree_rules::Operator::Ge => format!("{} >= {}", feature_name, condition.threshold),
                    decision_tree_rules::Operator::Eq => format!("{} == {}", feature_name, condition.threshold),
                    decision_tree_rules::Operator::Ne => format!("{} != {}", feature_name, condition.threshold),
                }
            })
            .collect();

        let condition_str = conditions.join(" && ");
