use serde_json::Value;
use std::collections::{HashMap, HashSet};

/// A "table" represented as an ordered list of (column_name, column_values).
/// Each column_values Vec<Value> must have the same length (same number of rows).
pub type Table = Vec<(String, Vec<Value>)>;

/// Merge `new_cols` onto `base` and return a table whose columns are ordered so that:
/// - The relative order of all non-priority columns is preserved (as they appear in base then new).
/// - The columns listed in `priority_order` appear in exactly that sequence (if they exist).
/// - If a column exists in both base and new, the values from `new_cols` override the base's values.
/// Behavior:
/// - initial order is base column order followed by any new columns not present in base (in new's order).
/// - all priority columns found in the initial order are removed from their old positions and THEN
///   inserted (in the priority list order) at the index of the earliest occurrence of any priority
///   column in the initial order. If no priority columns are present, initial order is returned unchanged.
///
/// Returns a new Table with columns in the computed order.
/// Panics if the input columns do not all have the same number of rows.
pub fn merge_tables_with_priority(
    base: &Table,
    new_cols: &Table,
    priority_order: &[&str],
) -> Table {
    // Validate row counts and build a map name -> column values (new overrides base)
    let mut row_count: Option<usize> = None;
    let mut col_map: HashMap<String, Vec<Value>> = HashMap::new();

    for (name, vals) in base.iter().chain(new_cols.iter()) {
        if let Some(expected) = row_count {
            if vals.len() != expected {
                panic!(
                    "All columns must have the same number of rows. Column '{}' has length {}, expected {}.",
                    name,
                    vals.len(),
                    expected
                );
            }
        } else {
            row_count = Some(vals.len());
        }
        // Insert or overwrite: later (new_cols) override earlier (base)
        col_map.insert(name.clone(), vals.clone());
    }

    let row_count = row_count.unwrap_or(0);

    // Build initial order: base order followed by any new column names not present in base (in new_cols order)
    let mut initial_order: Vec<String> = Vec::new();
    let mut seen: HashSet<String> = HashSet::new();

    for (name, _) in base {
        initial_order.push(name.clone());
        seen.insert(name.clone());
    }
    for (name, _) in new_cols {
        if !seen.contains(name) {
            initial_order.push(name.clone());
            seen.insert(name.clone());
        }
    }

    // Determine which priority names are actually present in initial_order
    let priority_set: HashSet<&str> = priority_order.iter().cloned().collect();
    let mut present_priority_names: Vec<String> = priority_order
        .iter()
        .filter_map(|&p| {
            if initial_order.iter().any(|n| n == p) {
                Some(p.to_string())
            } else {
                None
            }
        })
        .collect();

    // If no priority columns are present, return initial order mapped to actual columns.
    if present_priority_names.is_empty() {
        return initial_order
            .into_iter()
            .filter_map(|name| col_map.remove(&name).map(|vals| (name, vals)))
            .collect();
    }

    // Find the earliest index in initial_order at which any priority column appears.
    let mut min_index: Option<usize> = None;
    for (i, name) in initial_order.iter().enumerate() {
        if priority_set.contains(name.as_str()) {
            min_index = Some(i);
            break;
        }
    }
    let min_index = min_index.unwrap_or(initial_order.len());

    // Remove all priority columns from initial_order while preserving order of the rest.
    let mut non_priority: Vec<String> = Vec::with_capacity(initial_order.len());
    for name in initial_order.into_iter() {
        if !priority_set.contains(name.as_str()) {
            non_priority.push(name);
        }
    }

    // Insert the present priority names in the exact priority_order sequence at min_index.
    let mut final_order: Vec<String> = Vec::with_capacity(non_priority.len() + present_priority_names.len());
    // prefix
    for (i, name) in non_priority.iter().enumerate() {
        if i == min_index {
            // insert priority chunk
            for p in &present_priority_names {
                final_order.push(p.clone());
            }
        }
        final_order.push(name.clone());
    }
    // if min_index was at or beyond the end, append priorities at the end
    if min_index >= non_priority.len() {
        for p in &present_priority_names {
            final_order.push(p.clone());
        }
    }

    // Build final table from col_map according to final_order.
    let mut result: Table = Vec::with_capacity(final_order.len());
    for name in final_order {
        if let Some(vals) = col_map.remove(&name) {
            result.push((name, vals));
        }
    }

    // As a sanity: any remaining columns in col_map (shouldn't happen) are appended in unspecified order.
    for (name, vals) in col_map.into_iter() {
        result.push((name, vals));
    }

    // Optionally assert row lengths are consistent in the result
    for (_, vals) in &result {
        if vals.len() != row_count {
            panic!("Inconsistent row counts in final table.");
        }
    }

    result
}

