use table_column_order::ColumnOrder;
use std::collections::{HashMap, BTreeMap};

/// Merges a base table with new columns while preserving a specified column order.
///
/// # Arguments
/// * `base_table` - A HashMap representing the base table with column names as keys
/// * `new_columns` - A HashMap containing new columns to add to the base table
/// * `priority_order` - A Vec of column names defining the desired order for specified columns
///
/// # Returns
/// A BTreeMap with columns ordered according to the priority_order, followed by
/// remaining columns in their original relative positions.
///
/// # Example
/// ```
/// use std::collections::HashMap;
///
/// let mut base = HashMap::new();
/// base.insert("id".to_string(), vec![1, 2, 3]);
/// base.insert("name".to_string(), vec!["a", "b", "c"]);
/// base.insert("age".to_string(), vec![25, 30, 35]);
///
/// let mut new_cols = HashMap::new();
/// new_cols.insert("email".to_string(), vec!["x@test.com", "y@test.com", "z@test.com"]);
///
/// let priority = vec!["name".to_string(), "email".to_string(), "id".to_string()];
///
/// let result = merge_tables_with_order(&base, &new_cols, &priority);
/// // Result will have columns in order: name, email, id, age
/// ```
pub fn merge_tables_with_order<T: Clone>(
    base_table: &HashMap<String, Vec<T>>,
    new_columns: &HashMap<String, Vec<T>>,
    priority_order: &[String],
) -> BTreeMap<usize, (String, Vec<T>)> {
    // Create a merged map of all columns
    let mut all_columns = base_table.clone();
    for (col_name, col_data) in new_columns {
        all_columns.insert(col_name.clone(), col_data.clone());
    }

    // Track which columns have been placed
    let mut placed_columns = std::collections::HashSet::new();
    let mut ordered_columns: BTreeMap<usize, (String, Vec<T>)> = BTreeMap::new();
    let mut position = 0;

    // First, place columns according to priority_order
    for col_name in priority_order {
        if let Some(col_data) = all_columns.get(col_name) {
            ordered_columns.insert(position, (col_name.clone(), col_data.clone()));
            placed_columns.insert(col_name.clone());
            position += 1;
        }
    }

    // Then, add remaining columns from base_table in their original order
    for (col_name, col_data) in base_table {
        if !placed_columns.contains(col_name) {
            ordered_columns.insert(position, (col_name.clone(), col_data.clone()));
            placed_columns.insert(col_name.clone());
            position += 1;
        }
    }

    // Finally, add any remaining new columns not in base_table
    for (col_name, col_data) in new_columns {
        if !placed_columns.contains(col_name) {
            ordered_columns.insert(position, (col_name.clone(), col_data.clone()));
            position += 1;
        }
    }

    ordered_columns
}

/// Helper function to convert the ordered result back to a HashMap with preserved order info
pub fn get_column_names_in_order<T>(
    ordered_table: &BTreeMap<usize, (String, Vec<T>)>,
) -> Vec<String> {
    ordered_table
        .values()
        .map(|(name, _)| name.clone())
        .collect()
}

