```rust
use df_multiindex::prelude::*;
use polars::prelude::*;

/// Groups a DataFrame by a column and creates a new DataFrame with a hierarchical index
///
/// # Arguments
/// * `df` - The input DataFrame to group
/// * `group_by_col` - The column name to group by
///
/// # Returns
/// A new DataFrame with a hierarchical index where the first level is the group values
///
/// # Example
/// ```
/// use polars::prelude::*;
/// use df_multiindex::prelude::*;
///
/// let df = df!(
///     "var0" => &[1, 1, 2, 2, 3],
///     "value" => &[10, 20, 30, 40, 50]
/// )?;
///
/// let result = group_to_multiindex(df, "var0")?;
/// println!("{:?}", result);
/// ```
pub fn group_to_multiindex(df: DataFrame, group_by_col: &str) -> Result<DataFrame, PolarsError> {
    // Group the data by the specified column
    let grouped = df.lazy()
        .group_by([group_by_col])
        .agg_all()?
        .collect()?;

    // Create a new column with the group values (this will be our first level of the index)
    let group_values = grouped.column(group_by_col)?;

    // Create a new DataFrame without the group column (we'll use it for the index)
    let mut new_df = grouped.clone();

    // Remove the group column from the DataFrame
    new_df = new_df.drop(group_by_col)?;

    // Create a new index with the group values
    let index = Index::new(group_values);

    // Set the new index
    new_df.with_index(Some(index))?;

    Ok(new_df)
}

#[cfg(test)]
mod tests {
    use super::*;
    use polars::prelude::*;

    #[test]
    fn test_group_to_multiindex() {
        let df = df!(
            "var0" => &[1, 1, 2, 2, 3],
            "value" => &[10, 20, 30, 40, 50]
        ).unwrap();

        let result = group_to_multiindex(df, "var0").unwrap();

        // Verify the result has the correct structure
        assert_eq!(result.height(), 3); // One row per group
        assert_eq!(result.width(), 2); // All columns except var0

        // Check the index
        let index = result.index().unwrap();
        assert_eq!(index.len(), 3);
        assert_eq!(index.get(0).unwrap().to_string(), "1");
        assert_eq!(index.get(1).unwrap().to_string(), "2");
        assert_eq!(index.get(2).unwrap().to_string(), "3");
    }
}
```

