    //    (adjust `.utf8()` / `.as_str()` calls per the crate API if needed).
    let col_series = df0.column(var0)?;
    let col_iter = col_series.utf8()?; // assume utf8() gives an iterator over Option<&str>

    // 2) Build groups: map each distinct key -> vector of row indices in df0
    let mut groups: HashMap<String, Vec<usize>> = HashMap::new();
    for (idx, opt_val) in col_iter.into_iter().enumerate() {
        // treat None as empty string; adjust as desired
        let key = opt_val.unwrap_or("").to_string();
        groups.entry(key).or_default().push(idx);
    }

    // 3) For each group, build a sub-DataFrame and attach a two-level MultiIndex
