pub fn group_by_to_hierarchical_index(
    df0: DataFrame,
    var0: &str,
) -> Result<DataFrame, Box<dyn std::error::Error>> {
    // Validate that the grouping column exists
    if !df0.get_column_names().contains(&var0.to_string()) {
        return Err(format!("Column '{}' not found in DataFrame", var0).into());
    }

    // Get the grouping column and remove it from the main DataFrame
    let group_column = df0.column(var0)?.clone();
    let mut df_without_group = df0.drop(var0)?;

    // Get unique values from the grouping column
    let unique_groups: Vec<AnyValue> = group_column.unique()?.into_iter().collect();

    // Create a new DataFrame with the hierarchical index
    let mut hierarchical_df = DataFrame::default();

    // Add the grouping column as the first level of the index
    let group_series = Series::new("group", unique_groups.clone());
    hierarchical_df = hierarchical_df.with_column(group_series)?;

    // For each unique group, filter the original data and add it
    for group_value in &unique_groups {
        // Create a boolean mask for rows matching this group
        let mask: ChunkedArray<BooleanType> = group_column
            .equal(group_value)?
            .into_series()
            .bool()?
            .clone();

        // Filter the DataFrame without the group column
        let filtered_df = df_without_group.filter(&mask)?;

        // Add the filtered data with the group value as prefix for column names
        for col_name in filtered_df.get_column_names() {
            let new_col_name = format!("{}_{}", group_value.to_string(), col_name);
            let col_data = filtered_df.column(&col_name)?;
            hierarchical_df = hierarchical_df.with_column(
                Series::new(&new_col_name, col_data)
