```rust
use std::collections::HashMap;

/// Sorts a list of associative records by a specified key according to a custom order.
///
/// # Arguments
/// * `records` - A mutable slice of hashmaps representing associative records
/// * `sort_key` - The key in the hashmaps to sort by
/// * `order_sequence` - A sequence defining the desired order of values
///
/// # Example
/// ```
/// use std::collections::HashMap;
///
/// let mut records = vec![
///     {
///         let mut m = HashMap::new();
///         m.insert("color", "red");
///         m.insert("name", "apple");
///         m
///     },
///     {
///         let mut m = HashMap::new();
///         m.insert("color", "green");
///         m.insert("name", "lime");
///         m
///     },
///     {
///         let mut m = HashMap::new();
///         m.insert("color", "red");
///         m.insert("name", "cherry");
///         m
///     },
/// ];
///
/// let order = vec!["green", "red", "blue"];
/// sort_by_keyed_order(&mut records, "color", &order);
/// ```
fn sort_by_keyed_order(
    records: &mut [HashMap<&str, &str>],
    sort_key: &str,
    order_sequence: &[&str],
) {
    // Create a mapping from each value to its position in the order sequence
    let order_map: HashMap<&str, usize> = order_sequence
        .iter()
        .enumerate()
        .map(|(index, &value)| (value, index))
        .collect();

    // Sort records based on the position of their sort_key value in the order_map
    records.sort_by_key(|record| {
        record
            .get(sort_key)
            .and_then(|value| order_map.get(value).copied())
            .unwrap_or(usize::MAX) // Items not in order_sequence go to the end
    });
}

fn main() {
    // Example usage
    let mut records = vec![
        {
            let mut m = HashMap::new();
            m.insert("color", "red");
            m.insert("name", "apple");
            m
        },
        {
            let mut m = HashMap::new();
            m.insert("color", "green");
            m.insert("name", "lime");
            m
        },
        {
            let mut m = HashMap::new();
            m.insert("color", "red");
            m.insert("name", "cherry");
            m
        },
        {
            let mut m = HashMap::new();
            m.insert("color", "blue");
            m.insert("name", "blueberry");
            m
        },
    ];

    println!("Before sorting:");
    for record in &records {
        println!("  {:?}", record);
    }

    let order = vec!["green", "red", "blue"];
    sort_by_keyed_order(&mut records, "color", &order);

    println!("\nAfter sorting by 'color' with order [green, red, blue]:");
    for record in &records {
        println!("  Color: {}, Name: {}", 
                 record.get("color").unwrap_or(&"?"),
                 record.get("name").unwrap_or(&"?"));
    }
}
```

