/// Combine a variable number of lists into a single list by following `sequence`.
///
/// - `lists` is a slice of input lists (each list is a Vec<T>).
/// - `sequence` is a slice of indices; each index says which input list to take the next element from.
/// - Returns a Vec<T> with elements taken in the order specified by `sequence`.
///
/// Panics if any index in `sequence` is out of bounds or if a chosen list runs out of elements.
pub fn interleave_by_sequence<T: Clone>(lists: &[Vec<T>], sequence: &[usize]) -> Vec<T> {
    // Track read positions for each input list.
    let mut positions = vec![0usize; lists.len()];
    let mut result = Vec::with_capacity(sequence.len());

    for &which in sequence {
        if which >= lists.len() {
            panic!(
                "sequence index {} out of bounds (must be < {})",
                which,
                lists.len()
            );
        }
        let pos = positions[which];
        if pos >= lists[which].len() {
            panic!(
                "list {} exhausted (requested element {} but length is {})",
                which,
                pos,
                lists[which].len()
            );
        }
        result.push(lists[which][pos].clone());
        positions[which] += 1;
    }

    result
}

