use interleave_n::Interleaver;

/// Combines multiple lists into a single list by following a provided sequence.
/// 
/// # Arguments
/// * `lists` - A vector of vectors containing the input lists to combine
/// * `sequence` - A vector of indices specifying which list to draw from at each step
/// 
/// # Returns
/// A single vector containing elements in the order specified by the sequence
