///     vec![1, 2, 3],
///     vec![10, 20, 30],
///     vec![100, 200, 300],
/// ];
/// let sequence = vec![0, 1, 2, 0, 1, 2, 0, 1, 2];
/// let result = combine_by_sequence(lists, sequence);
/// assert_eq!(result, vec![1, 10, 100, 2, 20, 200, 3, 30, 300]);
/// ```
pub fn combine_by_sequence<T: Clone>(
    lists: Vec<Vec<T>>,
    sequence: Vec<usize>,
) -> Vec<T> {
    // Create mutable index trackers for each list
    let mut indices: Vec<usize> = vec![0; lists.len()];
    let mut result = Vec::new();

    // Follow the sequence to pick elements
    for &list_idx in &sequence {
        if list_idx < lists.len() {
            let current_idx = indices[list_idx];
            if current_idx < lists[list_idx].len() {
                result.push(lists[list_idx][current_idx].clone());
                indices[list_idx] += 1;
            }
        }
    }

    result
}

