    lists: Vec<Vec<T>>,
    sequence: Vec<usize>,
) -> Vec<T> {
    let mut iterators: Vec<_> = lists.into_iter().map(|list| list.into_iter()).collect();
    let mut result = Vec::new();

    for &list_idx in &sequence {
        if list_idx < iterators.len() {
            if let Some(element) = iterators[list_idx].next() {
                result.push(element);
            }
        }
    }

    result
}

