            let f_p = f(xp);
            let f_m = f(xm);
            // derivative column i is (f_p - f_m) / (2h)
            j[0][i] = (f_p[0] - f_m[0]) / (2.0 * h);
            j[1][i] = (f_p[1] - f_m[1]) / (2.0 * h);
        }
        j
    }

    // Solve 2x2 linear system A * dx = b, return Option(dx)
    fn solve_2x2(a: [[f64; 2]; 2], b: [f64; 2]) -> Option<[f64; 2]> {
        let det = a[0][0] * a[1][1] - a[0][1] * a[1][0];
        if det.abs() < 1e-15 {
            return None;
        }
        let inv00 = a[1][1] / det;
        let inv01 = -a[0][1] / det;
        let inv10 = -a[1][0] / det;
        let inv11 = a[0][0] / det;
        Some([
            inv00 * b[0] + inv01 * b[1],
            inv10 * b[0] + inv11 * b[1],
        ])
    }

    let mut x = init;
    for iter in 0..max_iter {
        let fx = f(x);
        let res_norm = norm2(fx);
        if res_norm <= tol {
            return Ok(x);
        }

        let j = jacobian_fd(&f, x);

        // Solve J * dx = -f
        let rhs = [-fx[0], -fx[1]];
        let maybe_dx = solve_2x2(j, rhs);
        let dx = match maybe_dx {
            Some(d) => d,
            None => return Err(format!("Jacobian is singular (iteration {})", iter)),
        };

        let step_norm = norm2(dx);
        x[0] += dx[0];
        x[1] += dx[1];

        if step_norm <= tol {
            // final check residual
            let fx_new = f(x);
            if norm2(fx_new) <= tol {
                return Ok(x);
            } else {
                // small step but residual not small -- continue (or break)
                return Err(format!(
                    "Converged step small but residual not small: residual = {}",
                    norm2(fx_new)
                ));
            }
        }
    }

    Err(format!(
        "Maximum iterations ({}) exceeded without convergence",
        max_iter
    ))
}

fn main() {
    // Example system:
    //   f1(x,y) = x^2 + y^2 - 4
    //   f2(x,y) = x*y - 1
    // Solutions include (2, 0.5) and (-2, -0.5) roughly.
    let system = |v: [f64; 2]| -> [f64; 2] {
