# Rust Function for Computing Roots of Coupled Nonlinear Equations

```rust
use coupled_roots::prelude::*;

/// Computes the roots of two coupled nonlinear equations.
///
/// # Arguments
///
/// * `f` - A function that takes a tuple `(x, y)` and returns `(f1, f2)` where:
///   - `f1` is the value of the first equation at `(x, y)`
///   - `f2` is the value of the second equation at `(x, y)`
/// * `initial_x` - Initial estimate for the first variable
/// * `initial_y` - Initial estimate for the second variable
/// * `tolerance` - Convergence tolerance for the solver
/// * `max_iterations` - Maximum number of iterations allowed
///
/// # Returns
///
/// A `Result` containing either:
/// - `Ok((root_x, root_y))` - The computed roots when converged
/// - `Err(String)` - An error message if the solver failed to converge
///
/// # Example
///
/// ```ignore
/// fn equations(vars: (f64, f64)) -> (f64, f64) {
///     let (x, y) = vars;
///     let f1 = x * x + y * y - 1.0;  // Circle: x² + y² = 1
///     let f2 = x - y;                 // Line: x = y
///     (f1, f2)
/// }
///
/// match find_coupled_roots(
///     &equations,
///     0.5,
///     0.5,
///     1e-6,
///     100
/// ) {
///     Ok((x, y)) => println!("Roots found: x = {}, y = {}", x, y),
///     Err(e) => println!("Error: {}", e),
/// }
/// ```
pub fn find_coupled_roots<F>(
    f: &F,
    initial_x: f64,
    initial_y: f64,
    tolerance: f64,
    max_iterations: usize,
) -> Result<(f64, f64), String>
where
    F: Fn((f64, f64)) -> (f64, f64),
{
    let mut x = initial_x;
    let mut y = initial_y;
    let h = 1e-8; // Step size for numerical differentiation

    for iteration in 0..max_iterations {
        // Evaluate function at current point
        let (f1, f2) = f((x, y));

        // Check convergence
        let residual = (f1.abs() + f2.abs()) / 2.0;
        if residual < tolerance {
            return Ok((x, y));
        }

        // Compute Jacobian matrix numerically
        let (f1_xh, f2_xh) = f((x + h, y));
        let (f1_yh, f2_yh) = f((x, y + h));

        let df1_dx = (f1_xh - f1) / h;
        let df1_dy = (f1_yh - f1) / h;
        let df2_dx = (f2_xh - f2) / h;
        let df2_dy = (f2_yh - f2) / h;

        // Compute determinant
        let det = df1_dx * df2_dy - df1_dy * df2_dx;

        if det.abs() < 1e-14 {
            return Err(format!(
                "Singular Jacobian at iteration {} (det = {})",
                iteration, det
            ));
        }

        // Newton's method update: solve J * delta = -F
        let delta_x = (-(f1 * df2_dy - f2 * df1_dy)) / det;
        let delta_y = (-(df1_dx * f2 - df2_dx * f1)) / det;

        x += delta_x;
        y += delta_y;

        // Check if step size is sufficiently small
        if delta_x.abs() < tolerance && delta_y.abs() < tolerance {
            return Ok((x, y));
        }
    }

    Err(format!(
        "Failed to converge after {} iterations",
        max_iterations
    ))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_simple_coupled_equations() {
        // Test: x² + y² = 1 and x - y = 0
        // Expected roots: (√2/2, √2/2) and (-√2/2, -√2/2)
        fn equations(vars: (f64, f64)) -> (f64, f64) {
            let (x, y) = vars;
