    let mut width1 = header1.len();

    for v in &col0 {
        width0 = max(width0, v.len());
    }
    for v in &col1 {
        width1 = max(width1, v.len());
    }

    // Helper to pad cell to width
    let pad = |s: &str, w: usize| {
        let mut out = String::with_capacity(w);
        out.push_str(s);
        for _ in 0..(w - s.len()) {
            out.push(' ');
        }
        out
    };

    let mut out = String::new();

    // Header
    out.push_str(&format!("| {} | {} |\n", pad(header0, width0), pad(header1, width1)));

    // Separator line
    out.push_str(&format!("|-{}-| -{}-|\n",
        "-".repeat(width0),
        "-".repeat(width1)));

    // Rows
    for i in 0..rows {
        let a = if i < col0.len() { col0[i] } else { "" };
        let b = if i < col1.len() { col1[i] } else { "" };
        out.push_str(&format!("| {} | {} |\n", pad(a, width0), pad(b, width1)));
    }

    out
}

