// Reorder elements of `lst0` according to the ordering of corresponding values in `lst1`.
// After this call, `lst0` is rearranged so that its elements are in the order that would
// be obtained by sorting `lst1` (ascending). Equal keys keep their original relative order.
//
// Requirements:
// - lst0.len() == lst1.len()
// - K: Ord + Clone
// - T: Clone
pub fn reorder_by_keys<T: Clone, K: Ord + Clone>(lst0: &mut [T], lst1: &[K]) {
    assert_eq!(
        lst0.len(),
        lst1.len(),
        "lst0 and lst1 must have the same length"
    );

    // Pair keys with values and original index to preserve stability explicitly.
    let mut pairs: Vec<(K, usize, T)> = lst1
        .iter()
        .cloned()
        .zip(0usize..)
        .zip(lst0.iter().cloned())
        .map(|((k, i), v)| (k, i, v))
        .collect();

    // Sort by key, preserving original index order when keys are equal (stable sort).
    pairs.sort_by(|a, b| a.0.cmp(&b.0).then(a.1.cmp(&b.1)));

    // Write back the values into lst0 in the new order.
    for (i, (_k, _orig_idx, val)) in pairs.into_iter().enumerate() {
        lst0[i] = val;
    }
}

fn main() {
    let mut vals = vec!["a", "b", "c", "d"];
    let keys = vec![2, 0, 2, 1];

    reorder_by_keys(&mut vals, &keys);

    // keys sorted order: 0 -> index 1 ("b"), 1 -> index 3 ("d"), 2 -> indices 0 ("a"), 2 -> index 2 ("c")
    // resulting vals: ["b", "d", "a", "c"]
    println!("{:?}", vals);
}
