pub fn remove_duplicate_rows(
    input_table: &mut Table,
    columns: &[usize],
) -> Result<(), String> {
    // Validate column indices
    for &col_idx in columns {
        if col_idx >= input_table.num_columns() {
            return Err(format!(
                "Column index {} is out of bounds. Table has {} columns.",
                col_idx,
                input_table.num_columns()
            ));
        }
    }

    // Validate that columns exist and have data
    if columns.is_empty() {
        return Err("No columns specified for deduplication.".to_string());
    }

    // Perform deduplication based on specified columns
    match dedup_by_columns(input_table, columns) {
        Ok(()) => Ok(()),
        Err(e) => Err(format!("Deduplication failed: {}", e)),
    }
}

