/// Removes rows from a table that contain duplicate values across specified columns.
///
/// # Arguments
/// * `table` - A vector of maps representing rows, where each map contains column names as keys and cell values as strings
/// * `dedup_columns` - A vector of column names to check for duplicates
///
/// # Returns
/// A vector of maps with duplicate rows removed (keeps the first occurrence)
///
/// # Example
/// ```
/// let mut table = vec![
///     [("name", "Alice"), ("age", "30"), ("city", "NYC")].iter().cloned().collect::<HashMap<&str, &str>>(),
///     [("name", "Bob"), ("age", "25"), ("city", "LA")].iter().cloned().collect::<HashMap<&str, &str>>(),
///     [("name", "Alice"), ("age", "30"), ("city", "NYC")].iter().cloned().collect::<HashMap<&str, &str>>(),
/// ];
/// let dedup_columns = vec!["name", "age"];
/// let result = remove_duplicate_rows(table, dedup_columns);
/// ```
fn remove_duplicate_rows(
    table: Vec<HashMap<String, String>>,
    dedup_columns: Vec<&str>,
) -> Vec<HashMap<String, String>> {
    let mut seen = std::collections::HashSet::new();
    let mut result = Vec::new();

    for row in table {
        // Create a key from the specified columns
        let mut key = Vec::new();
        for col in &dedup_columns {
            if let Some(value) = row.get(*col) {
                key.push(value.clone());
            }
        }

        let key_tuple = key.join("|"); // Join values with delimiter

        // Only add row if we haven't seen this combination before
        if seen.insert(key_tuple) {
            result.push(row);
        }
    }

    result
}

