    let mut mapping1 = HashMap::new();
    mapping1.insert("link".to_string(), "https://bad.com".to_string());
    mapping1.insert("title".to_string(), "Bad Link".to_string());

    let mut mapping2 = HashMap::new();
    mapping2.insert("link".to_string(), "https://good.com".to_string());
    mapping2.insert("title".to_string(), "Good Link".to_string());

    let mappings = vec![mapping1, mapping2];
    let excluded_links = vec!["https://bad.com".to_string()];

    let filtered = filter_mappings_by_links(mappings, excluded_links);

    println!("Remaining mappings: {}", filtered.len()); // Output: 1
}
```

## Key Features

- **Self-contained**: Function works independently with the `link-pruner` library
- **Type-safe**: Uses `HashMap<String, String>` for flexibility
- **Handles missing links**: Keeps mappings without a "link" entry
- **Efficient**: Uses the `LinkPruner` for optimal link lookup performance
- **Tested**: Includes unit tests demonstrating the filtering behavior

