/// let vec2 = vec!['a', 'b', 'c'];
/// let paired = zip_sequences(vec1, vec2);
/// // Result: [(1, 'a'), (2, 'b'), (3, 'c')]
/// ```
fn zip_sequences<T1, T2, I1, I2>(seq1: I1, seq2: I2) -> Vec<(T1, T2)>
where
    I1: IntoIterator<Item = T1>,
    I2: IntoIterator<Item = T2>,
{
    seq1.into_iter()
        .zip(seq2.into_iter())
        .collect()
}

