```rust
/// Generate the Cartesian product of two integer ranges specified by
/// (start, stop_exclusive, step) each. Returns a Vec of (var0, var1) pairs.
///
/// - start: included
/// - stop_exclusive: excluded
/// - step: may be positive or negative, but not zero
///
/// Example:
/// let pairs = cartesian_product(0, 5, 2, 10, 7, -1);
/// // pairs = [(0,10),(0,9),(0,8),(1)?? wait — see below example usage]
pub fn cartesian_product(
    var0_start: i64,
    var0_stop_exclusive: i64,
    var0_step: i64,
    var1_start: i64,
    var1_stop_exclusive: i64,
    var1_step: i64,
) -> Result<Vec<(i64, i64)>, String> {
    // Validate steps
    if var0_step == 0 {
        return Err("var0_step must not be zero".to_string());
    }
    if var1_step == 0 {
        return Err("var1_step must not be zero".to_string());
    }

    // Helper to iterate a ranged sequence with a step and produce a Vec<i64>
    fn expand_range(start: i64, stop_exclusive: i64, step: i64) -> Vec<i64> {
        let mut v = Vec::new();
        if step > 0 {
            let mut cur = start;
            while cur < stop_exclusive {
                v.push(cur);
                cur = cur.saturating_add(step);
            }
        } else {
            // step < 0
            let mut cur = start;
            while cur > stop_exclusive {
                v.push(cur);
                cur = cur.saturating_add(step); // step is negative
            }
        }
        v
    }

    let seq0 = expand_range(var0_start, var0_stop_exclusive, var0_step);
    let seq1 = expand_range(var1_start, var1_stop_exclusive, var1_step);

    let mut out = Vec::with_capacity(seq0.len().saturating_mul(seq1.len()));
    for &a in &seq0 {
        for &b in &seq1 {
            out.push((a, b));
        }
    }

    Ok(out)
}

