```rust
use std::collections::HashMap;

/// Filters a key-value container to include only the pairs whose keys appear in the sequence.
///
/// # Arguments
///
/// * `container` - A reference to the existing key-value container.
/// * `keys` - A slice of keys to include in the new container.
///
/// # Returns
///
/// A new `HashMap` containing only the key-value pairs where the key is in the `keys` slice.
fn filter_key_value_container<K, V>(container: &HashMap<K, V>, keys: &[K]) -> HashMap<K, V>
where
    K: Eq + std::hash::Hash + Clone,
    V: Clone,
{
    let mut filtered_map = HashMap::new();
    for key in keys {
        if let Some(value) = container.get(key) {
            filtered_map.insert(key.clone(), value.clone());
        }
    }
    filtered_map
}

fn main() {
    // Example usage
    let mut container = HashMap::new();
    container.insert("apple", 1);
    container.insert("banana", 2);
    container.insert("cherry", 3);
    container.insert("date", 4);

    let keys_to_filter = ["apple", "cherry"];

    let filtered_container = filter_key_value_container(&container, &keys_to_filter);

    println!("{:?}", filtered_container); // Output: {"apple": 1, "cherry": 3}
}
```

