/// assert!(!all_elements_less(&vec![1, 5, 3], &vec![4, 5, 6]));
/// assert!(!all_elements_less(&vec![1, 2], &vec![1, 2, 3]));
/// assert!(all_elements_less(&vec![], &vec![]));
/// ```
fn all_elements_less<T: PartialOrd>(a: &[T], b: &[T]) -> bool {
