    use super::*;

    #[test]
    fn test_partial_retain_in_place() {
        let mut vec = vec![1, 2, 3, 4, 5];
        let removed = vec.partial_retain_in_place(|x| *x == 3);
        assert_eq!(vec, vec![1, 2, 4, 5]);
        assert_eq!(removed, 1); // Only one element was removed
    }

    #[test]
    fn test_partial_retain_new() {
        let vec = vec![1, 2, 3, 4, 5];
        let new_vec = partial_retain_new(&vec, |x| *x == 3);
        assert_eq!(new_vec, vec![1, 2, 4, 5]);
    }

