    rows: Vec<Vec<String>>,
}

impl SimpleDataFrame {
    fn new(columns: Vec<&str>, rows: Vec<Vec<&str>>) -> Self {
        let columns = columns.into_iter().map(|s| s.to_string()).collect();
        let rows = rows
            .into_iter()
            .map(|r| r.into_iter().map(|s| s.to_string()).collect())
            .collect();
        Self { columns, rows }
    }
}

/// A small module implementing the column-order logic (stands in for the
/// "dataframe-col-order" functionality).
mod dataframe_col_order {
    use std::collections::HashMap;

    /// Compute a new column index order given:
    /// - var0: current column names (in their present order)
    /// - var1: desired order (names; must be present in var0)
    ///
    /// The result is a Vec<usize> of indices into var0 representing the new order.
    /// Behavior:
    /// - All names in var1 must appear in var0, otherwise Err is returned.
    /// - Duplicates in var1 or var0 are considered an error.
    /// - Columns present in var0 but not in var1 are appended in their original order.
    pub fn compute_order(var0: &[&str], var1: &[&str]) -> Result<Vec<usize>, String> {
        let mut name_to_index: HashMap<&str, usize> = HashMap::new();
        for (i, &name) in var0.iter().enumerate() {
            if name_to_index.contains_key(name) {
                return Err(format!("duplicate column name '{}' in var0", name));
            }
            name_to_index.insert(name, i);
        }

        let mut used = vec![false; var0.len()];
        let mut new_order: Vec<usize> = Vec::with_capacity(var0.len());

        for &name in var1 {
            match name_to_index.get(name) {
                Some(&idx) => {
                    if used[idx] {
                        return Err(format!("duplicate column name '{}' in var1", name));
                    }
                    new_order.push(idx);
                    used[idx] = true;
                }
                None => {
                    return Err(format!("column '{}' listed in var1 not found in var0", name));
                }
            }
        }

        // Append remaining columns in original var0 order
        for i in 0..var0.len() {
            if !used[i] {
                new_order.push(i);
            }
        }

        Ok(new_order)
