// HashMap<String, usize> mapping each string to its length.

use std::collections::HashMap;
use std::hash::Hash;

/// A tiny "list2map" helper module implementing a comprehension-based conversion.
mod list2map {
    use std::collections::HashMap;
    use std::hash::Hash;

    /// Convert any iterable `iter` into a HashMap using comprehension-style selector functions.
    ///
    /// - `iter` : any IntoIterator of items T (e.g., Vec<T>, slice, etc.)
    /// - `key_fn`: takes &T and returns a key K (must implement Eq + Hash)
    /// - `val_fn`: takes &T and returns a value V
    ///
    /// The function pre-allocates the HashMap capacity from the iterator's
    /// size_hint lower bound to reduce reallocations.
    pub fn from_comprehension<I, T, K, V, FK, FV>(iterable: I, key_fn: FK, val_fn: FV) -> HashMap<K, V>
    where
        I: IntoIterator<Item = T>,
        FK: Fn(&T) -> K,
        FV: Fn(&T) -> V,
        K: Eq + Hash,
    {
        let mut iter = iterable.into_iter();
        let (lower, _) = iter.size_hint();
        let mut map: HashMap<K, V> = HashMap::with_capacity(lower);

        for item in iter {
            map.insert(key_fn(&item), val_fn(&item));
        }

        map
    }
}

