use chrono::{NaiveTime, Duration};
use polars::prelude::*;

fn calculate_time_difference(df0: &DataFrame) -> Result<DataFrame> {
    // Ensure the columns exist and are of type Time
    let col0 = df0.column("col0")?.time()?;
    let col1 = df0.column("col1")?.time()?;

    // Calculate the duration between each pair of times
    let durations = col0
        .into_iter()
        .zip(col1.into_iter())
        .map(|(t0, t1)| {
            if let (Some(t0), Some(t1)) = (t0, t1) {
                let naive_t0 = NaiveTime::from_hms(t0.hour() as u32, t0.minute() as u32, t0.second() as u32);
                let naive_t1 = NaiveTime::from_hms(t1.hour() as u32, t1.minute() as u32, t1.second() as u32);
                let duration = if naive_t0 > naive_t1 {
                    Duration::seconds((naive_t0 - naive_t1).num_seconds())
                } else {
                    Duration::seconds((naive_t1 - naive_t0).num_seconds())
                };
                Ok(Some((duration.num_hours(), duration.num_minutes() % 60)))
            } else {
                Ok(None)
            }
        })
        .collect::<Result<Vec<Option<(i64, i64)>>>>()?;

    // Create Series for hours and minutes
    let hours_series = Series::new("hours", durations.iter().map(|d| d.as_ref().map(|&(h, _)| h)));
    let minutes_series = Series::new("minutes", durations.iter().map(|d| d.as_ref().map(|&(_, m)| m)));

    // Create a new DataFrame with the calculated hours and minutes
    let result_df = DataFrame::new(vec![hours_series, minutes_series])?;

    Ok(result_df)
}

