///
/// # Arguments
/// * `df0` - A 2D vector representing the tabular dataset where each row is a `Vec<String>`.
/// * `col0` - Index of the first time column.
/// * `col1` - Index of the second time column.
/// * `time_format` - Format description for parsing the time strings (e.g., `FormatDescription::new("yyyy-MM-dd HH:mm:ss")`).
///
/// # Returns
/// A `Result<Vec<Vec<String>>, Box<dyn Error>>` where each row contains the original row with an additional
/// column showing the time difference in "HH:MM" format.
pub fn calculate_time_difference(
    df0: Vec<Vec<String>>,
    col0: usize,
    col1: usize,
    time_format: FormatDescription<'static>,
) -> Result<Vec<Vec<String>>, Box<dyn Error>> {
