# Rust Function for Time Difference Calculation

```rust
use time::Duration;

/// Calculates the difference between two time values in each row and returns hours and minutes.
/// 
/// # Arguments
/// * `col0` - Vector of time values (start times)
/// * `col1` - Vector of time values (end times)
/// 
/// # Returns
/// A vector of tuples containing (hours, minutes) for each row
fn calculate_time_difference(
    col0: Vec<time::Time>,
    col1: Vec<time::Time>,
) -> Vec<(i32, i32)> {
    col0.iter()
        .zip(col1.iter())
        .map(|(start, end)| {
            // Calculate the duration between two times
            let duration = if end >= start {
                *end - *start
            } else {
                // Handle case where end time is on the next day
                Duration::hours(24) - (*start - *end)
            };

            // Convert duration to hours and minutes
            let total_seconds = duration.whole_seconds();
            let hours = (total_seconds / 3600) as i32;
            let minutes = ((total_seconds % 3600) / 60) as i32;

            (hours, minutes)
        })
        .collect()
}

#[cfg(test)]
mod tests {
