        let col1 = vec![
            Time::from_hms(11, 45, 0).unwrap(),
            Time::from_hms(16, 45, 0).unwrap(),
        ];

        let result = calculate_time_difference(col0, col1);

        assert_eq!(result[0], (2, 15)); // 9:30 to 11:45 = 2 hours 15 minutes
        assert_eq!(result[1], (2, 30)); // 14:15 to 16:45 = 2 hours 30 minutes
    }
}
