use std::collections::HashMap;

/// Groups a tabular dataset by a specified column and returns the row 
/// with the maximum value in another specified column for each group.
///
/// # Arguments
/// * `data` - A vector of records, where each record is a HashMap<String, String>
/// * `group_by_column` - The name of the column to group by
/// * `max_column` - The name of the column to find the maximum value in
///
/// # Returns
/// A HashMap where keys are group values and values are the complete records
/// with the maximum value in the specified column
///
/// # Example
/// ```
/// use std::collections::HashMap;
///
/// let mut record1 = HashMap::new();
/// record1.insert("name".to_string(), "Alice".to_string());
/// record1.insert("department".to_string(), "Engineering".to_string());
/// record1.insert("salary".to_string(), "75000".to_string());
///
/// let mut record2 = HashMap::new();
/// record2.insert("name".to_string(), "Bob".to_string());
/// record2.insert("department".to_string(), "Engineering".to_string());
/// record2.insert("salary".to_string(), "85000".to_string());
///
/// let mut record3 = HashMap::new();
/// record3.insert("name".to_string(), "Charlie".to_string());
/// record3.insert("department".to_string(), "Sales".to_string());
/// record3.insert("salary".to_string(), "70000".to_string());
///
/// let data = vec![record1, record2, record3];
/// let result = group_by_max(data, "department", "salary");
///
/// assert_eq!(result.get("Engineering").unwrap().get("name").unwrap(), "Bob");
/// assert_eq!(result.get("Sales").unwrap().get("name").unwrap(), "Charlie");
/// ```
pub fn group_by_max(
    data: Vec<HashMap<String, String>>,
    group_by_column: &str,
    max_column: &str,
) -> HashMap<String, HashMap<String, String>> {
    let mut groups: HashMap<String, (f64, HashMap<String, String>)> = HashMap::new();

    for record in data {
        // Get the grouping key
        let group_key = match record.get(group_by_column) {
            Some(key) => key.clone(),
            None => continue, // Skip records without the grouping column
        };

        // Get the value to compare
        let max_value = match record.get(max_column) {
            Some(val) => match val.parse::<f64>() {
                Ok(num) => num,
                Err(_) => continue, // Skip records where max_column is not numeric
            },
            None => continue, // Skip records without the max column
        };

        // Update the group if this record has a higher value
        groups
            .entry(group_key)
            .and_modify(|(current_max, current_record)| {
                if max_value > *current_max {
                    *current_max = max_value;
                    *current_record = record.clone();
                }
            })
            .or_insert((max_value, record.clone()));
    }

    // Convert to the final result format (removing the numeric value)
    groups
        .into_iter()
        .map(|(key, (_, record))| (key, record))
        .collect()
}

