use reorder_by_ref::{reorder_by_ref, ReorderByRef};
use std::collections::HashMap;

/// Reorders elements of `lst0` according to the order defined by `lst1`.
///
/// This implementation is optimized for cases where `lst1` is very large by:
/// 1. Using a hash map for O(1) lookups of positions in `lst1`
/// 2. Avoiding multiple passes through the data
///
/// # Arguments
/// * `lst0` - The list to be reordered
/// * `lst1` - The reference list that defines the desired order
///
/// # Returns
/// A new vector with elements from `lst0` reordered according to `lst1`
///
/// # Example
/// ```
/// let lst0 = vec![3, 1, 4, 1, 5, 9, 2, 6];
/// let lst1 = vec![1, 2, 3, 4, 5, 6, 9];
/// let reordered = reorder_by_reference(lst0, &lst1);
/// assert_eq!(reordered, vec![1, 2, 3, 4, 5, 6, 9, 1]);
/// ```
pub fn reorder_by_reference<T: PartialEq + Clone>(lst0: Vec<T>, lst1: &[T]) -> Vec<T> {
    // Create a mapping from value to its index in lst1
    let mut value_to_index = HashMap::new();
    for (index, &value) in lst1.iter().enumerate() {
        value_to_index.insert(value, index);
    }

    // Sort lst0 based on the indices from lst1
    let mut reordered: Vec<T> = lst0.into_iter()
        .map(|value| {
            // If the value exists in lst1, use its index; otherwise keep original order
            value_to_index.get(&value).copied().unwrap_or(usize::MAX)
        })
        .collect();

    // Stable sort by the indices we calculated
    reordered.sort_by_key(|&index| index);

    reordered
}

