use polars::prelude::*;
use std::collections::{HashMap, HashSet};
use std::error::Error;

/// Rename or reorder columns of df0.
///
/// - If `dict0` is `Some(map)`, renames columns according to the mapping (old_name -> new_name).
/// - Else if `lst0` is `Some(order)`, reorders columns to match `order` (must contain exactly the same column names).
/// - If both are None, returns the original DataFrame.
/// Returns a new DataFrame on success or an error message boxed as `Box<dyn Error>`.
pub fn rename_or_reorder_df(
    mut df0: DataFrame,
    dict0: Option<&HashMap<String, String>>,
    lst0: Option<&[String]>,
) -> Result<DataFrame, Box<dyn Error>> {
    // If mapping is provided, apply renames
    if let Some(map) = dict0 {
        for (old, new) in map.iter() {
            // check column exists
            if df0.column(old).is_err() {
                return Err(format!("column '{}' not found in DataFrame", old).into());
            }
            // polars DataFrame::rename returns Result<(), PolarsError>
            df0.rename(old, new)
                .map_err(|e| format!("failed to rename '{}' -> '{}': {}", old, new, e))?;
        }
        return Ok(df0);
    }

    // If an ordering list is provided, reorder columns
    if let Some(order) = lst0 {
        // Validate that `order` contains exactly the same columns as df0
        let existing: HashSet<String> = df0.get_column_names().iter().cloned().collect();
        let requested: HashSet<String> = order.iter().cloned().collect();

        if existing != requested {
            return Err(format!(
                "order list does not match existing columns.\nExisting: {:?}\nRequested: {:?}",
                existing, requested
            )
            .into());
        }

        // Build new series vector in requested order
        let mut series_vec: Vec<Series> = Vec::with_capacity(order.len());
        for name in order.iter() {
            let s = df0
                .column(name)
                .map_err(|e| format!("column '{}' not found while reordering: {}", name, e))?
                .clone();
            series_vec.push(s);
        }

        let new_df = DataFrame::new(series_vec)
            .map_err(|e| format!("failed to build reordered DataFrame: {}", e))?;
        return Ok(new_df);
    }

    // Neither dict0 nor lst0 provided: return original
    Ok(df0)
}

