use df_column_renamer::{ColumnRenamer, RenameMapping};
use polars::prelude::*;

/// Rename columns of a DataFrame according to a mapping dictionary or ordered sequence.
///
/// # Arguments
/// * `df0` - The input DataFrame to rename columns on
/// * `dict0` - Optional HashMap mapping old column names to new column names
/// * `lst0` - Optional ordered sequence of new column names (must match number of columns)
///
