/// Calculates the sum of values in a specified column for rows matching a condition.
///
/// # Arguments
/// * `data` - A slice of rows, where each row is a vector of f64 values
/// * `column_index` - The index of the column to sum
/// * `condition_column` - The index of the column to apply the filter condition on
/// * `condition_value` - The threshold value for the filter condition
/// * `filter_type` - The type of comparison (e.g., "greater", "less", "equal")
///
/// # Returns
/// * `Result<f64, String>` - The sum of matching values or an error message
///
/// # Example
/// ```
/// let data = vec![
///     vec![1.0, 10.0, 100.0],
///     vec![2.0, 20.0, 200.0],
///     vec![3.0, 30.0, 300.0],
/// ];
///
/// let sum = column_sum_with_filter(&data, 2, 0, 2.0, "greater").unwrap();
/// assert_eq!(sum, 500.0); // Rows where column 0 > 2.0: rows 1 and 2 (200.0 + 300.0)
/// ```
pub fn column_sum_with_filter(
    data: &[Vec<f64>],
    column_index: usize,
    condition_column: usize,
    condition_value: f64,
    filter_type: &str,
) -> Result<f64, String> {
    if data.is_empty() {
        return Ok(0.0);
    }

    // Validate indices
    if let Some(first_row) = data.first() {
        if column_index >= first_row.len() {
            return Err(format!(
                "Column index {} out of bounds (max: {})",
                column_index,
                first_row.len() - 1
            ));
        }
        if condition_column >= first_row.len() {
            return Err(format!(
                "Condition column index {} out of bounds (max: {})",
                condition_column,
                first_row.len() - 1
            ));
        }
    }

    let sum = data
        .iter()
        .filter(|row| {
            if let Some(&cond_val) = row.get(condition_column) {
                match filter_type.to_lowercase().as_str() {
                    "greater" | "gt" | ">" => cond_val > condition_value,
                    "less" | "lt" | "<" => cond_val < condition_value,
                    "equal" | "eq" | "==" => (cond_val - condition_value).abs() < f64::EPSILON,
                    "greater_equal" | "gte" | ">=" => cond_val >= condition_value,
                    "less_equal" | "lte" | "<=" => cond_val <= condition_value,
                    "not_equal" | "ne" | "!=" => (cond_val - condition_value).abs() >= f64::EPSILON,
                    _ => false,
                }
            } else {
                false
            }
        })
        .filter_map(|row| row.get(column_index))
        .sum::<f64>();

    Ok(sum)
}

