/// Center `text` into a new String of exactly `total_len` characters,
/// padding with `pad_char` on both sides. If `text` is longer than
/// `total_len`, it will be truncated to `total_len` characters.
pub fn center_pad(text: &str, total_len: usize, pad_char: char) -> String {
    let text_len = text.chars().count();

    // If text is already too long, truncate to total_len chars.
    if total_len <= text_len {
        return text.chars().take(total_len).collect();
    }

    let padding = total_len - text_len;
    // Put the smaller half on the left, extra on the right when padding is odd.
    let left = padding / 2;
    let right = padding - left;

    let mut out = String::with_capacity(total_len);
    for _ in 0..left {
        out.push(pad_char);
    }
    out.push_str(text);
    for _ in 0..right {
        out.push(pad_char);
    }
    out
}

