use std::collections::HashMap;
use std::hash::Hash;

/// Small helper "order-by-sequence" implementation (acts like a tiny library).
/// It maps each value in the reference sequence to its index so lookups are O(1).
mod order_by_sequence {
    use std::collections::HashMap;
    use std::hash::Hash;

    #[derive(Debug)]
    pub struct OrderBySequence<T>
    where
        T: Eq + Hash,
    {
        index_map: HashMap<T, usize>,
    }

    impl<T> OrderBySequence<T>
    where
        T: Eq + Hash,
    {
        /// Construct from any iterable sequence; first occurrence determines the order index.
        pub fn new<I>(seq: I) -> Self
        where
            I: IntoIterator<Item = T>,
        {
            let mut index_map = HashMap::new();
            for (i, item) in seq.into_iter().enumerate() {
                index_map.entry(item).or_insert(i);
            }
            OrderBySequence { index_map }
        }

        /// Returns the index of a value in the reference sequence, if present.
        pub fn index_of(&self, value: &T) -> Option<usize>
        where
            T: Clone,
        {
            self.index_map.get(value).cloned()
        }
    }
}

/// Sort `dict0` in-place according to the order defined by `lst0`.
/// Each record is a HashMap<String, String>. The record's value at key `var0`
/// is looked up in `lst0` to determine its sort position. Records whose
/// `var0` value does not appear in `lst0` are put after those that do,
/// preserving relative order among equal keys (stable sort).
///
/// Parameters:
/// - dict0: mutable slice of records to sort (Vec<HashMap<String,String>> works)
/// - lst0: reference sequence defining the ordering (Vec<String> or slice)
/// - var0: the key in each record whose value determines ordering
pub fn sort_records_by_reference_sequence(
    dict0: &mut [HashMap<String, String>],
    lst0: &[String],
    var0: &str,
) {
    // Build an orderer from the reference sequence
    let orderer = order_by_sequence::OrderBySequence::new(lst0.iter().cloned());

    // Use stable sort by key index: values found in lst0 get their index,
    // values not found get usize::MAX so they sort to the end.
    dict0.sort_by_key(|rec| {
        rec.get(var0)
            .and_then(|v| orderer.index_of(v))
            .unwrap_or(usize::MAX)
    });
}

