///     "id" => &[1, 2, 3],
///     "name" => &["Alice", "Bob", "Charlie"],
///     "score" => &[85, 92, 78]
/// ];
/// let result = df_to_dict(&df, "id");
/// ```
pub fn df_to_dict(df0: &DataFrame, var0: &str) -> Result<Value, Box<dyn std::error::Error>> {
    // Check if the orientation variable exists
    if !df0.column(var0).is_ok() {
        return Err(format!("Column '{}' not found", var0).into());
    }

    // Get the orientation column
    let orient_col = df0.column(var0)?.utf8()?;

    // Create a HashMap to store our dictionary
    let mut result_dict = serde_json::Map::new();

    // Get all other columns
    let other_cols: Vec<String> = df0
        .get_column_names()
        .iter()
        .filter(|&col| col != var0)
        .cloned()
        .collect();

    // Group by the orientation variable
    for row in 0..df0.height() {
        let key = orient_col.get(row).unwrap_or("");
        let mut row_dict = serde_json::Map::new();

        // Add each value to the row dictionary
        for col in &other_cols {
