            let value = col_data.get(row).unwrap_or("");
            row_dict.insert(col.clone(), Value::String(value.to_string()));
        }

        // Add to the main dictionary
        result_dict.insert(key.to_string(), Value::Object(row_dict));
    }

    Ok(Value::Object(result_dict))
}

