/// Transform a two-dimensional dataset `df0` into a dictionary according to orientation `var0`.
///
/// - `df0` is expected to be a Vec of Vec of Strings where the first inner vector is the header
///   (column names) and each subsequent inner vector is a data row.
/// - `var0` (orientation) supports: "dict", "list", "series", "records", "split", "index".
///
/// Returns a serde_json::Value representing the dictionary-like structure, or an Err(String)
/// describing a problem (e.g., unsupported orientation).
///
/// Example:
/// let df = vec![
///     vec!["id".into(), "name".into(), "age".into()],
///     vec!["1".into(), "Alice".into(), "30".into()],
///     vec!["2".into(), "Bob".into(), "25".into()],
/// ];
/// let out = df_to_dict(&df, "records")?;
/// // out -> [{"id":"1","name":"Alice","age":"30"}, {"id":"2","name":"Bob","age":"25"}]
pub fn df_to_dict(df0: &[Vec<String>], var0: &str) -> Result<Value, String> {
    // Empty dataset -> return empty object
    if df0.is_empty() {
        return Ok(json!({}));
    }

    let headers = &df0[0];
    let rows = &df0[1..];

    // Helpers to get a cell (if missing, use empty string)
    let get_cell = |row: &Vec<String>, col_idx: usize| {
        row.get(col_idx).cloned().unwrap_or_else(|| "".to_string())
    };

    match var0 {
        // { column: { index: value, ... }, ... }
        "dict" | "series" => {
            let mut out = Map::new();
            for (ci, col) in headers.iter().enumerate() {
                let mut colmap = Map::new();
                for (ri, row) in rows.iter().enumerate() {
                    colmap.insert(ri.to_string(), Value::String(get_cell(row, ci)));
                }
                out.insert(col.clone(), Value::Object(colmap));
            }
            Ok(Value::Object(out))
        }

        // { column: [v1, v2, ...], ... }
        "list" => {
            let mut out = Map::new();
            for (ci, col) in headers.iter().enumerate() {
                let mut arr = Vec::with_capacity(rows.len());
                for row in rows.iter() {
                    arr.push(Value::String(get_cell(row, ci)));
                }
                out.insert(col.clone(), Value::Array(arr));
            }
            Ok(Value::Object(out))
        }

        // [ {col: val, ...}, {col: val, ...}, ... ]
        "records" => {
            let mut recs = Vec::with_capacity(rows.len());
            for row in rows.iter() {
                let mut obj = Map::new();
                for (ci, col) in headers.iter().enumerate() {
                    obj.insert(col.clone(), Value::String(get_cell(row, ci)));
                }
                recs.push(Value::Object(obj));
            }
            Ok(Value::Array(recs))
        }

        // { "index": [0,1,...], "columns": [...], "data": [[...],[...],...] }
        "split" => {
            let index: Vec<Value> = (0..rows.len()).map(|i| Value::Number(i.into())).collect();
            let columns: Vec<Value> = headers.iter().map(|h| Value::String(h.clone())).collect();
            let mut data = Vec::with_capacity(rows.len());
            for row in rows.iter() {
                let row_arr: Vec<Value> = (0..headers.len()).map(|ci| Value::String(get_cell(row, ci))).collect();
                data.push(Value::Array(row_arr));
            }
            Ok(json!({ "index": index, "columns": columns, "data": data }))
        }

        // { index: {col: val, ...}, ... }
        "index" => {
            let mut out = Map::new();
            for (ri, row) in rows.iter().enumerate() {
                let mut obj = Map::new();
                for (ci, col) in headers.iter().enumerate() {
                    obj.insert(col.clone(), Value::String(get_cell(row, ci)));
                }
                out.insert(ri.to_string(), Value::Object(obj));
            }
            Ok(Value::Object(out))
        }

        _ => Err(format!("unsupported orientation: {}", var0)),
    }
}

