/// ensures a sequential row number column. If the table already has a
/// column named "row", "index", or "id" it will overwrite that column with
/// sequential 1-based numbering; otherwise it will add a "row" column.
mod regex_row_filter {
    use regex::Regex;
    use std::collections::HashMap;

    pub fn remove_matching_rows(
        df: &mut Vec<HashMap<String, String>>,
        column: &str,
        pattern: &str,
    ) -> Result<(), regex::Error> {
        let re = Regex::new(pattern)?;

        // Keep only rows where the column either doesn't exist or does not match.
        df.retain(|row| match row.get(column) {
            Some(value) => !re.is_match(value),
            None => true,
