fn sort_dataframe(df0: &mut Vec<Row>, sort_columns: &[usize]) {
    df0.sort_by(|a, b| {
        for &col in sort_columns {
            let cmp = a.get_column(col).cmp(&b.get_column(col));
            if cmp != Ordering::Equal {
                return cmp;
            }
        }
