use ndarray::{Array2, Axis};
use ndarray_stats::errors::MinMaxError;
use ndarray_stats::errors::MinMaxErrorKind;
use std::error::Error;

/// Normalize each column of the input array using z-score normalization.
fn z_score_normalization(df: &Array2<f64>) -> Result<Array2<f64>, Box<dyn Error>> {
    let means = df.mean_axis(Axis(0)).ok_or(MinMaxError::new(MinMaxErrorKind::mean))?;
    let std_devs = df.std_axis(Axis(0, 0));

    // Create an output array of the same shape
    let mut normalized = df.clone();

    for (i, column) in normalized.columns_mut().enumerate() {
        let mean = means[i];
        let std_dev = std_devs[i];

        if std_dev == 0.0 {
            return Err("Standard deviation is zero, cannot normalize".into());
        }

        column.map_inplace(|value| (value - mean) / std_dev);
    }

    Ok(normalized)
}

fn main() -> Result<(), Box<dyn Error>> {
