    let data = Array2::from_shape_vec((3, 2), vec![1.0, 2.0, 2.0, 3.0, 3.0, 4.0])?;

    // Normalize the data
    let normalized_data = z_score_normalization(&data)?;

    println!("Normalized data:\n{}", normalized_data);
    Ok(())
}
