        // If zscore produced NaNs (e.g., zero variance), replace with 0.0 for stability.
        for (dst, src) in col.iter_mut().zip(normalized.into_iter()) {
            if src.is_nan() {
                *dst = 0.0;
            } else {
                *dst = src;
            }
        }
    }

    // rebuild rows from normalized columns
    let mut out: Vec<Vec<f64>> = vec![vec![0.0; n_cols]; n_rows];
    for j in 0..n_cols {
        for i in 0..n_rows {
            out[i][j] = cols[j][i];
        }
    }

