/// # Returns
/// * `Result<DataFrame>` - DataFrame with z-score normalized columns
///
/// # Panics
/// * If any column contains non-numeric data
/// * If any column has zero variance (all values identical)
pub fn zscore_normalize_columns(df: &DataFrame) -> Result<DataFrame, PolarsError> {
    // Get all numeric columns
    let numeric_columns: Vec<&str> = df
        .get_column_names()
        .iter()
        .filter(|&&name| {
            df.column(name)
                .map(|col| col.dtype().is_numeric())
                .unwrap_or(false)
        })
        .map(|&name| name)
        .collect();

    // Create a vector to hold the normalized columns
    let mut normalized_columns: Vec<Series> = Vec::new();

    // Process each numeric column
    for col_name in &numeric_columns {
        let column = df.column(col_name)?;

        // Convert to f64 for z-score calculation
        let float_series = column.cast(&DataType::Float64)?;
        let values: Vec<f64> = float_series.f64()?.into_iter()
            .map(|v| v.unwrap_or(f64::NAN))
            .collect();

        // Calculate z-scores
        let zscores = ZScore::new(&values);
        let normalized_values = zscores.z_scores();

        // Create new series with normalized values
        let normalized_series = Series::new(col_name, &normalized_values);
        normalized_columns.push(normalized_series);
    }

    // Add non-numeric columns back unchanged
    let non_numeric_columns: Vec<&str> = df
        .get_column_names()
        .iter()
        .filter(|&&name| {
