///     Series::new("var0", vec![NaiveDate::from_ymd_opt(2023, 1, 1).unwrap(), NaiveDate::from_ymd_opt(2023, 2, 1).unwrap(), NaiveDate::from_ymd_opt(2023, 3, 1).unwrap()]),
