/// ```
pub fn filter_date_range<D: DateTime<Utc> + PartialOrd>(
    df0: DataFrame,
    var0: &str,
    date0: D,
    date1: D,
) -> Result<DataFrame, Box<dyn Error>> {
    // Ensure date0 <= date1
    if date0 > date1 {
        return Err("date0 must be less than or equal to date1".into());
    }

    // Get the column to filter
    let var_series = df0.column(var0)
        .ok_or_else(|| format!("Column '{}' not found", var0))?;

    // Convert to NaiveDateTime if needed (handles both DateTime and NaiveDate)
    let var_series = match var_series {
        Series::Datetime(datetime_series) => {
            // Convert to NaiveDateTime if it's a DateTime
            let naive_series: Series<NaiveDateTime> = datetime_series
                .iter()
                .map(|dt| dt.and_utc().naive_local())
                .collect();
            Series::new(var0, naive_series)
        }
        _ => var_series.clone(),
    };

    // Filter the DataFrame
    let filtered_df = df0.filter(|row| {
        let value = var_series.get(row.index).unwrap();
        match value {
            Value::Datetime(dt) => date0 <= *dt && *dt <= date1,
            Value::Date(date) => date0.with_time(NaiveTime::default()) <= *date && *date <= date1.with_time(NaiveTime::default()),
            _ => false, // Not a date/datetime value
        }
    })?;

    Ok(filtered_df)
}
