mod dataframe_filter {
    use super::*;

    #[derive(Clone, Debug)]
    pub enum Value {
        Int(i64),
        Float(f64),
        Str(String),
        Bool(bool),
    }

    impl Value {
        // Try to get numeric representation for Int/Float
        fn as_f64(&self) -> Option<f64> {
            match self {
                Value::Int(i) => Some(*i as f64),
                Value::Float(f) => Some(*f),
                _ => None,
            }
        }

        fn as_str(&self) -> Option<&str> {
            match self {
                Value::Str(s) => Some(s),
                _ => None,
            }
        }

        fn as_bool(&self) -> Option<bool> {
            match self {
                Value::Bool(b) => Some(*b),
                _ => None,
            }
        }

        // Equality handling across numeric types and exact matches for others
        fn eq_value(&self, other: &Value) -> bool {
            match (self, other) {
                (Value::Int(_), Value::Float(_)) |
                (Value::Float(_), Value::Int(_)) |
                (Value::Int(_), Value::Int(_)) |
                (Value::Float(_), Value::Float(_)) => {
                    match (self.as_f64(), other.as_f64()) {
                        (Some(a), Some(b)) => (a - b).abs() < std::f64::EPSILON,
                        _ => false,
                    }
                }
                (Value::Str(a), Value::Str(b)) => a == b,
                (Value::Bool(a), Value::Bool(b)) => a == b,
                _ => false,
            }
        }

        // Compare, only for numeric values
        fn partial_cmp_numeric(&self, other: &Value) -> Option<Ordering> {
            match (self.as_f64(), other.as_f64()) {
                (Some(a), Some(b)) => a.partial_cmp(&b),
                _ => None,
            }
        }
    }

    // Operator for a condition. Contains any literal values it needs.
    #[derive(Clone, Debug)]
    pub enum Operator {
        Eq(Value),
        Neq(Value),
        Lt(Value),
        Lte(Value),
        Gt(Value),
        Gte(Value),
        Contains(String),         // substring for string columns
        In(Vec<Value>),           // membership in given set
        Between(Value, Value),    // inclusive between
    }

    #[derive(Clone, Debug)]
    pub struct Condition {
        pub column: String,
        pub op: Operator,
    }

    pub type Row = HashMap<String, Value>;

    #[derive(Clone, Debug)]
    pub struct DataFrame {
        pub rows: Vec<Row>,
    }

