///
/// # Arguments
/// * `data` - A 2D array representing the tabular dataset
/// * `rows` - A slice of row indices to include in the average calculation
/// * `cols` - A slice of column indices to include in the average calculation
///
/// # Returns
/// * `Option<f64>` - The average value, or None if the selected region is empty
///
/// # Panics
/// * Panics if any row or column index is out of bounds
pub fn compute_average_for_subset(
    data: &Array2<f64>,
    rows: &[usize],
    cols: &[usize],
) -> Option<f64> {
    // Validate indices
    for &row in rows {
        assert!(
            row < data.nrows(),
            "Row index {} is out of bounds (max: {})",
            row,
            data.nrows() - 1
        );
    }
    for &col in cols {
        assert!(
            col < data.ncols(),
            "Column index {} is out of bounds (max: {})",
            col,
            data.ncols() - 1
        );
    }

    // If no rows or columns specified, return None
    if rows.is_empty() || cols.is_empty() {
        return None;
    }

    // Create a TabularMean instance and add the selected values
    let mut mean = TabularMean::new();

    for &row in rows {
        for &col in cols {
            mean.add(data[[row, col]]);
        }
    }

    // Return the average if we have at least one value
    if mean.count() > 0 {
        Some(mean.mean())
    } else {
        None
    }
}

