///     [1.0, 2.0, 3.0],
///     [f64::NAN, 5.0, 6.0],
///     [7.0, f64::NAN, 9.0],
/// ];
///
/// let filled = fill_missing_values(&data, 0, 1);
/// ```
pub fn fill_missing_values(data: &Array2<f64>, col0: usize, col1: usize) -> Array2<f64> {
    // Create a copy of the data to avoid modifying the original
    let mut filled_data = data.clone();

    // Create a view of the columns we're working with
    let col0_view = filled_data.column(col0);
    let col1_view = filled_data.column(col1);

    // Create a strategy that fills NA values in col0 with corresponding values from col1
