/// ).unwrap();
/// 
/// fill_from_column(&mut df, "A", "B").unwrap();
/// // Result: A column becomes [1, 20, 3]
/// ```
pub fn fill_from_column(
    df: &mut DataFrame,
    target_column: &str,
    source_column: &str,
) -> Result<(), PolarsError> {
    // Get the series for both columns
    let target_series = df.column(target_column)?.clone();
    let source_series = df.column(source_column)?.clone();

    // Create a mask for missing values in the target column
    let missing_mask = target_series.is_null();

    // Use fill_missing to replace null values with values from source column
    let filled_series = target_series
        .fill_missing_with_strategy(fill_missing::FillMissingStrategy::Forward)?;

    // For each position where target is null, replace with source value
    let result: Series = missing_mask
        .into_series()
        .apply(|mask_value| {
            if mask_value {
                // Use source value where target is null
                source_series.get(mask_value.index() as usize)
            } else {
                // Keep original value where target is not null
                target_series.get(mask_value.index() as usize)
            }
        })
        .collect();

    // Replace the column in the DataFrame
    df.replace(target_column, result)?;

    Ok(())
}

