/// * `data` - A vector of maps where each map represents a row with column names as keys
/// * `name_order` - A vector of names specifying the desired order
///
/// # Returns
/// A vector of maps reordered according to the name_order sequence
///
/// # Example
/// ```
/// let data = vec![
///     [("name".to_string(), "Charlie"), ("age".to_string(), "30")].iter().cloned().collect::<HashMap<_, _>>(),
///     [("name".to_string(), "Alice"), ("age".to_string(), "25")].iter().cloned().collect::<HashMap<_, _>>(),
///     [("name".to_string(), "Bob"), ("age".to_string(), "28")].iter().cloned().collect::<HashMap<_, _>>(),
/// ];
/// let name_order = vec!["Alice", "Bob", "Charlie"];
/// let reordered = reorder_by_name(data, name_order);
/// ```
fn reorder_by_name(
    data: Vec<HashMap<String, String>>,
    name_order: Vec<&str>,
) -> Vec<HashMap<String, String>> {
    // Create a mapping of names to their desired positions
    let order_map: HashMap<&str, usize> = name_order
        .iter()
        .enumerate()
        .map(|(index, name)| (*name, index))
        .collect();

    // Create a RowReorder instance and set the ordering
    let mut reorderer = RowReorder::new();

    // Add rows with their priority based on the order_map
    for (index, row) in data.iter().enumerate() {
        if let Some(name) = row.get("name") {
            if let Some(&priority) = order_map.get(name.as_str()) {
                reorderer.add_row(index, priority);
            } else {
                // Rows not in the order list are appended at the end
                reorderer.add_row(index, name_order.len() + index);
            }
        }
    }

    // Get the reordered indices
    let reordered_indices = reorderer.reorder();

    // Apply the reordering to the original data
    reordered_indices
        .iter()
        .map(|&idx| data[idx].clone())
        .collect()
}

