```rust
use groupby_count::CountMap;
use std::collections::HashMap;

/// Counts records for each distinct combination of values in specified columns.
///
/// # Arguments
/// * `df` - A vector of HashMaps where each HashMap represents a row with column names as keys
/// * `key_columns` - A vector of column names to group by
///
/// # Returns
/// A HashMap where keys are tuples of values (as Strings) and values are their counts
///
/// # Example
/// ```
/// let mut row1 = HashMap::new();
/// row1.insert("name".to_string(), "Alice".to_string());
/// row1.insert("dept".to_string(), "Sales".to_string());
///
/// let mut row2 = HashMap::new();
/// row2.insert("name".to_string(), "Bob".to_string());
/// row2.insert("dept".to_string(), "Sales".to_string());
///
/// let mut row3 = HashMap::new();
/// row3.insert("name".to_string(), "Alice".to_string());
/// row3.insert("dept".to_string(), "Sales".to_string());
///
/// let df = vec![row1, row2, row3];
/// let key_columns = vec!["name", "dept"];
/// let counts = groupby_count(&df, &key_columns);
/// ```
fn groupby_count(
    df: &[HashMap<String, String>],
    key_columns: &[&str],
) -> HashMap<Vec<String>, usize> {
    let mut count_map: CountMap<Vec<String>> = CountMap::new();

    for row in df {
        // Extract values for the specified key columns
        let key: Vec<String> = key_columns
            .iter()
            .map(|col| row.get(*col).cloned().unwrap_or_default())
            .collect();

        // Increment the count for this key combination
        count_map.insert(key);
    }

    // Convert CountMap to HashMap
    count_map.into_iter().collect()
}

fn main() {
    // Example usage
    let mut row1 = HashMap::new();
    row1.insert("name".to_string(), "Alice".to_string());
    row1.insert("dept".to_string(), "Sales".to_string());

    let mut row2 = HashMap::new();
    row2.insert("name".to_string(), "Bob".to_string());
    row2.insert("dept".to_string(), "Sales".to_string());

    let mut row3 = HashMap::new();
    row3.insert("name".to_string(), "Alice".to_string());
    row3.insert("dept".to_string(), "Sales".to_string());

    let mut row4 = HashMap::new();
    row4.insert("name".to_string(), "Alice".to_string());
    row4.insert("dept".to_string(), "IT".to_string());

    let df = vec![row1, row2, row3, row4];
    let key_columns = vec!["name", "dept"];

    let counts = groupby_count(&df, &key_columns);

    println!("GroupBy Count Results:");
    for (key_combo, count) in counts.iter() {
