/// Generate ordered pairs containing 9 and its predecessor for every occurrence of 9.
///
/// # Arguments
///
/// * `sequence`: Input sequence to process.
///
/// # Returns
///
/// A vector of ordered pairs, where each pair contains 9 and its predecessor.
pub fn generate_pairs(sequence: Vec<i32>) -> Vec<(i32, i32)> {
    let mut pairs = Vec::new();
    let mut predecessors = NinePredecessors::new();

    for (index, element) in sequence.iter().enumerate() {
