4. **Alternative Implementation**: If you prefer not to use external crates, here's a pure Rust implementation:

```rust
pub fn normalize_rows_pure<T>(input_data: &[Vec<T>]) -> Vec<Vec<f64>>
where
    T: Into<f64>,
{
    input_data
        .iter()
        .map(|row| {
            let sum: f64 = row.iter().map(|x| x.into()).sum();
            if sum == 0.0 {
                vec![0.0; row.len()]
            } else {
                row.iter()
                    .map(|x| x.into() / sum)
                    .collect()
            }
        })
        .collect()
}
```

