use list_ranker::ListRanker;

/// Assigns ranks to elements in a list based on their order when sorted.
/// Returns a vector of ranks where each element's rank corresponds to its
/// position in the sorted order (1-based ranking).
///
/// # Arguments
/// * `lst0` - A slice of items that implement Ord and Clone
///
/// # Returns
/// A vector of usize values representing the rank of each element
///
/// # Example
/// ```
/// let items = vec![3, 1, 4, 1, 5, 9, 2, 6];
/// let ranks = assign_ranks(&items);
/// // ranks = [4, 1, 5, 2, 6, 8, 3, 7]
/// ```
pub fn assign_ranks<T: Ord + Clone>(lst0: &[T]) -> Vec<usize> {
    // Create a vector of (value, original_index) pairs
    let indexed: Vec<(T, usize)> = lst0.iter()
        .cloned()
        .enumerate()
        .map(|(i, v)| (v, i))
        .collect();

    // Use ListRanker to get ranks (this sorts internally)
    let ranker = ListRanker::new(&indexed);
    let ranks = ranker.ranks();

    // Create result vector initialized with zeros
    let mut result = vec![0usize; lst0.len()];

    // Place each rank at its original position
    for (rank, (_, original_index)) in ranks.iter().zip(indexed.iter()) {
        result[*original_index] = *rank + 1; // +1 for 1-based ranking
    }

    result
}

