fn one_hot_encode_categories(df: &HashMap<String, Vec<String>>) -> HashMap<String, Vec<u8>> {
    // Create a mutable hashmap to store the one-hot encoded output
    let mut one_hot_encoded: HashMap<String, Vec<u8>> = HashMap::new();

    // Create an encoder
    let mut encoder = OneHotEncoder::new();

    // Iterate over each column in the input DataFrame (HashMap)
    for (column_name, values) in df.iter() {
        // Encode unique categories
        let unique_labels: Vec<&String> = values.iter().collect();
        encoder.fit(&unique_labels);

        // Transform the values into one-hot encoded format
        let transformed: Array<u8, _> = encoder.transform(&values)
            .expect("Failed to transform the values.");

        // Convert the Array into Vec<u8> and add to the output HashMap
        let encoded_values: Vec<u8> = transformed.iter().copied().collect();
        one_hot_encoded.insert(column_name.clone(), encoded_values);
    }

    one_hot_encoded
}

fn main() {
