/// Compare two HashMap<K, V> for equality ignoring the insertion order of keys.
/// K and V must implement Eq + Hash + Clone because we clone the maps into the
/// MapEq wrapper (MapEq implements PartialEq for the wrapped map type).
pub fn maps_equal<K, V>(a: &HashMap<K, V>, b: &HashMap<K, V>) -> bool
