/// let df = DataFrame::new(vec![
///     ("col_name".to_string(), vec!["abc123!@#", "def456", "ghi789"]),
/// ]);
/// let cleaned = clean_column(&df, "col_name");
/// ```
pub fn clean_column(df0: &DataFrame, col_name: &str) -> DataFrame {
    // Create a regex pattern that matches any non-alphanumeric character
    let re = Regex::new(r"[^a-zA-Z0-9]").unwrap();

    // Get the column to cleanse
    let col = df0.column(col_name)
        .expect(&format!("Column '{}' not found", col_name));

    // Clean each value in the column
    let cleaned_values: Vec<String> = col.values()
        .iter()
        .map(|s| re.replace_all(s, "").to_string())
        .collect();

    // Create a new DataFrame with the cleaned column
    let mut new_df = df0.clone();
    new_df.set_column(col_name, cleaned_values);

    new_df
}
