/// Count occurrences of each unique value in the first column of a tabular dataset.
///
/// # Arguments
/// * `data` - A vector of vectors where each inner vector represents a row,
///           and the first element of each row is the value to count
///
/// # Returns
/// A HashMap where keys are the unique values (as Strings) and values are their occurrence counts
///
/// # Example
/// ```
/// let data = vec![
///     vec!["apple", "red", "5"],
///     vec!["banana", "yellow", "3"],
///     vec!["apple", "red", "7"],
///     vec!["orange", "orange", "2"],
///     vec!["banana", "yellow", "4"],
/// ];
/// let counts = count_first_column(&data).unwrap();
/// assert_eq!(counts.get("apple"), Some(&2));
/// assert_eq!(counts.get("banana"), Some(&2));
/// assert_eq!(counts.get("orange"), Some(&1));
/// ```
pub fn count_first_column(data: &[Vec<&str>]) -> Result<HashMap<String, usize>, Box<dyn Error>> {
    if data.is_empty() {
        return Ok(HashMap::new());
    }

    // Extract the first column values
    let first_column: Vec<String> = data
        .iter()
        .filter_map(|row| row.first().map(|&val| val.to_string()))
        .collect();

    // Use colfreq to calculate frequencies
    let freq = Frequencies::from_vec(first_column);
    let counts = freq.frequencies();

    // Convert to HashMap for easier access
    let result: HashMap<String, usize> = counts
        .iter()
        .map(|(key, &count)| (key.clone(), count))
        .collect();

    Ok(result)
}

/// Alternative function that returns a sorted vector of (value, count) tuples
pub fn count_first_column_sorted(
    data: &[Vec<&str>],
) -> Result<Vec<(String, usize)>, Box<dyn Error>> {
    if data.is_empty() {
        return Ok(Vec::new());
    }

    let first_column: Vec<String> = data
        .iter()
        .filter_map(|row| row.first().map(|&val| val.to_string()))
        .collect();

    let freq = Frequencies::from_vec(first_column);
    let counts = freq.frequencies();

    let mut result: Vec<(String, usize)> = counts
        .iter()
        .map(|(key, &count)| (key.clone(), count))
        .collect();

    // Sort by count descending, then by value ascending
    result.sort_by(|a, b| {
        b.1.cmp(&a.1)
            .then_with(|| a.0.cmp(&b.0))
    });

    Ok(result)
}

