    // Initialize a vector to hold the count of missing entries for each column
    let mut missing_counts = vec![0; num_cols];
    let mut total_counts = vec![0; num_cols];

    // Iterate through each row in the dataset
    for row in df0 {
        for (col_index, value) in row.iter().enumerate() {
            total_counts[col_index] += 1;  // Count total entries
            if value.is_none() {
                missing_counts[col_index] += 1;  // Count missing entries
