pub fn remove_columns(mat0: &Matrix<i32>, columns_to_delete: &[usize]) -> Matrix<i32> {
    // Get the dimensions of the input matrix
    let rows = mat0.rows();
    let cols = mat0.cols();

    // Validate that all column indices are within bounds
    for &col_idx in columns_to_delete {
        assert!(
            col_idx < cols,
            "Column index {} is out of bounds. Matrix has {} columns.",
            col_idx,
            cols
        );
    }

    // Create a sorted copy of columns_to_delete for efficient checking
    let mut sorted_delete = columns_to_delete.to_vec();
    sorted_delete.sort();
    sorted_delete.dedup();

    // Calculate which columns to keep
    let keep_indices: Vec<usize> = (0..cols)
        .filter(|i| !sorted_delete.binary_search(i).is_ok())
        .collect();

    // Build the new matrix by selecting only the columns to keep
    let mut new_data = Vec::with_capacity(rows);

