/// Count occurrences of each unique value in specified columns from a tabular dataset.
///
/// # Arguments
/// * `df0` - A vector of vectors representing the tabular dataset (each inner vector is a row)
/// * `lst0` - A vector of column indices (0-based) to analyze
///
/// # Returns
/// A HashMap where keys are column indices and values are HashMaps mapping unique values to their counts
///
/// # Panics
/// Panics if any column index in lst0 is out of bounds for the dataset
pub fn count_column_values(
    df0: &[Vec<String>],
    lst0: &[usize],
) -> HashMap<usize, HashMap<String, usize>> {
    // Validate column indices
    if let Some(max_col) = lst0.iter().max() {
        if *max_col >= df0.first().map_or(0, |row| row.len()) {
            panic!("Column index {} is out of bounds", max_col);
        }
