            .ok_or("Failed to get column name")?;
        result.add_column(col_name)?;
    }

    // Compute element-wise difference
    for row_idx in 0..df0.nrows() {
        let mut row_values = Vec::new();

        for col_idx in 0..df0.ncols() {
            let val0 = df0.get(row_idx, col_idx)
                .ok_or("Failed to get value from df0")?;
            let val1 = df1.get(row_idx, col_idx)
                .ok_or("Failed to get value from df1")?;

