pub fn group_and_pivot<F>(df0: &DataFrame, var0: &str, agg_function: F) -> HashMap<String, f64>
where
    F: Fn(&[f64]) -> f64,
{
    // Get the grouping column
    let group_column = df0.get_column(var0)
        .expect("Column not found")
        .as_string()
