/// Changes the row index of a table to a two-level hierarchical index using values from two columns.
///
/// # Arguments
/// * `df0` - The input table with a flat row index
/// * `str0` - The name of the first column to use for the first level of the hierarchical index
/// * `str1` - The name of the second column to use for the second level of the hierarchical index
///
/// # Returns
/// A new table with a two-level hierarchical row index based on the specified columns
///
/// # Panics
/// Panics if either `str0` or `str1` columns don't exist in the table
pub fn set_hierarchical_index(
    df0: &Table,
    str0: &str,
    str1: &str,
) -> Table {
    // Verify that both columns exist
    if !df0.columns.contains_key(str0) {
        panic!("Column '{}' not found in table", str0);
    }
    if !df0.columns.contains_key(str1) {
        panic!("Column '{}' not found in table", str1);
    }

    // Get the values from the specified columns
    let col0 = &df0.columns[str0];
    let col1 = &df0.columns[str1];

    // Ensure both columns have the same length
    assert_eq!(
        col0.len(),
        col1.len(),
        "Columns '{}' and '{}' must have the same length",
        str0,
        str1
    );

    // Create the hierarchical index
    let mut hierarchical_index: Vec<(String, String)> = Vec::new();
    for i in 0..col0.len() {
        let val0 = col0[i].to_string();
        let val1 = col1[i].to_string();
        hierarchical_index.push((val0, val1));
    }

    // Create a new table with the hierarchical index
    let mut new_table = Table::new();

    // Set the hierarchical index
    new_table.index = multi_index::Index::Hierarchical(hierarchical_index);

    // Copy all columns except the ones used for the index
    for (col_name, col_data) in &df0.columns {
        if col_name != str0 && col_name != str1 {
            new_table.columns.insert(col_name.clone(), col_data.clone());
        }
    }

    new_table
}

