use table2d_filter::Table2D;

/// Filters rows from a 2D table based on multiple conditions.
///
/// # Arguments
/// * `table` - A Table2D containing the data to filter
/// * `conditions` - A vector of tuples (column_index, predicate_function)
///   where each predicate takes a cell value and returns true to keep the row
///
/// # Returns
/// A new Table2D containing only rows that satisfy ALL conditions
///
/// # Example
/// ```
/// let mut table = Table2D::new(2, 3);
/// table.set(0, 0, "Name").unwrap();
/// table.set(0, 1, "Age").unwrap();
/// table.set(1, 0, "Alice").unwrap();
/// table.set(1, 1, "30").unwrap();
/// table.set(2, 0, "Bob").unwrap();
/// table.set(2, 1, "25").unwrap();
///
/// let conditions = vec![
///     (1, |val: &str| val.parse::<u32>().unwrap_or(0) > 26),
/// ];
///
/// let filtered = filter_table_rows(&table, &conditions);
/// ```
fn filter_table_rows(
    table: &Table2D<String>,
    conditions: &[(usize, fn(&str) -> bool)],
) -> Table2D<String> {
    let rows = table.rows();
    let cols = table.cols();

    // Create a new table with same dimensions (will resize as needed)
    let mut filtered_table = Table2D::new(1, cols);

    // Copy header row (first row)
    if rows > 0 {
        for col in 0..cols {
            if let Some(header_val) = table.get(0, col) {
                let _ = filtered_table.set(0, col, header_val.clone());
            }
        }
    }

    let mut filtered_row_idx = 1;

    // Iterate through data rows (skip header at row 0)
    for row in 1..rows {
        let mut row_matches = true;

        // Check if row satisfies all conditions
        for (col_idx, predicate) in conditions.iter() {
            if *col_idx >= cols {
                row_matches = false;
                break;
            }

            if let Some(cell_value) = table.get(row, *col_idx) {
                if !predicate(cell_value) {
                    row_matches = false;
                    break;
                }
            } else {
                row_matches = false;
                break;
            }
        }

        // If row matches all conditions, copy it to filtered table
        if row_matches {
            // Expand filtered table if needed
            if filtered_row_idx >= filtered_table.rows() {
                filtered_table =
                    Table2D::new(filtered_row_idx + 1, cols);
                // Recopy all previous rows
                for prev_row in 0..filtered_row_idx {
                    for col in 0..cols {
                        if let Some(val) = table.get(prev_row, col) {
                            let _ = filtered_table.set(prev_row, col, val.clone());
                        }
                    }
                }
            }

            // Copy all columns from current row
            for col in 0..cols {
                if let Some(cell_value) = table.get(row, col) {
                    let _ = filtered_table.set(filtered_row_idx, col, cell_value.clone());
                }
            }

            filtered_row_idx += 1;
        }
    }

    filtered_table
}

