use sort_map_by_max::SortMapByMax; // Ensure this library is added to your Cargo.toml

fn reorder_by_max_value<K, V>(input: &SortMapByMax<K, Vec<V>>) -> SortMapByMax<K, Vec<V>>
where
    K: Clone + Ord,   // The key should be cloneable and orderable
    V: Ord + Copy,    // The value should be orderable and copyable
{
    let mut output: SortMapByMax<K, Vec<V>> = SortMapByMax::new();

    // Collect entries into a vector for sorting
