    // Sort by max values in descending order
    entries.sort_by(|(_, v1), (_, v2)| {
        v2.iter().copied().max().cmp(&v1.iter().copied().max())
    });

    // Rebuild the sorted map
    for (k, v) in entries {
        output.insert(k.clone(), v.clone());
    }

    output
}

