/// let result = semi_join_rows(&table_a, &table_b, 0);
/// assert_eq!(result, vec![vec!["Alice".to_string(), 30]]);
/// ```
pub fn semi_join_rows<A, B, K>(
    table_a: &[Vec<A>],
    table_b: &[Vec<B>],
    key_index: usize,
) -> Vec<Vec<A>>
where
    A: Clone + std::hash::Hash + Eq,
    B: Clone + std::hash::Hash + Eq,
