pub fn reset_and_convert_index(table: DataFrame) -> Result<DataFrame, Box<dyn std::error::Error>> {
    // Get the current index values
    let index = table.index().clone();

    // Create a new column with the original index values
    let original_index_col = match index {
        Index::Int64(idx) => {
            let values = idx.values();
            DataType::Int64.into_series("original_index", values)
        }
        Index::UInt64(idx) => {
