/// Reset the row index of `table` and convert each index level into a regular column.
/// 
/// Assumptions about the table-reindex API used here:
/// - Table is clonable or owned; this function takes ownership of `table`.
/// - `table.index()` returns an Option<IndexRef> where IndexRef provides:
///     - `names() -> Vec<String>`: the names of index levels (empty string or "index" if unnamed)
///     - `value_at(row: usize, level: usize) -> &ColumnValue`: value in the index for given row and level
/// - `table.height() -> usize`: number of rows
/// - `table.insert_column_at_front(name: String, values: Vec<ColumnValue>) -> Result<(), Error>`: inserts a column
/// - `table.clear_index() -> Result<(), Error>`: removes index metadata from the table
///
/// Adjust names to match the real crate API if necessary.
pub fn reset_index_to_columns(mut table: Table) -> Result<Table, Error> {
    // If there's no index, nothing to do.
    let index_ref = match table.index() {
        Some(idx) => idx,
        None => return Ok(table),
    };

    let index_names = index_ref.names();
    let nrows = table.height();

    // For each index level, construct a column of values (one value per row).
    // Insert new columns in front so the former index levels appear to the left of existing columns,
    // which is the common behavior of "reset_index" operations (like pandas.reset_index()).
    for (level_idx, level_name) in index_names.iter().enumerate() {
        let mut col_values: Vec<ColumnValue> = Vec::with_capacity(nrows);
