        // If the index level had no name, give it a default like "index" or "level_{i}"
        let name = if level_name.is_empty() {
            format!("level_{}", level_idx)
        } else {
            level_name.clone()
        };

        table.insert_column_at_front(name, col_values)?;
    }

    // Remove index metadata so the table becomes indexed by standard 0..n-1 row numbers.
    table.clear_index()?;

    Ok(table)
}
