/// Imputes missing values in a 2D dataset using column means.
/// This is a self-contained implementation without external dependencies.
pub fn impute_missing_with_column_mean(
    data: Vec<Vec<Option<f64>>>,
) -> Vec<Vec<f64>> {
    if data.is_empty() {
        return Vec::new();
    }

    let num_rows = data.len();
    let num_cols = data[0].len();

    // Calculate column means (ignoring None values)
    let mut column_means = vec![0.0; num_cols];
    let mut column_counts = vec![0; num_cols];

    for row in &data {
        for (col_idx, &value) in row.iter().enumerate() {
            if let Some(val) = value {
                column_means[col_idx] += val;
                column_counts[col_idx] += 1;
            }
        }
    }

    // Convert sums to means
    for (mean, &count) in column_means.iter_mut().zip(column_counts.iter()) {
        if count > 0 {
            *mean /= count as f64;
        }
    }

    // Create imputed dataset
    let mut imputed = vec![vec![0.0; num_cols]; num_rows];

    for (row_idx, row) in data.iter().enumerate() {
        for (col_idx, &value) in row.iter().enumerate() {
            imputed[row_idx][col_idx] = value.unwrap_or(column_means[col_idx]);
        }
    }

    imputed
}

