/// Updates a table by setting entries in `col_update` to `new_val` 
/// whenever the corresponding entry in `col_condition` is greater than `condition_val`.
///
/// # Arguments
/// * `table` - A mutable reference to the table to update
/// * `col_update` - The name of the column to update
/// * `new_val` - The new value to set in the update column
/// * `col_condition` - The name of the column to check the condition against
/// * `condition_val` - The threshold value for the condition
///
/// # Returns
/// * `Result<(), TableError>` - Ok if successful, Err if columns don't exist or types mismatch
///
/// # Example
/// ```ignore
/// use table_updater::Table;
/// 
/// let mut table = Table::new();
/// table.add_column("age", vec!["25", "30", "18", "35"]).unwrap();
/// table.add_column("status", vec!["active", "active", "active", "active"]).unwrap();
/// 
/// update_table_conditionally(&mut table, "status", "senior", "age", "30").unwrap();
/// ```
pub fn update_table_conditionally(
    table: &mut Table,
    col_update: &str,
    new_val: &str,
    col_condition: &str,
    condition_val: &str,
) -> Result<(), TableError> {
    // Get the number of rows in the table
    let row_count = table.row_count();

    // Get the condition column values
    let condition_values = table.get_column(col_condition)?;

    // Get the update column values as mutable
    let update_values = table.get_column_mut(col_update)?;

    // Parse the condition value for comparison
    let condition_threshold: f64 = condition_val.parse()
        .map_err(|_| TableError::InvalidValue(format!("Cannot parse '{}' as number", condition_val)))?;

    // Iterate through rows and update where condition is met
    for i in 0..row_count {
        // Parse the current condition value
        let current_value: f64 = condition_values[i].parse()
            .map_err(|_| TableError::InvalidValue(
                format!("Cannot parse '{}' as number at row {}", condition_values[i], i)
            ))?;

        // Check if condition is met
        if current_value > condition_threshold {
            update_values[i] = new_val.to_string();
        }
    }

    Ok(())
}

