use grouped_mean::GroupedMean;
use polars::prelude::*;

/// Compute the mean of each column in a DataFrame, grouped by values in var0 and var1
///
/// # Arguments
/// * `df0` - Input DataFrame to compute grouped means on
/// * `var0` - Name of the first grouping column
/// * `var1` - Name of the second grouping column
///
/// # Returns
/// * `Result<DataFrame>` - DataFrame with grouped means, or an error if something goes wrong
///
/// # Example
/// ```ignore
/// let df = df!(
///     "group1" => &["A", "A", "B", "B"],
///     "group2" => &["X", "Y", "X", "Y"],
///     "value1" => &[1.0, 2.0, 3.0, 4.0],
///     "value2" => &[5.0, 6.0, 7.0, 8.0]
/// ).unwrap();
///
/// let result = grouped_column_means(&df, "group1", "group2").unwrap();
/// println!("{:?}", result);
/// ```
pub fn grouped_column_means(
    df0: &DataFrame,
    var0: &str,
    var1: &str,
) -> Result<DataFrame, PolarsError> {
    // Validate that the grouping columns exist
    if !df0.get_column_names().contains(&var0) {
        return Err(PolarsError::ColumnNotFound(
            format!("Column '{}' not found in DataFrame", var0).into(),
        ));
    }
    if !df0.get_column_names().contains(&var1) {
        return Err(PolarsError::ColumnNotFound(
            format!("Column '{}' not found in DataFrame", var1).into(),
        ));
    }

    // Identify numeric columns (excluding grouping columns)
    let numeric_cols: Vec<&str> = df0
        .get_column_names()
        .iter()
        .filter(|&&name| name != var0 && name != var1)
        .filter(|&&name| {
            if let Ok(series) = df0.column(name) {
                series.dtype().is_numeric()
            } else {
                false
            }
        })
        .copied()
        .collect();

    if numeric_cols.is_empty() {
        return Err(PolarsError::ComputeError(
            "No numeric columns found to compute means".into(),
        ));
    }

    // Create a vector of column references for grouping
    let group_cols: Vec<&str> = vec![var0, var1];

    // Compute grouped means using grouped-mean library
    let result = df0
        .groupby(group_cols.as_slice())?
        .select(numeric_cols.as_slice())
        .mean()?;

    Ok(result)
}

