use std::collections::HashMap;
use std::hash::Hash;

/// A tiny, self-contained helper that provides the "entry-if-none" behavior
/// for HashMap<K, Option<V>>. This mimics what an "entry-if-none" helper
/// library would do: set the value for a key only when the current entry is `None`.
mod entry_if_none {
    use std::collections::HashMap;
    use std::hash::Hash;

    /// Extension trait for HashMap<K, Option<V>> providing set_if_none.
    pub trait EntryIfNone<K, V> {
        /// If the map contains `key` and its value is `None`, set it to `Some(value)`.
        /// If the key is absent or already `Some(_)`, do nothing.
        fn set_if_none(&mut self, key: K, value: V);
    }

    impl<K, V> EntryIfNone<K, V> for HashMap<K, Option<V>>
    where
        K: Eq + Hash,
    {
        fn set_if_none(&mut self, key: K, value: V) {
            if let Some(slot) = self.get_mut(&key) {
                if slot.is_none() {
                    *slot = Some(value);
                }
            }
        }
    }
}

