/// Iterates over each element of a two-dimensional input along the specified axis,
/// applying the given function to each element.
///
/// # Arguments
/// * `input` - A two-dimensional array/slice (e.g., Vec<Vec<T>> or &[&[T]])
/// * `axis` - The axis to iterate along (0 for rows, 1 for columns)
/// * `func` - The function to apply to each element
///
/// # Returns
/// A new two-dimensional structure with the function applied to each element
pub fn apply_along_axis<T, F, R>(
    input: &[Vec<T>],
    axis: usize,
    func: F,
) -> Vec<Vec<R>>
where
    T: Clone,
    F: Fn(&T) -> R,
{
    match axis {
        0 => {
            // Iterate along axis 0 (rows)
            input
                .iter()
                .map(|row| {
                    row.iter()
                        .map(|element| func(element))
                        .collect::<Vec<R>>()
                })
                .collect()
        }
        1 => {
            // Iterate along axis 1 (columns)
            if input.is_empty() {
                return Vec::new();
            }

            let num_cols = input[0].len();
            let mut result: Vec<Vec<R>> = Vec::new();

            for col_idx in 0..num_cols {
                let mut col_result: Vec<R> = Vec::new();
                for row in input {
                    if col_idx < row.len() {
                        col_result.push(func(&row[col_idx]));
                    }
                }
                result.push(col_result);
            }
            result
        }
        _ => panic!("Axis must be 0 or 1 for two-dimensional input"),
    }
}

