use unique_first::UniqueFirst;
use serde::{Serialize, Deserialize};
use std::collections::HashSet;

// Define a trait for our table rows that can be identified by a key
trait Identifiable {
    type Key: std::hash::Hash + Eq + Clone;

    fn key(&self) -> &Self::Key;
}

// Example implementation for a struct
#[derive(Debug, Serialize, Deserialize, Clone)]
struct Person {
    id: u32,
    name: String,
    age: u32,
}

impl Identifiable for Person {
    type Key = u32;

    fn key(&self) -> &Self::Key {
        &self.id
    }
}

// Generic function to deduplicate a table
fn deduplicate<T: Identifiable + Clone>(rows: Vec<T>) -> Vec<T> {
    let mut seen = HashSet::new();
    let mut result = Vec::new();

    for row in rows {
        if seen.insert(row.key().clone()) {
            result.push(row);
        }
    }

    result
}

// Alternative version using unique_first crate
fn deduplicate_with_unique_first<T: Identifiable + Clone>(rows: Vec<T>) -> Vec<T> {
    let mut unique_rows = UniqueFirst::new();

    for row in rows {
        unique_rows.insert(row.key().clone(), row);
    }

    unique_rows.into_values().collect()
}

fn main() {
    // Example usage
    let people = vec![
        Person { id: 1, name: "Alice".to_string(), age: 30 },
        Person { id: 2, name: "Bob".to_string(), age: 25 },
