        if stripped.parse::<f64>().is_err() {
            return Err(format!(
                "Row {}: Cannot convert '{}' to floating-point value after stripping currency symbol",
                row_idx, cell
            ));
        }

        // Update the cell with the stripped value
        row[penultimate_col] = stripped;
    }

    Ok(())
}

