use currency_table::CurrencyTable;

/// Strips the currency symbol from the penultimate column of a table
/// and converts its entries to floating-point values.
///
/// # Arguments
/// * `table` - A mutable reference to a CurrencyTable
///
/// # Returns
/// A Result containing a vector of f64 values, or an error message
fn strip_currency_and_convert(table: &mut CurrencyTable) -> Result<Vec<f64>, String> {
    // Get the number of columns
    let num_cols = table.num_columns()
        .map_err(|e| format!("Failed to get column count: {}", e))?;

    if num_cols < 2 {
        return Err("Table must have at least 2 columns".to_string());
    }

    // The penultimate column is at index num_cols - 2
    let penultimate_col_idx = num_cols - 2;

    // Get the number of rows
    let num_rows = table.num_rows()
        .map_err(|e| format!("Failed to get row count: {}", e))?;

    let mut result = Vec::new();

    // Iterate through each row in the penultimate column
    for row_idx in 0..num_rows {
        let cell = table.get_cell(row_idx, penultimate_col_idx)
            .map_err(|e| format!("Failed to get cell at ({}, {}): {}", row_idx, penultimate_col_idx, e))?;

        // Strip currency symbols and parse as f64
        let cleaned = cell
            .trim()
            .chars()
            .filter(|c| c.is_ascii_digit() || *c == '.' || *c == '-')
            .collect::<String>();

        let value = cleaned.parse::<f64>()
            .map_err(|e| format!("Failed to parse '{}' as f64: {}", cell, e))?;

        result.push(value);
    }

    Ok(result)
}

