///
/// Behavior for rows:
/// - If either A or sum is missing (null) -> A_perc is null.
/// - If sum is zero -> A_perc is null to avoid division-by-zero.
/// - Otherwise A_perc is Some(A / sum).
pub fn add_a_perc_column(table: &mut Table) -> Result<(), String> {
