    let mut a_perc = Vec::with_capacity(n_rows);
    for i in 0..n_rows {
        let a_val = a_col.get(i).and_then(|v| *v);   // Option<f64>
        let s_val = sum_col.get(i).and_then(|v| *v); // Option<f64>

        let perc = match (a_val, s_val) {
            (Some(a), Some(s)) if s != 0.0 => Some(a / s),
            _ => None, // either missing or division-by-zero -> null
        };
