use std::collections::HashMap;
use std::hash::Hash;

/// Assign an integer label to each element in `items` such that
/// identical elements receive the same label and labels reflect
/// the order in which elements first appear (labels start at 0).
///
/// Returns a Vec<usize> of labels in the same order as the input.
///
/// Example:
/// let labels = assign_order_labels(vec!["a", "b", "a", "c"]);
/// // labels == [0, 1, 0, 2]
pub fn assign_order_labels<T, I>(items: I) -> Vec<usize>
where
    T: Eq + Hash,
    I: IntoIterator<Item = T>,
{
    let mut map: HashMap<T, usize> = HashMap::new();
    let mut next_label: usize = 0;

    items
        .into_iter()
        .map(|item| {
            // Insert a new label if item not yet seen, otherwise reuse existing label
            *map.entry(item).or_insert_with(|| {
                let lab = next_label;
                next_label += 1;
                lab
            })
        })
        .collect()
}

