/// extension for `HashMap<K, Option<V>>`.
///
/// This inserts `Some(V::default())` when the key is missing or when the
/// stored value is `None`, and returns a mutable reference to the inner V.
mod map_entry_default {
    use super::*;
    pub trait MapEntryDefault<K, V> {
        fn entry_default(&mut self, key: K) -> &mut V;
    }

    impl<K, V> MapEntryDefault<K, V> for HashMap<K, Option<V>>
    where
        K: Eq + Hash,
        V: Default,
    {
        fn entry_default(&mut self, key: K) -> &mut V {
            use std::collections::hash_map::Entry;
            match self.entry(key) {
                Entry::Occupied(mut occ) => {
                    if occ.get().is_none() {
                        *occ.get_mut() = Some(V::default());
                    }
                    // Safe to unwrap because we ensured it's Some(...)
                    occ.get_mut().as_mut().unwrap()
                }
                Entry::Vacant(vac) => {
                    vac.insert(Some(V::default()));
                    // vac.into_mut() returns &mut Option<V>; unwrap to &mut V
                    vac.into_mut().as_mut().unwrap()
                }
            }
        }
    }
}

