use categorical_encoding::CategoricalEncoder;
use std::collections::HashMap;

/// Encodes categorical variables in var0 and var1 columns to unique integer codes
/// 
/// # Arguments
/// * `var0` - A vector of strings representing the first categorical variable
/// * `var1` - A vector of strings representing the second categorical variable
/// 
/// # Returns
/// A tuple containing two vectors of integers (lst0, lst1) with unique codes for each distinct value
/// 
/// # Example
/// ```
/// let var0 = vec!["a".to_string(), "b".to_string(), "a".to_string()];
/// let var1 = vec!["x".to_string(), "y".to_string(), "x".to_string()];
/// let (lst0, lst1) = encode_categorical_variables(var0, var1);
/// // lst0 could be [0, 1, 0]
/// // lst1 could be [0, 1, 0]
/// ```
fn encode_categorical_variables(
    var0: Vec<String>,
    var1: Vec<String>,
) -> (Vec<i32>, Vec<i32>) {
    let mut encoder0 = CategoricalEncoder::new();
    let mut encoder1 = CategoricalEncoder::new();

    // Fit and transform var0
    let lst0: Vec<i32> = var0
        .iter()
        .enumerate()
        .map(|(idx, value)| encoder0.fit_transform(idx, value) as i32)
        .collect();

    // Fit and transform var1
    let lst1: Vec<i32> = var1
        .iter()
        .enumerate()
        .map(|(idx, value)| encoder1.fit_transform(idx, value) as i32)
        .collect();

    (lst0, lst1)
}

/// Alternative implementation using HashMap for more control
fn encode_categorical_variables_hashmap(
    var0: Vec<String>,
    var1: Vec<String>,
) -> (Vec<i32>, Vec<i32>) {
    let mut map0: HashMap<String, i32> = HashMap::new();
    let mut map1: HashMap<String, i32> = HashMap::new();
    let mut counter0 = 0;
    let mut counter1 = 0;

    let lst0 = var0
        .iter()
        .map(|value| {
            if !map0.contains_key(value) {
                map0.insert(value.clone(), counter0);
                counter0 += 1;
            }
            *map0.get(value).unwrap()
