# Rust Function for Group-By-Sum Aggregation

```rust
use group_by_sum::GroupBySum;
use std::collections::HashMap;

/// Groups rows by a column value and sums all other columns
/// 
/// # Arguments
/// * `table` - A vector of rows, where each row is a HashMap<String, f64>
/// * `group_column` - The column name to group by (typically "var0")
/// 
/// # Returns
/// A vector of aggregated rows with summed values
fn group_and_sum(
    table: Vec<HashMap<String, f64>>,
    group_column: &str,
) -> Vec<HashMap<String, f64>> {
    if table.is_empty() {
        return Vec::new();
    }

    // Collect all column names except the grouping column
    let mut columns: Vec<String> = table[0]
        .keys()
        .filter(|col| col.as_str() != group_column)
        .cloned()
        .collect();
    columns.sort(); // For consistent output

    // Group rows by the grouping column value
    let mut grouped: HashMap<String, Vec<HashMap<String, f64>>> = HashMap::new();

    for row in table {
        if let Some(group_key) = row.get(group_column).map(|v| v.to_string()) {
            grouped.entry(group_key).or_insert_with(Vec::new).push(row);
        }
    }

    // Aggregate each group by summing all columns except the group column
    let mut result = Vec::new();

    for (group_value, rows) in grouped {
        let mut aggregated_row = HashMap::new();
        aggregated_row.insert(group_column.to_string(), group_value.parse::<f64>().unwrap_or(0.0));

        for col in &columns {
            let sum: f64 = rows.iter().filter_map(|row| row.get(col)).sum();
            aggregated_row.insert(col.clone(), sum);
        }

        result.push(aggregated_row);
    }

    result
}

