/// }.unwrap();
///
/// let imputed_df = impute_categorical_columns(df).unwrap();
/// println!("{}", imputed_df);
/// ```
pub fn impute_categorical_columns(
    df0: DataFrame,
) -> Result<DataFrame, Box<dyn std::error::Error>> {
    let mut imputer = CategoricalImputer::new();

    // Iterate through all columns and impute categorical columns
    let mut result_df = df0.clone();

    for col_name in df0.get_column_names() {
        let series = df0.column(col_name)?;

        // Check if column is string/categorical type
        if matches!(series.dtype(), DataType::String | DataType::Categorical(_, _, _)) {
            // Fit the imputer on the column (finds most frequent category)
            imputer.fit(series)?;

            // Transform the column (replaces null values with most frequent)
            let imputed_series = imputer.transform(series)?;

            // Replace the column in the dataframe
            result_df = result_df.with_columns([imputed_series.alias(col_name)])?;
        }
    }

    Ok(result_df)
}

