///     "value" => &[10, 20, 30, 40, 50]
/// ).unwrap();
///
/// let groups = group_by_column(&df, "var0");
/// ```
pub fn group_by_column(df0: &DataFrame, group_column: &str) -> HashMap<Series, DataFrame> {
    // Create a group-by object
    let mut group_by = df0.group_by(group_column);

    // Collect the groups into a HashMap
    let mut groups = HashMap::new();

    // Iterate through each group
    while let Some((key, group_df)) = group_by.next() {
        // Convert the key to a Series for consistent storage
        let key_series = Series::new(group_column, vec![key.clone()]);

        // Store the group DataFrame
        groups.insert(key_series, group_df);
    }

    groups
}
