/// Counts rows for each distinct combination of values across specified key columns
///
/// # Arguments
/// * `df` - The input DataFrame
/// * `key_columns` - Vector of column names to group by
///
/// # Returns
/// A new DataFrame with the group counts
///
/// # Example
/// ```
/// use polars::prelude::*;
/// use df_group_count::prelude::*;
///
/// let df = df!(
