/// * A HashMap where keys are unique values from var0 and values are counts of distinct var1 entries
pub fn count_distinct_var1_per_var0(df0: &DataFrame) -> HashMap<String, usize> {
    let mut result: HashMap<String, usize> = HashMap::new();

