# Rust Function for Computing Row and Column Means

```rust
use row_col_mean::{RowMean, ColMean};

/// Computes mean values for specified rows and columns from a 2D data table.
///
/// # Arguments
/// * `data` - A 2D vector representing the data table
/// * `row_indices` - Vector of row indices for which to compute means
/// * `col_indices` - Vector of column indices for which to compute means
///
/// # Returns
/// A tuple containing:
/// * `row_means` - Vector of mean values for specified rows
/// * `col_means` - Vector of mean values for specified columns
///
/// # Panics
/// Panics if row or column indices are out of bounds
pub fn compute_row_col_means(
    data: &[Vec<f64>],
    row_indices: &[usize],
    col_indices: &[usize],
) -> (Vec<f64>, Vec<f64>) {
    if data.is_empty() {
        return (vec![], vec![]);
    }

    let num_cols = data[0].len();

    // Validate indices
    for &row_idx in row_indices {
        assert!(
            row_idx < data.len(),
            "Row index {} out of bounds (max: {})",
            row_idx,
            data.len() - 1
        );
    }

    for &col_idx in col_indices {
        assert!(
            col_idx < num_cols,
            "Column index {} out of bounds (max: {})",
            col_idx,
            num_cols - 1
        );
    }

    // Compute row means
    let row_means: Vec<f64> = row_indices
        .iter()
        .map(|&row_idx| {
            let row = &data[row_idx];
            let sum: f64 = row.iter().sum();
            sum / row.len() as f64
        })
        .collect();

    // Compute column means
    let col_means: Vec<f64> = col_indices
        .iter()
        .map(|&col_idx| {
            let sum: f64 = data.iter().map(|row| row[col_idx]).sum();
            sum / data.len() as f64
        })
        .collect();

    (row_means, col_means)
}

