use map_value_sorter::sort_by_value;
use std::collections::HashMap;

fn sort_mapping<K: std::hash::Hash + Eq + Clone, V: Ord>(
    mapping: &HashMap<K, V>,
) -> Vec<(K, V, usize)> {
    // Collect the original mapping into a Vec of (key, value) pairs with their original indices
    let original: Vec<(K, V, usize)> = mapping
        .iter()
        .enumerate()
        .map(|(index, (key, value))| (key.clone(), value.clone(), index))
        .collect();

