///
/// # Returns
/// * A new 2D array with values scaled between 0 and 1 for each column
///
/// # Panics
/// * If any column has all identical values (min == max), the column will contain NaN values
pub fn normalize_columns_to_01(df0: &Array2<f64>) -> Array2<f64> {
    // Create a mutable copy to work with
    let mut result = df0.clone();

    // Get the number of columns
    let ncols = df0.ncols();

    // Normalize each column independently
    for col in 0..ncols {
        // Extract the column as a view
        let column = df0.column(col);

        // Find min and max for this column
        let min_val = column.iter().cloned().fold(f64::INFINITY, f64::min);
        let max_val = column.iter().cloned().fold(f64::NEG_INFINITY, f64::max);

        // Calculate range
        let range = max_val - min_val;

        // Apply min-max normalization to each element in the column
        if range > 0.0 {
            for val in result.column_mut(col).iter_mut() {
                *val = (*val - min_val) / range;
            }
        } else {
            // If all values are the same, set to 0.5 (or handle as needed)
            // This avoids division by zero
            for val in result.column_mut(col).iter_mut() {
                *val = 0.5;
            }
        }
    }

    result
}

