    // Convert back to DataFrame
    let schema = df0.schema();
    let mut new_df = DataFrame::new(schema.clone())?;

    for row_vec in unique_rows {
        let mut new_row = Row::new_empty(schema.len())?;
        for (i, col_name) in schema.columns().iter().enumerate() {
            let col_idx = schema.get_column_index(col_name)?;
