fn remove_consecutive_duplicate_rows(df0: DataFrame) -> Result<DataFrame> {
    // Convert DataFrame to a vector of rows for deduplication
    let mut rows: Vec<Vec<String>> = df0
        .iter()
        .map(|series| {
            series
                .iter()
                .map(|val| val.to_string())
                .collect::<Vec<String>>()
        })
        .collect();

    // Transpose to get rows instead of columns
    if rows.is_empty() {
        return Ok(df0);
    }

    let n_rows = rows[0].len();
    let mut transposed_rows: Vec<Vec<String>> = vec![vec![]; n_rows];

    for col in rows {
        for (i, val) in col.iter().enumerate() {
            transposed_rows[i].push(val.clone());
        }
