        return Err(format!("Denominator column '{}' not found in DataFrame", column_name0));
    }

    // Validate numerator columns exist
    for &col in columns_list0 {
        if !df.has_column(col) {
            return Err(format!("Column '{}' not found in DataFrame", col));
        }
    }

    let nrows = df.nrows();

    for row in 0..nrows {
        // Get denominator for this row
