/// Counts occurrences of each tuple in a sequence with optional filtering, ordering, and limiting
///
/// # Arguments
/// * `items` - The input sequence of tuples to count
/// * `filter` - Optional filter function to apply to each tuple before counting
/// * `order` - Optional ordering strategy (default: by count descending)
/// * `limit` - Maximum number of results to return (None for no limit)
///
/// # Returns
/// A vector of tuples containing (tuple, count) pairs, ordered and limited as specified
pub fn count_tuples<T, F, O>(
    items: impl IntoIterator<Item = T>,
    filter: Option<F>,
    order: Option<O>,
    limit: Option<usize>,
) -> Vec<(T, usize)>
where
    T: std::hash::Hash + Eq + Clone,
    F: Fn(&T) -> bool,
    O: Fn(&(T, usize), &(T, usize)) -> std::cmp::Ordering,
{
    // Apply filtering if provided
    let filtered_items = if let Some(f) = filter {
        items.into_iter().filter(|item| f(item))
    } else {
        items.into_iter()
    };

    // Count occurrences
    let mut counter = Counter::new();
    for item in filtered_items {
        counter.add(&item);
    }

    // Convert to HashMap for easier ordering
    let mut counts: HashMap<T, usize> = counter.into_iter()
        .map(|(k, v)| (k.clone(), v))
        .collect();

    // Determine ordering strategy
    let mut ordering = match order {
        Some(o) => o,
        None => |a, b| b.1.cmp(&a.1), // Default: order by count descending
    };

    // Convert to Vec for sorting
    let mut result: Vec<(T, usize)> = counts.into_iter().collect();

    // Sort according to the specified ordering
    result.sort_by(|a, b| ordering(a, b));

    // Apply limit if specified
    if let Some(limit) = limit {
        result.truncate(limit);
    }

    result
