/// * `order`: An optional ordering function to apply to the results.
/// * `limit`: An optional limit to apply to the results.
///
/// # Returns
///
/// A `HashMap` containing the tuples as keys and their counts as values.
pub fn count_tuples<T, F, O, L>(sequence: Vec<T>, filter: Option<F>, order: Option<O>, limit: Option<L>) -> HashMap<T, usize>
where
    T: Eq + std::hash::Hash + Clone,
    F: Fn(&T) -> bool,
    O: Fn(&T, &T) -> std::cmp::Ordering,
    L: std::ops::Add<usize, Output = usize>,
{
    let mut counter = TupleCounter::new();
    for tuple in sequence {
        counter.add(tuple.clone());
    }

    let mut counts: HashMap<T, usize> = counter.into_iter().collect();

    // Apply filter
    if let Some(filter) = filter {
        counts.retain(|k, _| filter(&k));
    }

    // Apply order
    if let Some(order) = order {
        let mut sorted_counts: Vec<(T, usize)> = counts.into_iter().collect();
        sorted_counts.sort_by(|a, b| order(&a.0, &b.0));
        counts = sorted_counts.into_iter().collect();
    }

    // Apply limit
    if let Some(limit) = limit {
        let mut limited_counts: HashMap<T, usize> = HashMap::new();
        let mut count = 0;
        for (k, v) in counts {
            limited_counts.insert(k, v);
            count += 1;
            if count >= limit + 0 {
                break;
            }
        }
        counts = limited_counts;
    }

    counts
