/// Efficient even when B is very large.
fn sort_by_order_list<T: Clone + Eq + std::hash::Hash>(a: &[T], b: &[T]) -> Vec<T> {
    // Create a HashMap for O(1) lookup of positions in B
    let position_map: HashMap<&T, usize> = b.iter()
        .enumerate()
        .map(|(i, item)| (item, i))
        .collect();

    // Separate items into those in B and those not in B
    let mut in_b: Vec<&T> = Vec::new();
    let mut not_in_b: Vec<&T> = Vec::new();

    for item in a {
        if position_map.contains_key(item) {
            in_b.push(item);
        } else {
            not_in_b.push(item);
        }
    }

    // Sort items in B according to their position in B
    in_b.sort_by(|x, y| {
        let pos_x = position_map.get(x).unwrap();
        let pos_y = position_map.get(y).unwrap();
        pos_x.cmp(pos_y)
    });

    // Combine: items not in B first, then sorted items from B
    let result: Vec<T> = not_in_b.into_iter()
        .chain(in_b.into_iter())
        .cloned()
        .collect();

    result
