/// use std::error::Error;
///
/// fn main() -> Result<(), Box<dyn Error>> {
///     let mut data = DataTable::new();
///     data.add_column("name", vec!["Alice", "Bob", "Charlie", "David"])?;
///     data.add_column("age", vec![25, 30, 35, 40])?;
///     data.add_column("salary", vec![50000.0, 60000.0, 70000.0, 80000.0])?;
///     
///     // Sum salaries for people older than 30
///     let sum = conditional_sum(&data, "salary", "age", 30.0, ">")?;
///     println!("Sum of salaries for people older than 30: {}", sum);
///     
///     Ok(())
/// }
/// ```
pub fn conditional_sum(
    data: &DataTable,
    column_name: &str,
    condition_column: &str,
    condition_value: f64,
    operator: &str,
) -> Result<f64, Box<dyn Error>> {
    // Get the column to sum
    let sum_column = data.get_column(column_name)
        .ok_or_else(|| format!("Column '{}' not found", column_name))?;

    // Get the condition column
    let condition_col = data.get_column(condition_column)
        .ok_or_else(|| format!("Condition column '{}' not found", condition_column))?;

    // Create the filter based on the operator
    let filter = match operator {
        "==" => Filter::new(condition_column, Value::Float(condition_value), |a, b| a == b),
        "!=" => Filter::new(condition_column, Value::Float(condition_value), |a, b| a != b),
        ">" => Filter::new(condition_column, Value::Float(condition_value), |a, b| a > b),
        "<" => Filter::new(condition_column, Value::Float(condition_value), |a, b| a < b),
        ">=" => Filter::new(condition_column, Value::Float(condition_value), |a, b| a >= b),
        "<=" => Filter::new(condition_column, Value::Float(condition_value), |a, b| a <= b),
        _ => return Err(format!("Unsupported operator: '{}'. Use one of: ==, !=, >, <, >=, <=", operator).into()),
    };

    // Apply the filter and calculate the sum
    let mut sum = 0.0;
    let filtered_data = data.filter(&filter)?;

    for row in filtered_data.iter_rows() {
        if let Some(value) = row.get(column_name) {
            match value {
                Value::Float(f) => sum += f,
                Value::Int(i) => sum += *i as f64,
                _ => return Err(format!("Column '{}' contains non-numeric values", column_name).into()),
            }
        }
    }

    Ok(sum)
}

