/// * `condition` - A filter condition string (e.g., "age > 25")
/// * `sum_column` - The name of the column to sum
///
/// # Returns
/// * `Result<f64, String>` - The sum value or an error message
///
/// # Example
/// ```
/// let mut data = vec![];
/// let mut row1 = HashMap::new();
/// row1.insert("name".to_string(), "Alice".to_string());
/// row1.insert("age".to_string(), "30".to_string());
/// row1.insert("salary".to_string(), "50000".to_string());
