fn sort_keys_by_values(dict: &std::collections::HashMap<String, i32>) -> (Vec<String>, Vec<usize>) {
    // Convert the HashMap to a Vec of tuples (key, value, original_index)
    let mut indexed_values: Vec<(String, i32, usize)> = dict.iter()
        .enumerate()
        .map(|(idx, (key, value))| (key.clone(), *value, idx))
