///     (1, "a"),
///     (1, "world"),
///     (2, "test"),
///     (3, "hi"),
///     (3, "hello"),
/// ]);
/// ```
pub fn sort_by_first_then_second_length<T, U>(items: &mut [(T, U)])
where
    T: Ord,
    U: AsRef<str>, // Works for String, &str, etc.
{
    items.tuple_sort_by(|a, b| {
        // First compare by the first element
        match a.0.cmp(&b.0) {
            // If first elements are equal, compare by length of second element
            std::cmp::Ordering::Equal => a.1.as_ref().len().cmp(&b.1.as_ref().len()),
            other => other,
        }
    });
}

// Alternative version that works with any type that has a .len() method
pub fn sort_by_first_then_second_length_generic<T, U>(items: &mut [(T, U)])
where
    T: Ord,
    U: HasLength,
{
    items.tuple_sort_by(|a, b| {
        match a.0.cmp(&b.0) {
            std::cmp::Ordering::Equal => a.1.len().cmp(&b.1.len()),
            other => other,
        }
    });
}

/// Trait for types that have a length
pub trait HasLength {
    fn len(&self) -> usize;
}

// Implement HasLength for common types
