    fn len(&self) -> usize {
        self.len()
    }
}

impl HasLength for &str {
    fn len(&self) -> usize {
        str::len(self)
    }
}

impl<T> HasLength for Vec<T> {
    fn len(&self) -> usize {
        self.len()
    }
}

impl<T> HasLength for &[T] {
    fn len(&self) -> usize {
        (*self).len()
    }
}

