use freqsort::FrequencySort;
use std::collections::HashMap;

/// Reorders elements of a collection based on their frequency of occurrence.
/// Elements that appear more frequently come first. Elements with the same
/// frequency maintain their relative order from the original collection.
///
/// # Arguments
/// * `collection` - A slice of items to be reordered
///
/// # Returns
/// A Vec containing all elements reordered by frequency (most frequent first)
///
/// # Example
/// ```
/// let input = vec![3, 1, 2, 1, 3, 1, 2, 3, 3];
/// let result = frequency_sort(&input);
/// // 3 appears 4 times, 1 appears 3 times, 2 appears 2 times
/// // Result: [3, 3, 3, 3, 1, 1, 1, 2, 2]
/// ```
pub fn frequency_sort<T: Clone + Eq + std::hash::Hash>(collection: &[T]) -> Vec<T> {
    // Count frequencies of each element
    let mut frequency_map: HashMap<&T, usize> = HashMap::new();
    for item in collection {
        *frequency_map.entry(item).or_insert(0) += 1;
    }

    // Create a vector of (frequency, original_index, item) tuples for stable sorting
    let mut items_with_freq: Vec<(usize, usize, &T)> = collection
        .iter()
        .enumerate()
        .map(|(index, item)| {
            let freq = *frequency_map.get(item).unwrap_or(&0);
            // Negate frequency for descending order (most frequent first)
            (usize::MAX - freq, index, item)
        })
        .collect();

    // Sort by frequency (descending), then by original index (stable)
    items_with_freq.sort();

    // Extract the items in sorted order
    items_with_freq
        .into_iter()
        .map(|(_, _, item)| item.clone())
        .collect()
}

/// Alternative implementation using the freqsort crate's FrequencySort trait
pub fn frequency_sort_freqsort<T: Clone + Eq + std::hash::Hash>(collection: &[T]) -> Vec<T> {
    collection.frequency_sort()
}

