/// Groups rows of a DataFrame by values in a specified column, computes sums of all other columns,
/// and returns a new DataFrame with the grouping column as an ordinary column (not an index).
///
/// # Arguments
/// * `df0` - The input DataFrame to be grouped
/// * `column_name0` - The name of the column to group by
///
/// # Returns
/// * A new DataFrame with grouped and summed data, where column_name0 remains an ordinary column
///
/// # Panics
/// * If column_name0 doesn't exist in the DataFrame
/// * If any non-grouping column contains non-numeric data
pub fn group_and_sum(df0: &DataFrame, column_name0: &str) -> DataFrame {
    // Get the index of the grouping column
    let group_col_idx = df0
        .columns
        .iter()
        .position(|col| col.name == column_name0)
        .expect("Column not found in DataFrame");

    // Collect all other column indices (non-grouping columns)
    let other_col_indices: Vec<usize> = (0..df0.columns.len())
        .filter(|&i| i != group_col_idx)
        .collect();

    // Create a HashMap to store sums for each group
    let mut group_sums: HashMap<String, Vec<f64>> = HashMap::new();

    // Iterate through each row in the DataFrame
    for row in &df0.rows {
        let group_key = row[group_col_idx].to_string();
        let entry = group_sums.entry(group_key).or_insert_with(|| {
            vec![0.0; other_col_indices.len()]
        });

        // Add values from this row to the group sums
        for (i, &col_idx) in other_col_indices.iter().enumerate() {
            if let Ok(value) = row[col_idx].parse::<f64>() {
                entry[i] += value;
            }
        }
    }

    // Build the result DataFrame
    let mut result_df = DataFrame {
        columns: Vec::new(),
        rows: Vec::new(),
    };

    // Add the grouping column first
    result_df.columns.push(df0.columns[group_col_idx].clone());

    // Add all other columns (keeping their original names)
    for &col_idx in &other_col_indices {
        result_df.columns.push(df0.columns[col_idx].clone());
    }

    // Add the grouped and summed rows
    for (group_key, sums) in group_sums {
        let mut row = vec![group_key];
        for sum_value in sums {
            row.push(sum_value.to_string());
        }
