        for (s, &idx) in col_strings.iter().zip(indices.iter()) {
            mapping.entry(s.clone()).or_insert(idx);
        }
    }

    // Replace the column in the DataFrame with the encoded numeric column.
    df0.cols.insert(col0.to_string(), Column::Usize(indices));

    Ok(mapping)
