use categorical_indexer::CategoricalIndexer;
use std::collections::HashMap;

/// Maps categorical values in a column to unique integer indices.
/// 
/// # Arguments
/// * `df0` - A vector of vectors representing the data table
/// * `col_index` - The index of the column to categorize (0-based)
/// 
/// # Returns
/// A tuple containing:
/// * The modified data table with categorical values replaced by indices
/// * A HashMap mapping original categories to their integer indices
/// 
/// # Example
/// ```
/// let df0 = vec![
///     vec!["apple", "red", "5"],
///     vec!["banana", "yellow", "3"],
///     vec!["apple", "red", "7"],
///     vec!["orange", "orange", "4"],
/// ];
/// let (indexed_df, mapping) = categorize_column(df0, 0);
/// ```
fn categorize_column(
    mut df0: Vec<Vec<String>>,
    col_index: usize,
) -> (Vec<Vec<String>>, HashMap<String, usize>) {
    // Create a CategoricalIndexer instance
    let mut indexer = CategoricalIndexer::new();

    // First pass: collect all unique categories and build the indexer
    for row in &df0 {
        if col_index < row.len() {
            let category = &row[col_index];
            indexer.insert(category.clone());
        }
    }

    // Create a mapping from original categories to indices
    let mut category_to_index: HashMap<String, usize> = HashMap::new();
    for (idx, category) in indexer.categories().iter().enumerate() {
        category_to_index.insert(category.clone(), idx);
    }

    // Second pass: replace categorical values with their indices
    for row in &mut df0 {
        if col_index < row.len() {
            let category = &row[col_index];
            if let Some(&index) = category_to_index.get(category) {
                row[col_index] = index.to_string();
            }
        }
    }

    (df0, category_to_index)
}

