/// Sorts a list of items (represented as key-value maps) in ascending order
/// by their 'weight' field, breaking ties with the 'factor' field.
///
/// # Arguments
/// * `items` - A vector of HashMaps with string keys and numeric values
///
/// # Returns
/// A sorted vector of the items
///
/// # Example
/// ```
/// let mut items = vec![
///     {
///         let mut m = HashMap::new();
///         m.insert("weight".to_string(), 10);
///         m.insert("factor".to_string(), 5);
///         m
///     },
///     {
///         let mut m = HashMap::new();
///         m.insert("weight".to_string(), 10);
///         m.insert("factor".to_string(), 3);
///         m
///     },
///     {
///         let mut m = HashMap::new();
///         m.insert("weight".to_string(), 5);
///         m.insert("factor".to_string(), 8);
///         m
///     },
/// ];
///
/// let sorted = sort_by_weight_and_factor(items);
/// ```
fn sort_by_weight_and_factor(
    mut items: Vec<HashMap<String, i32>>,
) -> Vec<HashMap<String, i32>> {
    items.sort_by(|a, b| {
        let weight_a = a.get("weight").copied().unwrap_or(0);
        let weight_b = b.get("weight").copied().unwrap_or(0);

        // Primary sort: by weight
        match weight_a.cmp(&weight_b) {
            std::cmp::Ordering::Equal => {
                // Secondary sort: by factor (on tie)
                let factor_a = a.get("factor").copied().unwrap_or(0);
                let factor_b = b.get("factor").copied().unwrap_or(0);
                factor_a.cmp(&factor_b)
            }
            other => other,
        }
    });

    items
}

