```rust
use tuple_order::TupleOrder;

/// Reorders lst0 according to the order specified in lst1.
/// 
/// # Arguments
/// * `lst0` - A vector of tuples to be reordered
/// * `lst1` - A vector defining the desired ordering (typically indices or keys)
/// 
/// # Returns
/// A vector of tuples from lst0, reordered according to lst1
/// 
/// # Example
/// ```
/// let lst0 = vec![(1, "a"), (2, "b"), (3, "c")];
/// let lst1 = vec![2, 0, 1];  // Reorder to: index 2, then 0, then 1
/// let result = reorder_tuples(lst0, lst1);
/// assert_eq!(result, vec![(3, "c"), (1, "a"), (2, "b")]);
/// ```
fn reorder_tuples<T: Clone>(lst0: Vec<T>, lst1: Vec<usize>) -> Vec<T> {
    lst1.iter()
        .filter_map(|&idx| lst0.get(idx).cloned())
        .collect()
}

// Alternative version that works with references (more efficient for large tuples)
fn reorder_tuples_ref<'a, T>(lst0: &'a [T], lst1: &[usize]) -> Vec<&'a T> {
    lst1.iter()
        .filter_map(|&idx| lst0.get(idx))
        .collect()
}

// Example usage
fn main() {
    // Example 1: Tuples with integers and strings
    let lst0 = vec![(1, "a"), (2, "b"), (3, "c"), (4, "d")];
    let lst1 = vec![3, 1, 0, 2];
    let result = reorder_tuples(lst0.clone(), lst1);
