use std::collections::HashMap;
use std::hash::Hash;

/// Reorder `lst0` in-place so its elements follow the order specified by `lst1`.
/// 
/// - T must implement Eq + Hash + Clone (tuples do if their components do).
/// - Elements present in `lst1` are ordered by their index in `lst1`.
/// - Elements not present in `lst1` are pushed to the end, preserving relative order.
/// 
/// Example:
/// let mut lst0 = vec![(2, 'b'), (1, 'a'), (3, 'c'), (1, 'b')];
/// let lst1 = vec![(1, 'a'), (1, 'b'), (2, 'b'), (3, 'c')];
/// reorder_by_reference(&mut lst0, &lst1);
/// assert_eq!(lst0, vec![(1,'a'), (1,'b'), (2,'b'), (3,'c')]);
pub fn reorder_by_reference<T>(lst0: &mut [T], lst1: &[T])
where
    T: Eq + Hash + Clone,
{
    // Map each element of lst1 to its rank (index).
    let rank: HashMap<T, usize> = lst1
        .iter()
        .cloned()
        .enumerate()
        .map(|(i, v)| (v, i))
        .collect();

    // Sort lst0 by the rank; use usize::MAX for items not in lst1 so they go to the end.
    // sort_by_key is stable, so relative order of equal keys (including missing ones) is preserved.
    lst0.sort_by_key(|item| rank.get(item).copied().unwrap_or(usize::MAX));
}

