use std::collections::HashSet;

/// Remove rows from `table` that are duplicates with respect to the columns listed in `cols`.
///
/// - `table` is a slice of rows, each row is a Vec<String>.
/// - `cols` is a slice of 0-based column indices to compare.
///
/// Keeps the first row encountered for each distinct combination of values in `cols`.
/// Out-of-range column indices are treated as empty strings for deduplication purposes.
///
/// Returns a new Vec<Vec<String>> containing the filtered rows.
///
/// Example:
/// let table = vec![
///     vec!["a".to_string(), "1".to_string()],
///     vec!["b".to_string(), "1".to_string()],
///     vec!["a".to_string(), "2".to_string()],
///     vec!["a".to_string(), "1".to_string()],
/// ];
/// let filtered = remove_duplicate_rows_by_columns(&table, &[0, 1]);
/// // filtered will contain rows 0,1,2 (row 3 is duplicate of row 0 on columns 0 and 1)
pub fn remove_duplicate_rows_by_columns(table: &[Vec<String>], cols: &[usize]) -> Vec<Vec<String>> {
    // Use a HashSet of keys (Vec<&str>) to remember seen combinations of column values.
    // The &str references borrow from the input `table` so the HashSet only lives
    // during the function call; we clone rows into the result as owned Strings.
    let mut seen: HashSet<Vec<&str>> = HashSet::with_capacity(table.len());
    let mut result: Vec<Vec<String>> = Vec::with_capacity(table.len());

    for row in table {
        // build key: values from the selected columns (use "" if index out of range)
        let key: Vec<&str> = cols
            .iter()
            .map(|&ci| row.get(ci).map(|s| s.as_str()).unwrap_or(""))
            .collect();

        // insert returns true iff the key was not present
        if seen.insert(key) {
            result.push(row.clone());
        }
    }

    result
}

