    dict0.insert("apples", vec![1.5, 2.5, 3.0]);
    dict0.insert("oranges", vec![10.0, 20.0]);
    dict0.insert("bananas", vec![5.0]);

    let result = compute_keyed_averages(dict0);

    for (key, avg) in result.iter() {
        println!("{}: {}", key, avg);
    }
}
