/// Find all case-insensitive occurrences of `pattern` within `text` across multiple lines.
/// Returns a vector of starting byte indices where matches are found.
///
/// # Arguments
/// * `pattern` - The substring to search for (case-insensitive)
/// * `text` - The text to search within (can contain multiple lines)
///
/// # Returns
/// * `Vec<usize>` - Sorted list of starting byte positions of all matches
///
/// # Example
/// ```
/// let text = "Hello World\nhello again\nHELLO there";
/// let matches = find_all_ci("hello", text);
/// assert_eq!(matches, vec![0, 12, 24]);
/// ```
pub fn find_all_ci(pattern: &str, text: &str) -> Vec<usize> {
    if pattern.is_empty() || text.is_empty() {
        return Vec::new();
