/// // Result will have id1 summed and id2 with its values
/// ```
fn aggregate_rows_by_sum(df0: HashMap<String, Vec<f64>>) -> HashMap<String, Vec<f64>> {
    let mut aggregator = Aggregator::new();

    // Process each row in the dataframe
    for (identifier, values) in df0.iter() {
