    if weight_sum == 0.0 {
        return Err("Sum of weights cannot be zero".to_string());
    }

    // Create a WeightedAverage and add all value-weight pairs
    let mut weighted_avg = WeightedAverage::new();

    for (&value, &weight) in col_values.iter().zip(col_weights.iter()) {
