        let mut df0 = vec![
            vec!["Alice".to_string(), "  ".to_string(), "Engineer".to_string()],
            vec!["\t".to_string(), "Bob".to_string(), "Manager".to_string()],
            vec!["Charlie".to_string(), "Data Scientist".to_string(), "   \n".to_string()],
