use std::collections::{HashMap, HashSet};
use std::hash::Hash;

/// Return a new `HashMap` containing only entries from `source` whose keys
/// appear in `keys`.
///
/// - `source` can be any IntoIterator<Item = (K, V)> (for example a `HashMap`
///   or a `Vec<(K,V)>`).
/// - `keys` is any iterator of keys to keep (duplicates are ignored).
///
/// Complexity: O(n + m) where n = number of entries in `source` and
/// m = number of keys in `keys`.
pub fn filter_kv_by_keys<K, V, S, T, I>(source: T, keys: I) -> HashMap<K, V>
where
    K: Eq + Hash + Clone,
    V: Clone,
    T: IntoIterator<Item = (K, V)>,
    I: IntoIterator<Item = K>,
{
    let key_set: HashSet<K> = keys.into_iter().collect();
    source
        .into_iter()
        .filter(|(k, _v)| key_set.contains(k))
        .collect()
}

