/// reorder_by_reference(&mut lst0, &lst1);
/// assert_eq!(lst0, vec!["apple", "banana", "cherry", "date"]);
/// ```
pub fn reorder_by_reference<T: Clone + std::hash::Hash + Eq>(lst0: &mut Vec<T>, lst1: &[T]) {
