fn extract_context(text: &str, search_term: &str, num_words: usize) -> Option<(Vec<Option<String>>, Vec<Option<String>>)> {
    // Create a context extractor with the specified number of words before and after
    let context = Context::new(text, num_words, num_words);

    // Find the search term and extract its context
    let results: Vec<_> = context
        .extract(search_term)
        .collect();

    if results.is_empty() {
        return None;
    }

    // Take the first occurrence
    let (before, _found, after) = &results[0];

    // Convert to Vec<Option<String>>, padding with None where needed
    let mut before_words: Vec<Option<String>> = before
        .iter()
        .map(|w| Some(w.to_string()))
        .collect();

    let mut after_words: Vec<Option<String>> = after
        .iter()
        .map(|w| Some(w.to_string()))
        .collect();

    // Pad with None if we have fewer words than requested
    while before_words.len() < num_words {
        before_words.insert(0, None);
    }

    while after_words.len() < num_words {
        after_words.push(None);
    }

