/// returning only rows where the "value" column equals zero.
///
/// # Arguments
/// * `table` - A vector of HashMaps representing table rows
///
/// # Returns
/// A vector of HashMaps containing only rows from groups where value == 0
pub fn filter_table_by_zero_value(
    table: Vec<HashMap<String, String>>,
) -> Vec<HashMap<String, String>> {
    filter_groups(
        table,
        vec!["var0".to_string(), "var1".to_string()],
        |row| {
            row.get("value")
                .and_then(|v| v.parse::<i32>().ok())
                .map(|val| val == 0)
                .unwrap_or(false)
        },
    )
}

